function hearthTimePeriodFromDate(date = new Date()){
  const hour = date.getHours();
  if(hour >= 5 && hour < 11) return 'morning';
  if(hour >= 11 && hour < 17) return 'afternoon';
  if(hour >= 17 && hour < 21) return 'evening';
  return 'night';
}

function applyHearthTimePeriod(){
  if(!hearth) return '';
  const override = (prototypeParams.get('timePeriod') || '').trim().toLowerCase();
  const allowed = new Set(['morning','afternoon','evening','night']);
  const period = allowed.has(override) ? override : hearthTimePeriodFromDate();
  hearth.dataset.timePeriod = period;
  return period;
}

function normalizeTimelineEmail(value = ''){
  const email = String(value || '').trim().toLowerCase();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : '';
}

function calendarEventAttendees(event = {}){
  return Array.isArray(event.attendees) ? event.attendees.filter(Boolean) : [];
}

function calendarAttendeeEmail(attendee = {}){
  return String(attendee.email || attendee.address || attendee.emailAddress?.address || attendee.mail || '').trim().toLowerCase();
}

function calendarAttendeeDisplayName(attendee = {}){
  return String(attendee.name || attendee.displayName || attendee.emailAddress?.name || attendee.label || '').trim();
}

function calendarAttendeeLabel(attendee = {}){
  const name = calendarAttendeeDisplayName(attendee);
  const email = calendarAttendeeEmail(attendee);
  if(name && email && name.toLowerCase() !== email) return name + ' <' + email + '>';
  return name || email || 'Calendar attendee';
}

function calendarAttendeeLooksLikeSelf(attendee = {}){
  const email = calendarAttendeeEmail(attendee);
  if(attendee.self) return true;
  return Boolean(email && selfCalendarEmails.includes(email));
}

function calendarEventExternalAttendees(event = {}){
  return calendarEventAttendees(event).filter((attendee) => !calendarAttendeeLooksLikeSelf(attendee) && (attendee.name || calendarAttendeeEmail(attendee)));
}

function calendarEventAttendeeSummary(event = {}, limit = 3){
  const attendees = calendarEventExternalAttendees(event).map(calendarAttendeeLabel).filter(Boolean);
  if(!attendees.length) return '';
  const shown = attendees.slice(0, limit);
  const remaining = attendees.length - shown.length;
  return shown.join(' · ') + (remaining > 0 ? ' · +' + remaining + ' more' : '');
}

function renderCalendarAttendeeList(event = {}){
  const summary = calendarEventAttendeeSummary(event, 3);
  return summary ? '<em class="calendar-attendee-list">' + escapeHtml(summary) + '</em>' : '';
}

function calendarEventLooksPrivateBlock(event = {}){
  const text = [event.title, event.summary, event.description, event.location].filter(Boolean).join(' ').toLowerCase();
  return /\b(mammogram|screening|doctor|dentist|therapy|medical|appointment|annual physical|haircut|personal block|focus block|thinking day|ceo thinking day)\b/.test(text);
}

function calendarEventStartDate(event = {}){
  const value = event.start || event.startTime || event.date || '';
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
}

function calendarEventIsPast(event = {}){
  const date = calendarEventStartDate(event);
  return !!date && date.getTime() < Date.now();
}

function calendarEventIsMeeting(event = {}){
  return calendarEventExternalAttendees(event).length > 0 && !calendarEventLooksPrivateBlock(event);
}

function calendarEventLooksMeetingLike(event = {}){
  const text = [event.title, event.summary, event.description, event.location, event.meetingLink].filter(Boolean).join(' ').toLowerCase();
  return /\b(meet|meeting|zoom|call|session|prep|check[ -]?in|follow[ -]?up|planning|review|sync)\b/.test(text) && !calendarEventLooksPrivateBlock(event);
}

function calendarEventIsFutureMeeting(event = {}){
  return calendarEventIsMeeting(event) && !calendarEventIsPast(event);
}

function calendarCoworkContextLines(limit = 6){
  const events = (currentCalendarEvents || [])
    .filter((event) => !calendarEventIsPast(event))
    .slice(0, limit)
    .map((event, index) => {
      const date = calendarEventStartDate(event);
      const when = date ? date.toLocaleString([], {weekday:'short', hour:'numeric', minute:'2-digit'}) : 'Time unknown';
      const titleText = event.title || event.summary || '(No title)';
      const attendees = calendarEventAttendeeSummary(event, 3);
      const location = String(event.location || event.meetingLink || '').trim();
      return [String(index + 1) + '. ' + when + ': ' + titleText, attendees ? 'Attendees: ' + attendees : '', location ? 'Location: ' + location : ''].filter(Boolean).join(' | ');
    });
  const nextMeeting = currentMeetingEvents?.[0];
  const nextMeetingDate = nextMeeting ? calendarEventStartDate(nextMeeting) : null;
  const nextMeetingLine = nextMeeting
    ? 'Next meeting: ' + (nextMeetingDate ? nextMeetingDate.toLocaleString([], {weekday:'short', hour:'numeric', minute:'2-digit'}) : 'Time unknown') + ' - ' + (nextMeeting.title || nextMeeting.summary || '(No title)') + (calendarEventAttendeeSummary(nextMeeting, 3) ? ' with ' + calendarEventAttendeeSummary(nextMeeting, 3) : '')
    : '';
  return [nextMeetingLine, ...events].filter(Boolean);
}

function homeCoworkNeedsFullValContext(text = ''){
  const value = String(text || '');
  if(/\b(next|upcoming)\b[\s\S]{0,30}\b(appointment|calendar|meeting|schedule)\b/i.test(value)) return false;
  if(homeCoworkNeedsActionPrep(value)) return false;
  if(/\bwitnessing\b/i.test(value)) return false;
  return /\b(send|email|draft|reply|contact|person|people|relationship|stewardship|crm|ghl|pipeline|opportunity|note|task|project|transcript|linkedin|board|observer|director|witnessing|document|file|memory|search|find|look up|check|who is|what do we know)\b/i.test(value);
}

function homeCoworkNeedsActionPrep(text = ''){
  const value = String(text || '');
  return /\b(send|write|compose|draft|prepare)\b[\s\S]{0,80}\b(email|reply|message)\b/i.test(value)
    || /\b(email|reply|message)\b[\s\S]{0,50}\b(to|for)\b/i.test(value)
    || /\b(text|sms)\b[\s\S]{0,80}\b(send|tell|ask|message)\b/i.test(value)
    || /\b(send|tell|ask|message)\b[\s\S]{0,80}\b(text|sms)\b/i.test(value)
    || /\b(remind me|set a reminder|create (a )?reminder|add (a )?task|create (a )?task)\b/i.test(value)
    || /\b(book|schedule|create|set up)\b[\s\S]{0,80}\b(appointment|meeting|calendar|event|call)\b/i.test(value);
}

function homeCoworkFullContextDetail(text = ''){
  const value = String(text || '');
  if(/\b(send|email|draft|reply|text|sms)\b/i.test(value)) return 'Give me one moment. I’m finding the right person and preparing the safest path.';
  if(/\b(remind|task)\b/i.test(value)) return 'Give me one moment. I’m finding where this should live.';
  if(/\b(book|schedule|appointment|meeting|calendar|event|call)\b/i.test(value)) return 'Give me one moment. I’m checking the right calendar path.';
  if(/\b(stewardship|relationship|contact|person|people|michele)\b/i.test(value)) return 'Give me one moment. I’m finding the right relationship record.';
  if(/\b(project)\b/i.test(value)) return 'Just a sec. I’m checking Project Managers, source packets, and relevant relationship context.';
  if(/\b(transcript)\b/i.test(value)) return 'Just a sec. I’m checking transcript intelligence and related memory.';
  if(/\b(linkedin)\b/i.test(value)) return 'Just a sec. I’m checking LinkedIn context and relationship signals.';
  if(/\b(board|observer|director)\b/i.test(value)) return 'Just a sec. I’m checking the Board of Observers and current system context.';
  return 'Just a sec. I’m checking the wider system context.';
}

let pendingHomeCoworkActionPacket = null;
let pendingHomeCoworkActionDraft = null;

function isHomeCoworkActionConfirmation(text = ''){
  return /^(send|send it|yes send|yes, send|do it|approve|approved|confirm|confirmed)$/i.test(String(text || '').trim());
}

async function confirmPendingHomeCoworkActionPacket(text = ''){
  if(!pendingHomeCoworkActionPacket || !isHomeCoworkActionConfirmation(text)) return false;
  const packet = pendingHomeCoworkActionPacket;
  pendingHomeCoworkActionPacket = null;
  const payload = packet.payloadPreviewJson || packet.payload_preview_json || {};
  showCoworkContextGathering('VAL is sending exactly the approved message.', {noTimeout:true});
  try{
    await postJson('/api/val/external-actions/' + encodeURIComponent(packet.id) + '/approve', {
      note: 'Approved by spoken Home VAL confirmation.'
    }, {timeoutMs:10000});
    const result = await postJson('/api/val/external-actions/' + encodeURIComponent(packet.id) + '/execute', {
      finalConfirmation:true,
      executedBy:'home_voice_confirmation'
    }, {timeoutMs:18000});
    const sent = result?.executed || result?.packet?.status === 'executed';
    appendHomeCoworkMessage('val', sent
      ? 'Done. I sent the approved email to ' + (payload.to || 'the recipient') + '.'
      : 'I tried to send the approved email, but it did not complete. Nothing else was changed.');
  }catch(error){
    appendHomeCoworkMessage('val', 'I could not complete that send cleanly: ' + (error.message || 'the send gate did not finish.') + '\n\nNothing else was changed.');
  }
  return true;
}

