function updateCoworkEntryContext(result = {}){
  const brief = result.session?.workingBrief || {};
  const entrypointId = result.session?.entrypointId || activeCoworkEntry?.entrypointId || '';
  const isObserverConversation = entrypointId === 'observer.discussion' || entrypointId === 'board.chief_of_staff';
  const isTranscript = entrypointId.startsWith('transcript.');
  const isEmailThread = entrypointId === 'email.thread';
  const isRelationship = entrypointId === 'relationship.overview' || entrypointId === 'relationship.section';
  const sectionLabel = entrypointId === 'project.overview' ? 'Round Table focus' : entrypointId === 'project.documents' ? 'documents and sources' : entrypointId === 'project.people' ? 'people involved' : entrypointId === 'project.identity' ? 'project foundation' : entrypointId === 'project.milestones' ? 'milestones' : entrypointId === 'project.monitoring' ? 'monitoring after launch' : entrypointId === 'project.relationship_nurture' ? 'relationship nurture' : entrypointId === 'project.why_it_matters' ? 'why it matters' : entrypointId === 'project.risk' ? 'risk or blocker' : entrypointId === 'project.narrative' ? 'working narrative' : entrypointId === 'project.needs_next' ? 'what VAL needs next' : entrypointId === 'project.sop' ? 'operating system' : entrypointId === 'project.phase' ? 'current phase' : entrypointId === 'project.prepared_work' ? 'prepared work' : entrypointId === 'project.next_move' ? 'next move' : 'workstreams';
  const fallbackObjective = isTranscript
    ? 'Prepare one reviewable result from the selected transcript.'
    : entrypointId === 'project.overview'
    ? 'Choose one bounded question or work item the Project Managers Round Table should focus on next.'
    : entrypointId === 'project.documents'
    ? 'Link existing evidence and name how it should inform this selected project.'
    : entrypointId === 'project.people'
    ? 'Connect the correct relationships and owner to this selected project.'
    : entrypointId === 'project.identity'
    ? 'Establish the selected project foundation.'
    : entrypointId === 'project.milestones'
    ? 'Define evidence-based milestones for this project.'
    : entrypointId === 'project.monitoring'
    ? 'Define what VAL watches and when to surface it.'
    : entrypointId === 'project.relationship_nurture'
    ? 'Define how VAL should protect the relationships this project depends on.'
    : entrypointId === 'project.why_it_matters'
    ? 'State the project consequence or opportunity, why now, and the basis for that judgment.'
    : entrypointId === 'project.risk'
    ? 'Assess one material risk precisely, or record that none is currently proven.'
    : entrypointId === 'project.narrative'
    ? 'Make the project\'s current reality, learning, blocked condition, basis, and confidence explicit.'
    : entrypointId === 'project.needs_next'
    ? 'Identify one precise missing fact, decision, source, or person before taking another project-management step.'
    : entrypointId === 'project.sop'
    ? 'Select the real operating pattern that should run this project and make material deviations explicit.'
    : entrypointId === 'project.phase'
    ? 'Record the project’s actual place in the selected operating-system sequence, with evidence and an exit condition.'
    : entrypointId === 'project.prepared_work'
    ? 'Choose one reviewable artifact to prepare with the correct source and approval boundary.'
    : entrypointId === 'project.next_move'
    ? 'Commit to the next narrow move for this project.'
    : 'Build a complete set of workstreams for this project.';
  const context = scraperPreviewList?.querySelector?.('[data-home-cowork-context]');
  if(!context) return;
  if(isObserverConversation){
    const isChief = entrypointId === 'board.chief_of_staff';
    context.innerHTML = [
      '<span>' + (isChief ? 'Chief of Staff' : 'Board of Observers') + '</span>',
      '<strong>' + escapeHtml(brief.title || (isChief ? 'Chat with Your Chief of Staff' : 'Observer conversation')) + '</strong>',
      '<p>' + escapeHtml(isChief ? 'Your Chief of Staff can reason across the full Board context.' : 'This conversation stays scoped to this Observer and its evidence.') + '</p>',
      '<small>Saved privately and carried forward when you return.</small>'
    ].join('');
    return;
  }
  if(isRelationship){
    const sectionLabel = entrypointId === 'relationship.section' ? (brief.sectionLabel || 'selected card') : 'next relationship move';
    context.innerHTML = [
      '<span>Relationships</span>',
      '<strong>' + escapeHtml((brief.relationshipName || 'Selected relationship') + ' > ' + sectionLabel) + '</strong>',
      '<p>' + escapeHtml(brief.objective || 'Prepare one reviewable update for this selected relationship card.') + '</p>',
      '<small>Selected relationship only. Nothing external happens here.</small>'
    ].join('');
    return;
  }
  if(isEmailThread){
    context.innerHTML = [
      '<span>Executive Inbox</span>',
      '<strong>' + escapeHtml(brief.subject || 'Selected email thread') + '</strong>',
      '<p>' + escapeHtml(brief.objective || 'Prepare one review-only reply from this selected thread.') + '</p>',
      '<small>Selected thread: ' + escapeHtml((brief.messages || []).length) + ' readable message(s). Nothing external happens here.</small>'
    ].join('');
    return;
  }
  if(isTranscript){
    const receipt = brief.sourceReceipt || {};
    context.innerHTML = [
      '<span>Transcripts</span>',
      '<strong>' + escapeHtml(brief.transcriptTitle || 'Selected transcript') + '</strong>',
      '<p>' + escapeHtml(brief.objective || fallbackObjective) + '</p>',
      brief.actionItem
        ? '<small>Exact Krisp Action Item: ' + escapeHtml(brief.actionItem) + '</small>'
        : '<small>Exact Krisp receipt: ' + escapeHtml((receipt.actionItems || []).length) + ' Action Items and ' + escapeHtml((receipt.keyPoints || []).length) + ' Key Points.</small>'
    ].join('');
    return;
  }
  context.innerHTML = [
    '<span>Project Managers</span>',
    '<strong>' + escapeHtml(brief.projectName || activeProjectProfile?.name || 'Project') + ' ' + escapeHtml(sectionLabel) + '</strong>',
    '<p>' + escapeHtml(brief.objective || fallbackObjective) + '</p>',
    brief.completionCondition ? '<small>Complete when: ' + escapeHtml(brief.completionCondition) + '</small>' : ''
  ].join('');
}

function renderCoworkEntryResult(result = {}, options = {}){
  const session = result.session || {};
  const workItem = result.workItem || {};
  hideCoworkContextGathering();
  if(session.id){
    activeCoworkEntry = {
      ...(activeCoworkEntry || {}),
      entrypointId:session.entrypointId || activeCoworkEntry?.entrypointId || '',
      sessionId:session.id,
      workItemId:workItem.id || activeCoworkEntry?.workItemId || '',
      status:workItem.status || session.status || '',
      sectionId:session.scope?.sectionId || activeCoworkEntry?.sectionId || '',
      projectId:session.scope?.entityType === 'project_section' ? (session.scope?.entityId || activeProjectProfile?.projectId || activeProjectProfile?.id || '') : '',
      transcriptId:session.scope?.entityType === 'transcript' ? session.scope?.entityId || '' : '',
      emailThreadId:session.scope?.entityType === 'email_thread' ? session.scope?.entityId || '' : '',
      relationshipId:(session.scope?.entityType === 'relationship' || session.scope?.entityType === 'relationship_section') ? session.scope?.entityId || '' : '',
      observerId:(session.scope?.entityType === 'observer' || session.scope?.entityType === 'observer_board') ? session.scope?.entityId || '' : ''
    };
  }
  updateCoworkEntryContext(result);
  const response = homeCoworkResponseNode();
  const isObserverConversation = session.entrypointId === 'observer.discussion' || session.entrypointId === 'board.chief_of_staff';
  const savedMessages = Array.isArray(session.state?.messages) ? session.state.messages : [];
  if(response && isObserverConversation && options.hydrateConversation){
    response.innerHTML = savedMessages.length
      ? savedMessages.map((saved) => renderHomeCoworkMessage(saved.role === 'user' ? 'user' : 'val', saved.content || '')).join('')
      : renderHomeCoworkMessage('val', session.entrypointId === 'board.chief_of_staff'
        ? 'I am here with the full Board context. What would you like us to notice, pressure-test, or move forward?'
        : 'This Observer is loaded with the evidence behind the card. What do you want to examine first?');
    response.scrollTop = response.scrollHeight;
  }
  response?.querySelectorAll?.('[data-cowork-work-item]').forEach((node) => node.remove());
  const message = options.suppressMessage ? '' : (result.question?.question || result.message || '');
  if(message) appendHomeCoworkMessage('val', message, {replace:Boolean(options.replaceMessage)});
  if(response && workItem.id){
    const item = workItem.type === 'project_documents'
      ? renderCoworkDocumentItem(workItem)
      : workItem.type === 'project_people'
      ? renderCoworkPeopleItem(workItem)
      : workItem.type === 'project_onboarding_stage'
      ? renderCoworkProjectOnboardingItem(workItem)
      : workItem.type === 'project_identity'
      ? renderCoworkIdentityItem(workItem)
      : workItem.type === 'project_milestones'
      ? renderCoworkMilestonesItem(workItem)
      : workItem.type === 'project_monitoring'
      ? renderCoworkMonitoringItem(workItem)
      : workItem.type === 'project_relationship_nurture'
      ? renderCoworkRelationshipNurtureItem(workItem)
      : workItem.type === 'project_importance'
      ? renderCoworkProjectImportanceItem(workItem)
      : workItem.type === 'project_risk'
      ? renderCoworkProjectRiskItem(workItem)
      : workItem.type === 'project_narrative'
      ? renderCoworkProjectNarrativeItem(workItem)
      : workItem.type === 'project_needs_next'
      ? renderCoworkProjectNeedsNextItem(workItem)
      : workItem.type === 'project_operating_system'
      ? renderCoworkProjectOperatingSystemItem(workItem)
      : workItem.type === 'project_phase'
      ? renderCoworkProjectPhaseItem(workItem)
      : workItem.type === 'project_overview_focus'
      ? renderCoworkProjectOverviewFocusItem(workItem)
      : workItem.type === 'relationship_overview_focus'
      ? renderCoworkRelationshipOverviewItem(workItem)
      : workItem.type === 'relationship_section_update'
      ? renderCoworkRelationshipSectionItem(workItem)
      : workItem.type === 'project_prepared_work'
      ? renderCoworkProjectPreparedWorkItem(workItem)
      : workItem.type === 'project_next_move'
      ? renderCoworkNextMoveItem(workItem)
      : workItem.type === 'transcript_meeting_overview'
        ? renderCoworkTranscriptOverviewItem(workItem)
        : workItem.type === 'transcript_action_item'
          ? renderCoworkTranscriptActionItem(workItem)
        : workItem.type === 'email_thread_draft'
          ? renderCoworkEmailThreadItem(workItem)
        : renderCoworkWorkstreamsItem(workItem);
    if(item) response.insertAdjacentHTML('beforeend', item);
  }
  const textarea = homeCoworkTextareaNode();
  const submit = homeCoworkSubmitNode();
  const isComplete = !isObserverConversation && (workItem.status === 'applied' || session.status === 'completed');
  const chatShouldStayOpen = session.entrypointId.startsWith('transcript.') || session.entrypointId === 'observer.discussion' || session.entrypointId === 'board.chief_of_staff';
  const isReadyForReview = !isComplete && !chatShouldStayOpen && (session.entrypointId === 'email.thread' || session.entrypointId === 'relationship.overview' || session.entrypointId === 'relationship.section') && workItem.status === 'needs_review';
  if(textarea){
    if(isObserverConversation){
      textarea.placeholder = session.entrypointId === 'board.chief_of_staff' ? 'Talk this through with your Chief of Staff...' : 'Talk this through with this Observer...';
      textarea.disabled = false;
    }else{
    const completeLabel = session.entrypointId === 'transcript.working_brief'
      ? 'Meeting overview draft created.'
      : session.entrypointId === 'transcript.action_item'
        ? 'Transcript Commitment created.'
      : session.entrypointId === 'email.thread'
        ? 'Private email draft ready in Leverage.'
      : session.entrypointId === 'relationship.overview'
        ? 'Relationship move applied.'
      : session.entrypointId === 'relationship.section'
        ? 'Relationship card update applied.'
      : session.entrypointId === 'project.documents'
        ? 'Project document links applied.'
      : session.entrypointId === 'project.people'
        ? 'Project people applied.'
      : session.entrypointId === 'project.identity'
        ? 'Project foundation applied.'
      : session.entrypointId === 'project.onboarding'
        ? 'Project onboarding answer applied.'
      : session.entrypointId === 'project.milestones'
        ? 'Milestones applied.'
      : session.entrypointId === 'project.monitoring'
        ? 'Monitoring rules applied.'
      : session.entrypointId === 'project.relationship_nurture'
        ? 'Relationship nurture rules applied.'
      : session.entrypointId === 'project.why_it_matters'
        ? 'Strategic judgment applied.'
      : session.entrypointId === 'project.risk'
        ? 'Project risk assessment applied.'
      : session.entrypointId === 'project.narrative'
        ? 'Current-state narrative applied.'
      : session.entrypointId === 'project.needs_next'
        ? 'What VAL needs next applied.'
      : session.entrypointId === 'project.sop'
        ? 'Operating system applied.'
      : session.entrypointId === 'project.phase'
        ? 'Current phase applied.'
      : session.entrypointId === 'project.overview'
        ? 'Round Table focus applied.'
      : session.entrypointId === 'project.prepared_work'
        ? 'Prepared work applied.'
      : session.entrypointId === 'project.next_move'
        ? 'Next move applied.'
        : 'Workstreams applied.';
    const returnSurface = session.entrypointId === 'email.thread' ? ' Executive Inbox' : (session.entrypointId.startsWith('transcript.') ? ' Transcripts' : (session.entrypointId.startsWith('relationship.') ? ' Stewardship' : ' Project Managers'));
    textarea.placeholder = isComplete ? completeLabel + ' Return to' + returnSurface + ' when you are ready.' : isReadyForReview ? (session.entrypointId === 'email.thread' ? 'Review the private draft in Leverage.' : 'Review the source-backed result above, then use Apply.') : coworkEntryPlaceholder(result.question || {});
      textarea.disabled = isComplete || isReadyForReview;
    }
  }
  if(submit) submit.disabled = isObserverConversation ? false : (isComplete || isReadyForReview);
}

async function openProjectWorkstreamsCowork(node = null){
  const project = projectProfileForCoworkNode(node);
  if(!project) return;
  const projectId = project.projectId || project.id || project.profileKey || '';
  if(!projectId) return;
  const scopedPacket = projectScopedCoworkPacket('workstreams', project);
  const action = 'project:cowork:workstreams';
  const baseSource = projectSource(project, action);
  const source = {...baseSource,sourceItem:{...(baseSource.sourceItem || {}),scopedCoworkPacket:scopedPacket}};
  activeProjectCoworkTarget = {field:'workstreams',mode:'registered_entry',projectId,projectName:project.name || 'project',title:'Build project workstreams',scopedPacket};
  activeCoworkEntry = {entrypointId:'project.workstreams',sessionId:'',workItemId:'',projectId,status:'opening'};
  openContextualCoworkSession({
    returnTarget:'project',
    title:'Build project workstreams',
    meaning:'Preparing the workstreams brief for ' + (project.name || 'this project') + '.',
    context:projectScopedCoworkContextLines(scopedPacket),
    recommendation:'VAL will ask only for the fields needed to create complete, manageable workstreams.',
    placeholder:'Preparing the selected Project Managers section...',
    heading:'Preparing workstreams for ' + (project.name || 'this project'),
    detail:'This interview fills the Project Managers workstreams packet.',
    publicDetail:'Scoped to Project Managers: Workstreams.',
    lockContext:true
  });
  void ensureHearthClickPacket({node,packetName:'project_packet',action,allowBlockedForInspection:true,source}).then((preflight) => {
    if(preflight.ok) renderDrawerPacketReceiptStrip(preflight.packet || lastHearthPacketReceipt);
  }).catch(() => {});
  try{
    const result = await postJson('/api/val/cowork/entries/open',{
      entrypointId:'project.workstreams',
      scope:{entityType:'project_section',entityId:projectId,sectionId:'workstreams'},
      suggestedWorkstreams:projectCoworkWorkstreamSuggestions(project)
    },{timeoutMs:10000,timeoutMessage:'VAL could not prepare this Workstreams brief yet.'});
    renderCoworkEntryResult(result,{replaceMessage:true});
  }catch(error){
    activeCoworkEntry = null;
    appendHomeCoworkMessage('val','VAL could not open the Workstreams interview. Nothing was changed. ' + error.message,{replace:true});
  }
}

