function setCorrespondenceField(field, value){
  const node = document.querySelector('[data-correspondence-field="' + field + '"]');
  if(node) node.textContent = value || '';
}

function correspondenceFallbackMessage(item = activeCorrespondenceItem){
  if(!item) return '';
  const raw = item.raw || {};
  const source = raw.sourceContext || raw.source_context || raw.metadataJson || raw.metadata || {};
  const conversation = source.conversationContext || source.conversation_context || source.thread || source.conversation || {};
  const current = conversation.current_message || conversation.currentMessage || {};
  const latest = conversation.latest_inbound || conversation.latestInbound || source.latestInbound || source.latest_inbound || {};
  return [
    raw.bodyText,
    raw.body_text,
    raw.bodyPreview,
    raw.body_preview,
    raw.snippet,
    source.bodyText,
    source.body_text,
    source.bodyPreview,
    source.body_preview,
    current.bodyText,
    current.body_text,
    current.bodyPreview,
    current.body_preview,
    current.snippet,
    latest.bodyText,
    latest.body_text,
    latest.bodyPreview,
    latest.body_preview,
    latest.snippet,
    item.threadMessages?.[0]?.body,
    item.evidence?.[0],
    item.summary
  ].map((value) => correspondenceCompactText(value, 3600)).find(Boolean) || '';
}

function correspondenceFallbackSender(item = activeCorrespondenceItem){
  if(!item) return 'Email';
  const raw = item.raw || {};
  const source = raw.sourceContext || raw.source_context || raw.metadataJson || raw.metadata || {};
  const conversation = source.conversationContext || source.conversation_context || {};
  const current = conversation.current_message || conversation.currentMessage || {};
  const latest = conversation.latest_inbound || conversation.latestInbound || source.latestInbound || source.latest_inbound || {};
  const from = raw.from || source.from || current.from || latest.from || {};
  return from.name || from.email || item.senderName || item.senderEmail || 'Email';
}

function correspondenceReadableTextFromHtml(value = ''){
  if(!value) return '';
  const template = document.createElement('template');
  template.innerHTML = String(value || '');
  return correspondenceCompactText(template.content.textContent || '', 2400);
}

function correspondenceCalendarInviteDetails(message = {}){
  const text = correspondenceReadableTextFromHtml(message.bodyHtml) || correspondenceCompactText(message.body || '', 2400);
  if(!/this event has been updated|zoom link|view all guest info|changed:\s*description|guests/i.test(text)) return null;
  const normalized = text.replace(/\s+/g, ' ').trim();
  const zoom = normalized.match(/https?:\/\/[^\s<>"']+/i)?.[0] || '';
  const changed = normalized.match(/changed:\s*([A-Z ]+?)(?:\s+zoom link:|\s+description|\s+when\b|$)/i)?.[1] || 'Description';
  const when = normalized.match(/((?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)\s+[a-z]{3,9}\s+\d{1,2},\s+\d{4}\s+.+?(?:new york|edt|est|pst|cst|mst))/i)?.[1] || '';
  const guestsPart = normalized.match(/guests\s+(.+?)(?:\s+view all guest info|$)/i)?.[1] || '';
  const guests = guestsPart
    .split(/\s+(?=[A-Z][a-z]+ [A-Z][a-z]+ - |[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,})/i)
    .map((guest) => correspondenceCompactText(guest.replace(/\s+-\s+/g, ' - '), 90))
    .filter(Boolean)
    .slice(0, 4);
  return {changed:correspondenceCompactText(changed, 80), zoom, when:correspondenceCompactText(when, 140), guests};
}

function renderCorrespondenceCalendarInvite(message = {}){
  const details = correspondenceCalendarInviteDetails(message);
  if(!details) return null;
  const card = document.createElement('div');
  card.className = 'correspondence-calendar-email';
  const eyebrow = document.createElement('span');
  eyebrow.textContent = 'Calendar Update';
  const title = document.createElement('strong');
  title.textContent = 'This event was updated';
  const grid = document.createElement('dl');
  const rows = [
    ['Changed', details.changed],
    ['When', details.when],
    ['Guests', details.guests.join(' · ')]
  ].filter((row) => row[1]);
  rows.forEach(([label, value]) => {
    const dt = document.createElement('dt');
    dt.textContent = label;
    const dd = document.createElement('dd');
    dd.textContent = value;
    grid.append(dt, dd);
  });
  card.append(eyebrow, title, grid);
  if(details.zoom){
    const link = document.createElement('a');
    link.href = details.zoom;
    link.target = '_blank';
    link.rel = 'noopener noreferrer';
    link.textContent = 'Open Zoom link';
    card.appendChild(link);
  }
  return card;
}

function correspondenceMeaningfulSentences(value = '', limit = 2){
  const cleaned = String(value || '')
    .replace(/https?:\/\/\S+/gi, '')
    .replace(/\b(view all guest info|zoom link|when|guests|description|changed)\b\s*:*/gi, ' ')
    .replace(/\s+/g, ' ')
    .trim();
  if(!cleaned) return '';
  const sentences = cleaned
    .split(/(?<=[.!?])\s+/)
    .map((sentence) => sentence.trim())
    .filter((sentence) => sentence.length > 24 && !/^(this event has been updated|changed description)$/i.test(sentence));
  const chosen = (sentences.length ? sentences : [cleaned]).slice(0, limit).join(' ');
  return correspondenceCompactText(chosen, 360);
}

function correspondenceConversationSummary(item = activeCorrespondenceItem){
  if(!item) return 'Select a conversation to see what the latest email says and why it needs judgment.';
  const messages = Array.isArray(item.threadMessages) ? item.threadMessages.filter((message) => message?.body || message?.bodyHtml) : [];
  const latest = messages[0] || {};
  const sender = latest.from || correspondenceFallbackSender(item);
  const title = correspondenceCompactText(item.title || item.subject || 'this conversation', 140);
  const latestText = correspondenceMeaningfulSentences(latest.body || correspondenceReadableTextFromHtml(latest.bodyHtml) || correspondenceFallbackMessage(item), 2);
  if(/^updated invitation|^invitation:/i.test(title)){
    return latestText
      ? sender + ' sent a calendar update for "' + title + '". The visible change is: ' + latestText
      : sender + ' sent a calendar update for "' + title + '". Review the invite details before deciding the next response.';
  }
  if(latestText){
    return sender + ' wrote about "' + title + '": ' + latestText;
  }
  return item.summary || item.whyNow || 'VAL found this conversation needs judgment, but the readable message body is limited.';
}

function correspondenceHumanContactTime(value = ''){
  if(!value) return '';
  const date = new Date(value);
  if(Number.isNaN(date.getTime())) return correspondenceCompactText(value, 42);
  const now = new Date();
  const yesterday = new Date(now);
  yesterday.setDate(now.getDate() - 1);
  const sameDay = date.toDateString() === now.toDateString();
  const priorDay = date.toDateString() === yesterday.toDateString();
  const time = date.toLocaleTimeString([], {hour:'2-digit', minute:'2-digit', hourCycle:'h23'});
  if(sameDay) return 'Today, ' + time;
  if(priorDay) return 'Yesterday, ' + time;
  const dateLabel = date.toLocaleDateString([], date.getFullYear() === now.getFullYear()
    ? {month:'short', day:'numeric'}
    : {month:'short', day:'numeric', year:'numeric'});
  return dateLabel + ', ' + time;
}

function correspondenceThreadIdentity(item = activeCorrespondenceItem){
  if(!item) return '';
  return [item.provider || 'email', item.messageId || '', item.threadId || '', item.conversationId || item.id || ''].join(':');
}

async function hydrateSelectedCorrespondenceThread(item = activeCorrespondenceItem){
  if(!item || !canUseApi || item.threadHydrated) return;
  const messageId = item.messageId || '';
  const threadId = item.threadId || '';
  const conversationId = item.conversationId || '';
  if(!messageId && !threadId && !conversationId) return;
  const token = ++correspondenceThreadHydrationToken;
  const identity = correspondenceThreadIdentity(item);
  try{
    const params = new URLSearchParams();
    if(messageId) params.set('messageId', messageId);
    if(threadId) params.set('threadId', threadId);
    if(conversationId) params.set('conversationId', conversationId);
    if(item.provider) params.set('provider', item.provider);
    const result = await getJson('/api/val/executive-inbox/thread?' + params.toString(), {timeoutMs:16000, timeoutMessage:'Selected email thread took longer than expected.'});
    if(token !== correspondenceThreadHydrationToken || correspondenceThreadIdentity(activeCorrespondenceItem) !== identity) return;
    const thread = result.thread || {};
    const messages = correspondenceThreadMessagesFromSource({messages:thread.messages || [], conversationContext:{messages:thread.messages || []}}, item);
    const existingDraft = thread.existingDraft || thread.existing_draft || {};
    const updated = {
      ...item,
      threadHydrated:true,
      threadMessages:messages.length ? messages : item.threadMessages,
      draftBody:item.draftBody || existingDraft.body || '',
      draftId:item.draftId || existingDraft.id || '',
      raw:{...(item.raw || {}), selectedThread:thread}
    };
    currentCorrespondenceItems = currentCorrespondenceItems.map((row) => row.id === item.id ? updated : row);
    activeCorrespondenceItem = updated;
    renderCorrespondenceBrief(updated);
    if(updated && !String(updated.draftBody || '').trim() && !updated.autoDraftAttempted){
      prepareSelectedCorrespondenceDraft(updated);
    }
  }catch(error){
    if(token !== correspondenceThreadHydrationToken) return;
    const updated = {...item, threadHydrated:true};
    currentCorrespondenceItems = currentCorrespondenceItems.map((row) => row.id === item.id ? updated : row);
    activeCorrespondenceItem = updated;
    renderCorrespondenceThread(updated);
    if(correspondenceSafety) correspondenceSafety.textContent = 'VAL could not load previous emails for this thread yet. Showing the readable message currently attached.';
    if(updated && !String(updated.draftBody || '').trim() && !updated.autoDraftAttempted){
      prepareSelectedCorrespondenceDraft(updated);
    }
  }
}

async function prepareSelectedCorrespondenceDraft(item = activeCorrespondenceItem){
  if(!item || !canUseApi || item.autoDraftAttempted || String(item.draftBody || '').trim()) return;
  const preparedItem = {...item, autoDraftAttempted:true};
  currentCorrespondenceItems = currentCorrespondenceItems.map((row) => row.id === item.id ? preparedItem : row);
  activeCorrespondenceItem = preparedItem;
  if(correspondenceSafety) correspondenceSafety.textContent = 'Preparing a private reply draft with your saved Tone Rules. Nothing is sent or created in Gmail.';
  try{
    await draftCorrespondenceReply(preparedItem, {automatic:true});
  }catch(error){
    if(correspondenceSafety) correspondenceSafety.textContent = 'VAL could not prepare a private draft yet: ' + error.message;
    activeCorrespondenceItem = {...preparedItem, autoDraftFailed:true};
    currentCorrespondenceItems = currentCorrespondenceItems.map((row) => row.id === item.id ? activeCorrespondenceItem : row);
  }
}

function renderCorrespondenceThread(item = activeCorrespondenceItem){
  if(!correspondenceThreadBody) return;
  correspondenceThreadBody.innerHTML = '';
  const messages = Array.isArray(item?.threadMessages) ? item.threadMessages.filter((message) => message?.body || message?.bodyHtml) : [];
  if(!item){
    return;
  }
  const attachments = Array.isArray(item.attachments) ? item.attachments : correspondenceAttachmentsFromSource(item.raw || {});
  if(attachments.length){
    const attachmentBlock = document.createElement('article');
    attachmentBlock.className = 'correspondence-thread-attachments';
    const span = document.createElement('span');
    span.textContent = 'Attachments';
    const wrap = document.createElement('div');
    attachments.slice(0, 6).forEach((attachment) => {
      const chip = document.createElement('button');
      chip.type = 'button';
      chip.dataset.correspondenceAttachmentIndex = String(attachments.indexOf(attachment));
      const size = Number(attachment.size || 0);
      const sizeLabel = size ? ' · ' + Math.round(size / 1024) + ' KB' : '';
      chip.textContent = [attachment.name, attachment.type].filter(Boolean).join(' · ') + sizeLabel;
      chip.title = attachment.attachmentId || attachment.url ? 'View attachment source' : 'Attachment source id is not available yet';
      wrap.appendChild(chip);
    });
    attachmentBlock.append(span, wrap);
    correspondenceThreadBody.appendChild(attachmentBlock);
  }
  if(!messages.length){
    const empty = document.createElement('article');
    empty.className = 'correspondence-thread-message newest';
    const span = document.createElement('span');
    span.textContent = ['Latest email', correspondenceFallbackSender(item), correspondenceHumanContactTime(item.receivedAt)].filter(Boolean).join(' · ');
    const p = document.createElement('p');
    p.textContent = correspondenceFallbackMessage(item) || 'No readable email body is attached yet. VAL should not ask you to act on this thread until the source message is visible.';
    empty.append(span, p);
    correspondenceThreadBody.appendChild(empty);
    return;
  }
  messages.forEach((message, index) => {
    if(index === 1){
      const history = document.createElement('div');
      history.className = 'correspondence-thread-history-label';
      history.textContent = 'Previous emails in this thread';
      correspondenceThreadBody.appendChild(history);
    }
    const article = document.createElement('article');
    article.className = 'correspondence-thread-message' + (index === 0 ? ' newest' : '');
    const span = document.createElement('span');
    span.textContent = [index === 0 ? 'Latest email' : 'Earlier email', message.from, correspondenceHumanContactTime(message.date)].filter(Boolean).join(' · ');
    article.appendChild(span);
    const calendarInvite = renderCorrespondenceCalendarInvite(message);
    if(calendarInvite){
      article.appendChild(calendarInvite);
    }else if(message.bodyHtml){
      const html = document.createElement('div');
      html.className = 'correspondence-email-html';
      html.innerHTML = message.bodyHtml;
      article.appendChild(html);
    }else{
      const p = document.createElement('p');
      p.textContent = message.body;
      article.appendChild(p);
    }
    correspondenceThreadBody.appendChild(article);
  });
}

function selectedCorrespondenceAttachments(item = activeCorrespondenceItem){
  if(!item) return [];
  return Array.isArray(item.attachments) ? item.attachments : correspondenceAttachmentsFromSource(item.raw || {});
}

function setCorrespondenceAttachmentPanel(open){
  if(!correspondenceAttachmentPanel) return;
  correspondenceAttachmentPanel.hidden = !open;
  correspondenceAttachmentPanel.setAttribute('aria-hidden', String(!open));
}

function renderCorrespondenceAttachmentView(result = {}, attachment = {}){
  if(correspondenceAttachmentTitle) correspondenceAttachmentTitle.textContent = result.filename || attachment.name || 'Email attachment';
  if(correspondenceAttachmentMeta){
    correspondenceAttachmentMeta.textContent = [
      result.mimeType || attachment.mimeType || attachment.type || 'Attachment',
      result.size ? Math.round(Number(result.size) / 1024) + ' KB' : '',
      'Read-only source view. Nothing is sent, downloaded, moved, or changed.'
    ].filter(Boolean).join(' · ');
  }
  if(!correspondenceAttachmentView) return;
  correspondenceAttachmentView.innerHTML = '';
  if(result.dataUrl && String(result.mimeType || '').startsWith('image/')){
    const img = document.createElement('img');
    img.src = result.dataUrl;
    img.alt = result.filename || attachment.name || 'Email attachment';
    correspondenceAttachmentView.appendChild(img);
    return;
  }
  if(result.dataUrl && String(result.mimeType || '').includes('pdf')){
    const frame = document.createElement('iframe');
    frame.src = result.dataUrl;
    frame.title = result.filename || attachment.name || 'Email attachment';
    correspondenceAttachmentView.appendChild(frame);
    return;
  }
  const pre = document.createElement('pre');
  pre.textContent = result.text || result.message || 'VAL could not produce a readable preview for this attachment yet.';
  correspondenceAttachmentView.appendChild(pre);
}

async function openCorrespondenceAttachment(index = 0){
  const attachment = selectedCorrespondenceAttachments()[index];
  if(!attachment){
    if(correspondenceSafety) correspondenceSafety.textContent = 'Attachment source was not found on the selected thread.';
    return;
  }
  if(attachment.url){
    window.open(attachment.url, '_blank', 'noopener');
    if(correspondenceSafety) correspondenceSafety.textContent = 'Opened the attachment source link. No VAL data was changed.';
    return;
  }
  const messageId = attachment.messageId || activeCorrespondenceItem?.messageId || activeCorrespondenceItem?.raw?.messageId || '';
  const attachmentId = attachment.attachmentId || attachment.id || '';
  if(!messageId || !attachmentId){
    if(correspondenceSafety) correspondenceSafety.textContent = 'VAL has the attachment name, but not the Gmail source id needed to open it yet.';
    setCorrespondenceAttachmentPanel(true);
    renderCorrespondenceAttachmentView({filename:attachment.name, mimeType:attachment.mimeType || attachment.type, size:attachment.size, message:'Attachment listed on the email, but the source id is missing. Re-scan Gmail or open the original message in Gmail to view it.'}, attachment);
    return;
  }
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The live VAL server is needed to open Gmail attachment sources.';
    return;
  }
  setCorrespondenceAttachmentPanel(true);
  renderCorrespondenceAttachmentView({filename:attachment.name, mimeType:attachment.mimeType || attachment.type, size:attachment.size, message:'Loading attachment source...'}, attachment);
  try{
    const params = new URLSearchParams({messageId, attachmentId, filename:attachment.filename || attachment.name || '', mimeType:attachment.mimeType || attachment.type || ''});
    const result = await getJson('/api/val/executive-inbox/attachment?' + params.toString(), {timeoutMs:22000, timeoutMessage:'Attachment source took longer than expected.'});
    renderCorrespondenceAttachmentView(result, attachment);
    if(correspondenceSafety) correspondenceSafety.textContent = 'Opened attachment source in read-only preview.';
  }catch(error){
    renderCorrespondenceAttachmentView({filename:attachment.name, mimeType:attachment.mimeType || attachment.type, size:attachment.size, message:'Attachment preview failed: ' + error.message}, attachment);
    if(correspondenceSafety) correspondenceSafety.textContent = 'Attachment preview failed: ' + error.message;
  }
}

function renderCorrespondenceSideList(node, lines, emptyText){
  if(!node) return;
  node.innerHTML = '';
  const values = (Array.isArray(lines) ? lines : []).map((line) => correspondenceCompactText(line, 180)).filter(Boolean);
  if(!values.length){
    const empty = document.createElement('p');
    empty.className = 'correspondence-side-empty';
    empty.textContent = emptyText;
    node.appendChild(empty);
    return;
  }
  values.forEach((line) => {
    const p = document.createElement('p');
    p.textContent = line;
    node.appendChild(p);
  });
}

function correspondenceOptionLabel(item = {}, fallback = 'Untitled'){
  return item.name || item.displayName || item.display_name || item.title || item.email || item.id || fallback;
}

function correspondencePopulateSelect(select, items = [], emptyLabel = 'Choose'){
  if(!select) return;
  const selected = select.value;
  const options = items
    .map((item) => ({
      id: item.id || item.profileKey || item.profile_key || item.projectId || item.project_id || item.email || '',
      label: correspondenceOptionLabel(item)
    }))
    .filter((item) => item.id && item.label)
    .sort((a, b) => a.label.localeCompare(b.label));
  select.innerHTML = '<option value="">' + escapeHtml(emptyLabel) + '</option>' + options.map((item) => '<option value="' + escapeHtml(item.id) + '">' + escapeHtml(item.label) + '</option>').join('');
  if(options.some((item) => item.id === selected)) select.value = selected;
}

function correspondenceRelationshipOptions(){
  return Object.values(relationshipIndexProfiles || {})
    .map((item) => ({
      id: item.id || item.profileKey || item.profile_key || item.email || '',
      label: correspondenceOptionLabel(item),
      email: item.email || item.primaryEmail || item.primary_email || '',
      summary: item.role || item.relationship || item.summary || item.context || ''
    }))
    .filter((item) => item.id && item.label)
    .sort((a, b) => a.label.localeCompare(b.label));
}

function correspondenceSetRelationshipSearch(open = false){
  if(!correspondenceRelationshipResults || !correspondenceRelationshipSearch) return;
  const query = correspondenceRelationshipSearch.value.trim().toLowerCase();
  const selectedId = String(correspondenceRelationshipSelect?.value || '').trim();
  const matches = correspondenceRelationshipOptions()
    .filter((item) => {
      if(!query) return true;
      return [item.label, item.email, item.summary].some((value) => String(value || '').toLowerCase().includes(query));
    })
    .slice(0, 8);
  correspondenceRelationshipResults.innerHTML = '';
  if(!open || !matches.length){
    correspondenceRelationshipResults.hidden = true;
    correspondenceRelationshipSearch.setAttribute('aria-expanded', 'false');
    return;
  }
  matches.forEach((item) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.relationshipResultId = item.id;
    button.setAttribute('aria-pressed', String(item.id === selectedId));
    const label = document.createElement('strong');
    label.textContent = item.label;
    const meta = document.createElement('small');
    meta.textContent = [item.email, item.summary].filter(Boolean).join(' · ');
    button.append(label, meta);
    correspondenceRelationshipResults.appendChild(button);
  });
  correspondenceRelationshipResults.hidden = false;
  correspondenceRelationshipSearch.setAttribute('aria-expanded', 'true');
}

function correspondenceChooseRelationship(id = ''){
  const option = correspondenceRelationshipOptions().find((item) => item.id === id);
  if(!option) return;
  if(correspondenceRelationshipSelect) correspondenceRelationshipSelect.value = option.id;
  if(correspondenceRelationshipSearch) correspondenceRelationshipSearch.value = option.label;
  if(correspondenceRelationshipResults) correspondenceRelationshipResults.hidden = true;
  correspondenceRelationshipSearch?.setAttribute('aria-expanded', 'false');
}

function renderCorrespondenceContextControls(){
  if(correspondenceRelationshipSelect && correspondenceRelationshipSearch){
    const selected = correspondenceRelationshipOptions().find((item) => item.id === correspondenceRelationshipSelect.value);
    if(selected && !correspondenceRelationshipSearch.value.trim()) correspondenceRelationshipSearch.value = selected.label;
    correspondenceSetRelationshipSearch(false);
  }else{
    correspondencePopulateSelect(correspondenceRelationshipSelect, Object.values(relationshipIndexProfiles || {}), 'Choose relationship');
  }
  correspondencePopulateSelect(correspondenceProjectSelect, Object.values(projectIndexProfiles || {}), 'Choose project');
}

function correspondenceRuleLabel(rule = {}){
  return correspondenceCompactText(rule.ruleName || rule.rule_name || rule.plainEnglish || rule.confirmationQuestion || 'Email rule', 140);
}

function correspondenceDraftRuleText(){
  const draftRule = currentCorrespondenceRules.find((rule) => {
    const type = String(rule.ruleType || rule.rule_type || '').toLowerCase();
    const action = String(rule.actions?.action || rule.actions_json?.action || '').toLowerCase();
    return rule.isActive !== false && (type === 'draft_style' || action === 'apply_draft_style');
  });
  return draftRule?.actions?.draft_style || draftRule?.actions_json?.draft_style || draftRule?.ruleName || draftRule?.rule_name || '';
}

function correspondenceDraftRuleCategories(){
  return correspondenceDraftRuleFields.reduce((categories, field) => {
    const key = field.dataset.correspondenceWritingRule || '';
    if(key) categories[key] = field.value.trim();
    return categories;
  }, {});
}

const CORRESPONDENCE_WRITING_RULE_MAPS = {
  warm_direct:{
    tone:'Warm, direct, calm, and human.',
    signoff:'Jessa',
    use:'Clear next steps, plain language, and a gracious but efficient opening.',
    avoid:'Corporate polish, over-apologizing, vague enthusiasm, and filler.',
    length:'Short unless the email needs context.'
  },
  brief_executive:{
    tone:'Concise, decisive, and respectful.',
    signoff:'Jessa',
    use:'One clear answer, one next step, and only the necessary context.',
    avoid:'Long explanations, hedging, and repeating the sender back to themselves.',
    length:'Very brief by default.'
  },
  relationship_care:{
    tone:'Warm, thoughtful, and relationship-aware.',
    signoff:'Jessa',
    use:'Acknowledgment, appreciation, and a clear next step that protects the relationship.',
    avoid:'Cold efficiency, transactional phrasing, and sounding rushed.',
    length:'Moderate, with enough context to feel cared for.'
  },
  firm_boundary:{
    tone:'Kind, firm, and clean.',
    signoff:'Jessa',
    use:'A clear boundary, what is possible, and the next practical step.',
    avoid:'Over-explaining, softening the answer until it becomes unclear, and defensive language.',
    length:'Short and definitive.'
  },
  detail_when_needed:{
    tone:'Clear, organized, and grounded.',
    signoff:'Jessa',
    use:'Bullet-like structure, specific facts from the thread, and explicit decisions or questions.',
    avoid:'Inventing facts, burying the ask, and generic summary.',
    length:'Detailed only when the thread requires it.'
  }
};

function applyCorrespondenceWritingRuleMap(mapId = ''){
  const map = CORRESPONDENCE_WRITING_RULE_MAPS[mapId];
  if(!map) return;
  correspondenceDraftRuleFields.forEach((field) => {
    const key = field.dataset.correspondenceWritingRule || '';
    if(key && map[key]) field.value = map[key];
  });
  renderCorrespondenceWritingRuleSummary();
}

function correspondenceDraftRuleSummary(categories = correspondenceDraftRuleCategories(), notes = String(correspondenceDraftRules?.value || '').trim()){
  return [
    categories.tone && 'Tone: ' + categories.tone,
    categories.signoff && 'Sign-off: ' + categories.signoff,
    categories.use && 'Use: ' + categories.use,
    categories.avoid && 'Avoid: ' + categories.avoid,
    categories.length && 'Length: ' + categories.length,
    notes && 'Other rules: ' + notes
  ].filter(Boolean).join('\n');
}

function correspondenceStoredDraftRule(){
  return currentCorrespondenceRules.find((rule) => {
    const type = String(rule.ruleType || rule.rule_type || '').toLowerCase();
    const action = String(rule.actions?.action || rule.actions_json?.action || '').toLowerCase();
    return rule.isActive !== false && (type === 'draft_style' || action === 'apply_draft_style');
  }) || null;
}

function populateCorrespondenceDraftRuleFields(){
  const rule = correspondenceStoredDraftRule();
  const actions = rule?.actions || rule?.actions_json || {};
  const categories = actions.draft_style_categories || actions.draftStyleCategories || {};
  if(correspondenceWritingRuleMap) correspondenceWritingRuleMap.value = '';
  correspondenceDraftRuleFields.forEach((field) => {
    const key = field.dataset.correspondenceWritingRule || '';
    field.value = categories?.[key] || '';
  });
  if(correspondenceDraftRules){
    const hasCategories = Object.values(categories || {}).some(Boolean);
    correspondenceDraftRules.value = actions.draft_style_notes || actions.draftStyleNotes || (hasCategories ? '' : (actions.draft_style || correspondenceDraftRuleText() || ''));
  }
  renderCorrespondenceWritingRuleSummary();
}

function correspondenceActiveDraftRuleText(){
  const fieldsText = correspondenceDraftRuleSummary();
  return fieldsText || correspondenceDraftRuleText();
}

function renderCorrespondenceWritingRuleSummary(){
  if(!correspondenceWritingRulesSummary) return;
  const text = correspondenceActiveDraftRuleText();
  correspondenceWritingRulesSummary.textContent = text || 'No saved Executive Inbox tone rules yet.';
}

function renderCorrespondenceRulesPanel(){
  if(!correspondenceRulesList) return;
  correspondenceRulesList.innerHTML = '';
  const rules = currentCorrespondenceRules.filter((rule) => rule.isActive !== false);
  if(!rules.length){
    const empty = document.createElement('p');
    empty.className = 'correspondence-side-empty';
    empty.textContent = 'No saved Executive Inbox rules yet.';
    correspondenceRulesList.appendChild(empty);
    return;
  }
  rules.slice(0, 80).forEach((rule) => {
    const article = document.createElement('article');
    const title = document.createElement('strong');
    title.textContent = correspondenceRuleLabel(rule);
    const meta = document.createElement('p');
    const action = rule.actions?.action || rule.actions_json?.action || rule.ruleType || rule.rule_type || 'review';
    const condition = rule.conditions?.from_email || rule.conditions_json?.from_email || rule.conditions?.from_domain || rule.conditions_json?.from_domain || rule.conditions?.subject_contains || rule.conditions_json?.subject_contains || 'Executive Inbox';
    const type = String(rule.ruleType || rule.rule_type || '').toLowerCase();
    if(type === 'draft_style' || String(action).toLowerCase() === 'apply_draft_style'){
      const actions = rule.actions || rule.actions_json || {};
      meta.textContent = 'Applies to private Executive Inbox reply drafts and Discuss with VAL on selected email threads.';
      const detail = document.createElement('pre');
      detail.textContent = actions.draft_style || correspondenceRuleLabel(rule);
      const rowActions = document.createElement('div');
      rowActions.className = 'correspondence-rule-row-actions';
      const deleteButton = document.createElement('button');
      deleteButton.type = 'button';
      deleteButton.textContent = 'Delete rule';
      deleteButton.dataset.correspondenceRuleDelete = rule.id || '';
      rowActions.append(deleteButton);
      article.append(title, meta, detail, rowActions);
      correspondenceRulesList.appendChild(article);
      return;
    }
    meta.textContent = [String(action).replace(/_/g, ' '), condition].filter(Boolean).join(' · ');
    const rowActions = document.createElement('div');
    rowActions.className = 'correspondence-rule-row-actions';
    const deleteButton = document.createElement('button');
    deleteButton.type = 'button';
    deleteButton.textContent = 'Delete rule';
    deleteButton.dataset.correspondenceRuleDelete = rule.id || '';
    rowActions.append(deleteButton);
    article.append(title, meta, rowActions);
    correspondenceRulesList.appendChild(article);
  });
}

function setCorrespondenceRulesPanel(open){
  if(!correspondenceRulesPanel) return;
  correspondenceRulesPanel.hidden = !open;
  correspondenceRulesPanel.setAttribute('aria-hidden', String(!open));
  if(open){
    setCorrespondenceRuleComposerPanel(false);
    setCorrespondenceWritingRulesPanel(false);
    renderCorrespondenceRulesPanel();
  }
}

function toggleCorrespondenceRulesPanel(){
  if(!correspondenceRulesPanel) return;
  setCorrespondenceRulesPanel(correspondenceRulesPanel.hidden);
}

function setCorrespondenceRuleComposerPanel(open){
  if(!correspondenceRuleComposerPanel) return;
  correspondenceRuleComposerPanel.hidden = !open;
  correspondenceRuleComposerPanel.setAttribute('aria-hidden', String(!open));
  if(open){
    setCorrespondenceRulesPanel(false);
    setCorrespondenceWritingRulesPanel(false);
    if(correspondenceRuleInstruction && activeCorrespondenceItem){
      const sender = activeCorrespondenceItem.senderName || activeCorrespondenceItem.senderEmail || 'this sender';
      correspondenceRuleInstruction.placeholder = 'Example: When ' + sender + ' emails about scheduling, prepare a concise review-only reply with the next step.';
    }
    window.requestAnimationFrame(() => correspondenceRuleInstruction?.focus());
  }
}

function setCorrespondenceWritingRulesPanel(open){
  if(!correspondenceWritingRulesPanel) return;
  correspondenceWritingRulesPanel.hidden = !open;
  correspondenceWritingRulesPanel.setAttribute('aria-hidden', String(!open));
  if(open){
    setCorrespondenceRuleComposerPanel(false);
    setCorrespondenceRulesPanel(false);
    populateCorrespondenceDraftRuleFields();
    window.requestAnimationFrame(() => (correspondenceDraftRuleFields[0] || correspondenceDraftRules)?.focus());
  }
}

function toggleCorrespondenceWritingRulesPanel(){
  if(!correspondenceWritingRulesPanel) return;
  setCorrespondenceWritingRulesPanel(correspondenceWritingRulesPanel.hidden);
}

function normalizeCorrespondenceRuleSuggestion(suggestion, source = 'val'){
  if(typeof suggestion === 'string'){
    return {text:correspondenceCompactText(suggestion, 220), raw:{plainEnglish:suggestion}, source};
  }
  const text = suggestion?.confirmationQuestion || suggestion?.plainEnglish || suggestion?.ruleName || '';
  return {text:correspondenceCompactText(text, 220), raw:suggestion || {}, source};
}

function correspondenceRuleSuggestionRows(item = activeCorrespondenceItem){
  const itemSuggestions = (item?.ruleSuggestions || []).map((suggestion) => normalizeCorrespondenceRuleSuggestion(suggestion, 'thread'));
  const analyzedSuggestions = currentCorrespondenceRuleSuggestions.map((suggestion) => normalizeCorrespondenceRuleSuggestion(suggestion, 'analysis'));
  return itemSuggestions.concat(analyzedSuggestions).filter((suggestion) => suggestion.text && !dismissedCorrespondenceRuleSuggestions.has(suggestion.text));
}

function renderCorrespondenceRuleSuggestions(item = activeCorrespondenceItem){
  if(!correspondenceRuleSuggestions) return;
  correspondenceRuleSuggestions.innerHTML = '';
  const suggestions = correspondenceRuleSuggestionRows(item);
  if(!suggestions.length){
    const empty = document.createElement('p');
    empty.className = 'correspondence-side-empty';
    empty.textContent = 'No reusable rule suggested yet.';
    correspondenceRuleSuggestions.appendChild(empty);
    return;
  }
  suggestions.forEach((suggestion, index) => {
    const article = document.createElement('article');
    article.className = 'correspondence-rule-suggestion';
    const p = document.createElement('p');
    p.textContent = suggestion.text;
    const actions = document.createElement('div');
    const yes = document.createElement('button');
    yes.type = 'button';
    yes.textContent = 'Yes';
    yes.dataset.correspondenceSuggestionAccept = String(index);
    const no = document.createElement('button');
    no.type = 'button';
    no.textContent = 'No';
    no.dataset.correspondenceSuggestionDismiss = String(index);
    actions.append(yes, no);
    article.append(p, actions);
    correspondenceRuleSuggestions.appendChild(article);
  });
}

function renderCorrespondenceIntelligence(item = activeCorrespondenceItem){
  renderCorrespondenceContextControls();
  renderCorrespondenceSideList(correspondenceRelationships, item?.relationships || [], 'No relationship match yet.');
  renderCorrespondenceSideList(correspondenceProjects, item?.projects || [], 'No project match yet.');
  renderCorrespondenceRuleSuggestions(item);
  if(correspondenceRuleStatus){
    const activeCount = currentCorrespondenceRules.filter((rule) => rule.isActive !== false).length;
    correspondenceRuleStatus.textContent = activeCount ? 'View ' + activeCount + ' active rule' + (activeCount === 1 ? '' : 's') : 'No saved rules yet';
  }
  if(correspondenceRulesPanel && !correspondenceRulesPanel.hidden) renderCorrespondenceRulesPanel();
}

function renderCorrespondenceBrief(item = activeCorrespondenceItem){
  activeCorrespondenceItem = item || currentCorrespondenceItems[0] || null;
  renderCorrespondenceList();
  const selected = activeCorrespondenceItem;
  setCorrespondenceField('status', selected ? (selected.status === 'waiting_for_response' ? 'Waiting for response' : (selected.status === 'needs_context' ? 'Needs context' : 'Ready')) : 'Clear');
  setCorrespondenceField('title', selected?.title || 'No Executive Inbox conversations');
  setCorrespondenceField('summary', selected?.summary || 'Nothing needs your attention right now.');
  const selectedPriority = selected?.priority || (selected?.status === 'needs_context' ? 'Medium' : selected ? 'High' : 'Clear');
  const lastContact = selected?.receivedAt || selected?.lastContact || selected?.date || '—';
  const sourceLabel = selected?.provider === 'gmail' || selected?.source === 'gmail' || selected?.source === 'local_preview' ? 'Gmail' : (selected?.provider || selected?.source || 'Gmail');
  const relationshipState = (selected?.relationships || []).length ? 'Active' : 'Unlinked';
  setCorrespondenceField('priority', selectedPriority.charAt(0).toUpperCase() + selectedPriority.slice(1));
  setCorrespondenceField('last-contact', correspondenceHumanContactTime(lastContact) || '—');
  setCorrespondenceField('source', sourceLabel);
  setCorrespondenceField('relationship-state', relationshipState);
  setCorrespondenceField('decision-summary', correspondenceConversationSummary(selected));
  const hasDraft = !!String(selected?.draftBody || '').trim();
  setCorrespondenceField('draft-title', selected && hasDraft ? 'Reply: ' + (selected.title || 'prepared draft') : 'Reply for review');
  setCorrespondenceField('draft-note', selected?.draftFailureMessage || (selected && hasDraft ? 'Editable private draft. Nothing sends until approved.' : 'No private draft is waiting for review.'));
  renderCorrespondenceThread(selected);
  renderCorrespondenceIntelligence(selected);
  if(correspondenceDraftBody){
    correspondenceDraftBody.value = selected?.draftBody || '';
    correspondenceDraftBody.disabled = !selected;
    correspondenceDraftBody.placeholder = selected ? (hasDraft ? 'Write or edit the reply here.' : (selected.draftFailureMessage || 'No draft has been prepared for this conversation yet.')) : 'Select a conversation to edit the draft.';
  }
  if(correspondenceSafety) correspondenceSafety.textContent = '';
  document.querySelectorAll('.correspondence-actions [data-correspondence-action], .correspondence-intelligence [data-correspondence-action]').forEach((button) => {
    const action = button.dataset.correspondenceAction;
    const isDraftSend = action === 'send' && button.closest('.correspondence-actions');
    const allowed = correspondenceSuggestedActions(selected).includes(action) || isDraftSend;
    button.hidden = !allowed;
    button.disabled = !allowed || (isDraftSend && !hasDraft);
    button.setAttribute('aria-hidden', String(!allowed));
  });
  if(selected && !selected.threadHydrated) hydrateSelectedCorrespondenceThread(selected);
}

function showCorrespondenceLocalBoundary(action, item = activeCorrespondenceItem){
  if(!item) return;
  const needs = action === 'generate'
    ? 'I can only prepare a fresh saved draft when this item has a live conversation id. This preview already has private draft language ready for review.'
    : action === 'send'
      ? 'This draft needs a recipient and message before it can be sent.'
      : 'I can only tighten a saved draft when this item has a draft id. This preview draft is private preparation inside VAL, and no saved draft record was changed.';
  if(correspondenceSafety){
    correspondenceSafety.textContent = needs;
  }
}

function correspondencePacketSource(packet = {}){
  return packet.sourceContextJson || packet.source_context_json || {};
}

function sendPacketForDraft(packets = [], draftId = ''){
  return packets.find((packet) => {
    const source = correspondencePacketSource(packet);
    return packet.actionType === 'send_email' && String(source.draftId || source.draft_id || '') === String(draftId);
  }) || null;
}

function correspondenceSendPayload(item = activeCorrespondenceItem){
  if(!item) return null;
  const raw = item.raw || {};
  const source = raw.sourceContext || raw.source_context || {};
  const draft = source.writerOutput || source.draft || {};
  const subject = item.title || raw.subject || draft.subject || 'VAL follow-up';
  const body = correspondenceDraftBody?.value || item.draftBody || raw.body || draft.body || item.prepared || '';
  const recipientEmail = item.recipientEmail || source.to || source.recipientEmail || source.recipient || source.forwardTo || '';
  return {
    to: recipientEmail,
    subject,
    body,
    provider: item.provider || source.provider || raw.provider || 'gmail',
    threadId: item.threadId || source.threadId || '',
    messageId: source.messageId || '',
    sourceContext: {
      source: 'hearth_executive_inbox',
      draftId: item.draftId || '',
      readyForYouId: item.readyForYouId || '',
      conversationId: item.conversationId || '',
      originalSource: item.source || ''
    },
    sourceRefs: (item.evidence || []).map((line, index) => ({
      source_type: 'hearth_executive_inbox',
      source_id: item.id || item.draftId || 'hearth-correspondence',
      quote_or_summary: line,
      confidence: index === 0 ? 0.9 : 0.75
    })),
    finalApprovalSurface: 'hearth_executive_inbox_drawer'
  };
}

function correspondenceSuppressionContact(item = activeCorrespondenceItem){
  if(!item) return {};
  const source = item.raw?.sourceContext || item.raw?.source_context || {};
  const conversation = source.conversationContext || {};
  const latestInbound = conversation.latest_inbound || conversation.current_message || {};
  const from = latestInbound.from || latestInbound.sender || {};
  const senderEmail = from.email || source.from?.email || source.senderEmail || source.classification?.from?.email || '';
  const senderName = from.name || source.from?.name || source.senderName || source.classification?.from?.name || '';
  const domain = String(senderEmail || '').split('@')[1] || '';
  const local = String(senderEmail || '').split('@')[0] || '';
  const genericSender = /^(info|support|hello|sales|admin|team|contact|office|newsletter|marketing|events?|webinars?|community|billing|invoice|payments?|orders?|receipts?|security|alerts?|updates?|notifications?|notify|no.?reply|donotreply|do.?not.?reply)$/i.test(local) || (!senderName && !!domain);
  return {
    email: senderEmail || item.recipientEmail || source.recipientEmail || '',
    name: senderName || item.recipientName || source.recipientName || '',
    domain,
    suppressDomain: genericSender,
    reason: 'User marked this sender as not an executive contact from the Hearth Executive Inbox.',
    conversationId: item.conversationId || source.conversationId || '',
    threadId: item.threadId || source.threadId || '',
    sourceItemId: item.id || ''
  };
}

function correspondenceSafeContact(item = activeCorrespondenceItem){
  const contact = correspondenceSuppressionContact(item);
  return {
    email: contact.email || item?.senderEmail || item?.recipientEmail || '',
    name: contact.name || item?.senderName || item?.title || '',
    sourceItemId: item?.id || '',
    threadId: item?.threadId || '',
    messageId: item?.messageId || '',
    reason: 'User marked this sender as an Executive Inbox contact from Hearth.'
  };
}

function correspondenceExecutionMessage(result = {}){
  if(result.executed){
    return result.packet?.providerResponseSummary || result.receipt?.providerResponseSummary || 'Sent.';
  }
  const errors = result.risk_check?.errors || [];
  if(errors.includes('payload.to') || result.risk_check?.missing?.includes('payload.to')){
    return 'Send approval was captured, but VAL could not send because the recipient is missing.';
  }
  if(errors.includes('unsupported_adapter')){
    return 'Send approval was captured, but this email provider is not enabled for sending yet.';
  }
  if(errors.includes('final_confirmation_required') || errors.includes('final_send_confirmation_required')){
    return 'Send approval was captured, but final confirmation is still required.';
  }
  return 'Send approval was recorded, but the email was not sent: ' + (result.error || errors.join(', ') || result.packet?.failureReason || 'provider execution did not finish.');
}

function correspondenceRuleEmail(item = activeCorrespondenceItem){
  const email = String(item?.senderEmail || item?.recipientEmail || '').trim();
  const name = String(item?.senderName || item?.title || '').trim();
  return {from:{email,name}};
}

async function hydrateCorrespondenceRules(){
  if(!canUseApi){
    currentCorrespondenceRules = [];
    if(correspondenceRuleStatus) correspondenceRuleStatus.textContent = 'Rules load when VAL is connected';
    renderCorrespondenceIntelligence(activeCorrespondenceItem);
    return;
  }
  try{
    const data = await getJson('/api/email/rules');
    currentCorrespondenceRules = Array.isArray(data.rules) ? data.rules : [];
    if(correspondenceWritingRulesPanel && !correspondenceWritingRulesPanel.hidden) populateCorrespondenceDraftRuleFields();
  }catch(error){
    currentCorrespondenceRules = [];
    if(correspondenceRuleStatus) correspondenceRuleStatus.textContent = 'Rules unavailable';
  }
  renderCorrespondenceIntelligence(activeCorrespondenceItem);
}

function correspondenceRulePayloadFromText(ruleText = '', item = activeCorrespondenceItem){
  const text = String(ruleText || '').trim();
  const email = correspondenceRuleEmail(item);
  const directForwardMatch = text.match(/forward[\s\S]*?from\s+([^\s,;]+@[^\s,;]+)[\s\S]*?\bto\s+([^\s,;]+@[^\s,;]+)/i);
  const selectedForwardMatch = text.match(/\bto\s+([^\s,;]+@[^\s,;]+)/i);
  if(/forward/i.test(text) && (directForwardMatch || (selectedForwardMatch && email.from.email))){
    const fromEmail = directForwardMatch?.[1] || email.from.email;
    const forwardTo = directForwardMatch?.[2] || selectedForwardMatch?.[1] || '';
    return {
      provider:'any',
      ruleName:text,
      ruleType:'forward_sender',
      conditions:{from_email:fromEmail},
      actions:{action:'forward',forward_to:forwardTo,include_summary:true,cc_user:false},
      approvalMode:'review_only',
      confidenceThreshold:'high',
      createdFrom:'executive_inbox_rule_learning',
      createdFromMessageId:item?.messageId || '',
      createdFromThreadId:item?.threadId || ''
    };
  }
  if(/ignore|low priority|downgrade/i.test(text) && email.from.email){
    return {
      provider:'any',
      ruleName:text,
      ruleType:'ignore_sender',
      conditions:{from_email:email.from.email},
      actions:{action:'label',label:'low_priority'},
      approvalMode:'review_only',
      confidenceThreshold:'medium',
      createdFrom:'executive_inbox_rule_learning',
      createdFromMessageId:item?.messageId || '',
      createdFromThreadId:item?.threadId || ''
    };
  }
  return {
    provider:'any',
    ruleName:text,
    ruleType:'plain_english_instruction',
    conditions:email.from.email ? {from_email:email.from.email} : {source:'executive_inbox'},
    actions:{action:'manual_instruction',instruction:text},
    approvalMode:'review_only',
    confidenceThreshold:'medium',
    createdFrom:'executive_inbox_rule_learning',
    createdFromMessageId:item?.messageId || '',
    createdFromThreadId:item?.threadId || ''
  };
}

function correspondenceRulePayloadFromSuggestion(suggestion = {}, item = activeCorrespondenceItem){
  const raw = suggestion.raw || suggestion;
  const text = suggestion.text || raw.confirmationQuestion || raw.plainEnglish || raw.ruleName || '';
  if(raw.conditions || raw.actions || raw.suggestedRuleType){
    return {
      provider:'any',
      ruleName:text,
      ruleType:raw.suggestedRuleType || raw.ruleType || 'suggested_rule',
      conditions:raw.conditions || {},
      actions:raw.actions || {action:'manual_instruction',instruction:text},
      approvalMode:'review_only',
      confidenceThreshold:raw.confidence || 'medium',
      createdFrom:'executive_inbox_val_suggestion',
      createdFromMessageId:item?.messageId || '',
      createdFromThreadId:item?.threadId || ''
    };
  }
  return correspondenceRulePayloadFromText(text, item);
}

async function saveCorrespondenceRulePayload(payload, successText){
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The local VAL server is needed to save rules. Nothing was changed.';
    return null;
  }
  if(correspondenceSafety) correspondenceSafety.textContent = 'Saving rule. Approval boundaries still apply.';
  const result = await postJson('/api/email/rules', payload);
  if(result.rule) currentCorrespondenceRules = [result.rule].concat(currentCorrespondenceRules.filter((rule) => rule.id !== result.rule?.id));
  if(correspondenceSafety) correspondenceSafety.textContent = successText || 'Saved rule: ' + correspondenceRuleLabel(result.rule || payload) + '.';
  renderCorrespondenceIntelligence(activeCorrespondenceItem);
  return result.rule || payload;
}

async function deleteCorrespondenceRule(ruleId){
  const id = String(ruleId || '').trim();
  if(!id){
    if(correspondenceSafety) correspondenceSafety.textContent = 'VAL could not identify that rule.';
    return;
  }
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The local VAL server is needed to delete rules. Nothing was changed.';
    return;
  }
  if(correspondenceSafety) correspondenceSafety.textContent = 'Deleting rule. Past evidence stays intact.';
  const result = await patchJson('/api/email/rules/' + encodeURIComponent(id), {isActive:false});
  if(result.ok === false) throw new Error(result.error || 'Rule delete failed.');
  currentCorrespondenceRules = currentCorrespondenceRules.map((rule) => rule.id === id ? {...rule,isActive:false,is_active:false} : rule);
  renderCorrespondenceRulesPanel();
  renderCorrespondenceIntelligence(activeCorrespondenceItem);
  if(correspondenceSafety) correspondenceSafety.textContent = 'Rule deleted. VAL will stop applying it going forward.';
}

async function saveCorrespondenceDraftRules(){
  const categories = correspondenceDraftRuleCategories();
  const notes = String(correspondenceDraftRules?.value || '').trim();
  const text = correspondenceDraftRuleSummary(categories, notes);
  if(!text){
    if(correspondenceSafety) correspondenceSafety.textContent = 'Add the writing guidance you want VAL to remember before saving.';
    return null;
  }
  const existing = currentCorrespondenceRules.find((rule) => {
    const type = String(rule.ruleType || rule.rule_type || '').toLowerCase();
    const action = String(rule.actions?.action || rule.actions_json?.action || '').toLowerCase();
    return type === 'draft_style' || action === 'apply_draft_style';
  });
  const saved = await saveCorrespondenceRulePayload({
    id: existing?.id || '',
    provider:'any',
    ruleName:'Executive Inbox tone rules',
    ruleType:'draft_style',
    conditions:{surface:'executive_inbox'},
    actions:{action:'apply_draft_style', draft_style:text, draft_style_categories:categories, draft_style_notes:notes},
    approvalMode:'review_only',
    confidenceThreshold:'high',
    createdFrom:'executive_inbox_writing_rules'
  }, 'Saved Executive Inbox tone rules. VAL will use them when preparing review drafts.');
  if(saved){
    renderCorrespondenceWritingRuleSummary();
    setCorrespondenceWritingRulesPanel(false);
    setCorrespondenceRulesPanel(true);
  }
  return saved;
}

async function saveCorrespondenceForwardRule(item = activeCorrespondenceItem){
  const ruleText = String(correspondenceForwardTo?.value || '').trim();
  if(!ruleText){
    if(correspondenceSafety) correspondenceSafety.textContent = 'Type the rule you want VAL to remember.';
    return;
  }
  const payload = correspondenceRulePayloadFromText(ruleText, item);
  const saved = await saveCorrespondenceRulePayload(payload, 'Saved rule: ' + ruleText + '.');
  if(saved && correspondenceForwardTo) correspondenceForwardTo.value = '';
}

async function saveCorrespondenceComposedRule(item = activeCorrespondenceItem){
  const ruleText = String(correspondenceRuleInstruction?.value || '').trim();
  const appliesTo = String(correspondenceRuleFunction?.value || 'replies').trim();
  if(!ruleText){
    if(correspondenceSafety) correspondenceSafety.textContent = 'Type the rule VAL should remember before saving.';
    return null;
  }
  const labels = {
    replies:'Replies',
    scheduling:'Scheduling',
    introductions:'Introductions',
    forwarding:'Forwarding',
    executive_inbox:'Executive Inbox admission'
  };
  const payload = correspondenceRulePayloadFromText(ruleText, item);
  payload.ruleName = (labels[appliesTo] || 'Executive Inbox') + ': ' + correspondenceCompactText(ruleText, 120);
  payload.ruleType = appliesTo;
  payload.conditions = {...(payload.conditions || {}), function:appliesTo};
  payload.actions = {...(payload.actions || {}), action:payload.actions?.action || 'manual_instruction', function:appliesTo, instruction:ruleText};
  payload.createdFrom = 'executive_inbox_rule_composer';
  const saved = await saveCorrespondenceRulePayload(payload, 'Saved ' + (labels[appliesTo] || 'Executive Inbox') + ' rule. VAL will show it under View rules and apply it inside review boundaries.');
  if(saved){
    if(correspondenceRuleInstruction) correspondenceRuleInstruction.value = '';
    setCorrespondenceRuleComposerPanel(false);
    setCorrespondenceRulesPanel(true);
  }
  return saved;
}

async function saveCorrespondenceSafeContact(item = activeCorrespondenceItem){
  const typedEmail = String(correspondenceSafeEmail?.value || '').trim();
  const contact = typedEmail ? {email:typedEmail, name:typedEmail, reason:'User manually added this sender as an Executive Inbox contact from Hearth.'} : correspondenceSafeContact(item);
  if(!contact.email){
    if(correspondenceSafety) correspondenceSafety.textContent = 'Type an email address or select a thread before saving an Executive contact.';
    return;
  }
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The local VAL server is needed to save Executive contacts.';
    return;
  }
  const result = await postJson('/api/val/executive-inbox/safe-contact', contact);
  if(result.ok !== false && correspondenceSafeEmail) correspondenceSafeEmail.value = '';
  if(correspondenceSafety) correspondenceSafety.textContent = 'Saved ' + (contact.name || contact.email) + ' as an Executive Inbox contact.';
}

function correspondenceEmailForAction(item = activeCorrespondenceItem){
  if(!item) return {};
  const raw = item.raw || {};
  return {
    ...raw,
    provider:item.provider || raw.provider || 'gmail',
    messageId:item.messageId || raw.messageId || '',
    threadId:item.threadId || raw.threadId || '',
    subject:item.title || raw.subject || '',
    from:raw.from || {name:item.senderName || '', email:item.senderEmail || item.recipientEmail || ''},
    snippet:raw.snippet || item.summary || '',
    bodyPreview:raw.bodyPreview || raw.body_preview || item.threadMessages?.[0]?.body || item.summary || '',
    webLink:raw.webLink || ''
  };
}

async function searchCorrespondenceInbox(){
  const query = String(correspondenceSearchInput?.value || '').trim();
  if(!query){
    if(correspondenceSafety) correspondenceSafety.textContent = 'Type what you remember about the email before searching.';
    return;
  }
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The local VAL server is needed to search the connected inbox.';
    return;
  }
  if(correspondenceSafety) correspondenceSafety.textContent = 'Searching connected inboxes for: ' + query;
  const result = await postJson('/api/email/inbox-command', {query, maxResults:8}, {timeoutMs:45000, timeoutMessage:'Inbox search took longer than expected.'});
  const rows = (result.emails || result.results || []).map((email, index) => normalizeCorrespondenceEmailItem({...email, classification:'needs_attention', reason:'Found by inbox search: ' + query, recommendedAction:'Review this search result in Executive Inbox.'}, index));
  const byId = new Map(rows.concat(currentCorrespondenceItems).map((item) => [item.id, item]));
  currentCorrespondenceItems = Array.from(byId.values());
  activeCorrespondenceItem = rows[0] || activeCorrespondenceItem || currentCorrespondenceItems[0] || null;
  renderCorrespondenceBrief(activeCorrespondenceItem);
  if(correspondenceSafety) correspondenceSafety.textContent = result.answer || (rows.length ? 'Found ' + rows.length + ' inbox result' + (rows.length === 1 ? '' : 's') + '.' : 'No matching inbox messages found.');
}

async function draftCorrespondenceReply(item = activeCorrespondenceItem, options = {}){
  if(!item) return;
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The local VAL server is needed to prepare a reply draft.';
    return;
  }
  if(correspondenceSafety) correspondenceSafety.textContent = options.automatic ? 'Preparing a private reply draft with your saved Tone Rules. Nothing will be sent.' : 'Preparing a private reply draft. Nothing will be sent.';
  let result = null;
  if(item.conversationId || item.messageId || item.threadId){
    try{
      result = await postJson('/api/val/email/generate-draft', {
        conversationId:item.conversationId || '',
        messageId:item.messageId || '',
        threadId:item.threadId || '',
        provider:item.provider || '',
        writingRules:correspondenceActiveDraftRuleText()
      });
    }catch(error){
      result = {ok:false, error:error.message};
    }
  }
  const primaryDraft = result?.draft || {};
  const primaryBody = String(primaryDraft.body || result?.writer_output?.body || '').trim();
  if(!primaryBody){
    const message = result?.message || result?.error || 'VAL could not load enough readable thread content to prepare a source-backed draft. Open this thread with VAL or refresh Gmail, then try Draft reply again.';
    const updated = {
      ...item,
      autoDraftAttempted:true,
      autoDraftFailed:true,
      draftStatus:result?.status || 'needs_source_content',
      draftFailureMessage:message,
      status:item.status || 'needs_context'
    };
    currentCorrespondenceItems = currentCorrespondenceItems.map((row) => row.id === item.id ? updated : row);
    activeCorrespondenceItem = updated;
    renderCorrespondenceBrief(updated);
    if(correspondenceSafety) correspondenceSafety.textContent = message + ' No generic reply was created.';
    return;
  }
  const draft = result.draft || result.internalDraft || {};
  const updated = {
    ...item,
    autoDraftAttempted:true,
    draftId:draft.id || item.draftId || '',
    draftBody:draft.body || result.draft?.body || item.draftBody || '',
    title:draft.subject || item.title,
    status:'ready_for_review',
    source:item.source || 'executive_inbox_draft'
  };
  currentCorrespondenceItems = [updated].concat(currentCorrespondenceItems.filter((row) => row.id !== item.id));
  activeCorrespondenceItem = updated;
  renderCorrespondenceBrief(updated);
  if(correspondenceSafety) correspondenceSafety.textContent = 'Private reply draft prepared for review using current Tone Rules. Nothing was sent.';
}

async function forwardCorrespondenceDraft(item = activeCorrespondenceItem){
  if(!item) return;
  const recipient = String(correspondenceForwardTo?.value || '').match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i)?.[0] || '';
  if(!recipient){
    if(correspondenceSafety) correspondenceSafety.textContent = 'Type the forwarding recipient email in the rule/instruction field before forwarding.';
    return;
  }
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The local VAL server is needed to create a forward draft.';
    return;
  }
  if(correspondenceSafety) correspondenceSafety.textContent = 'Creating a private forward draft. Nothing is forwarded automatically.';
  const result = await postJson('/api/email/inbox-command/action', {action:'forward_draft', to:recipient, email:correspondenceEmailForAction(item)});
  const draft = result.draft || {};
  const updated = {
    ...item,
    draftId:draft.id || item.draftId || '',
    draftBody:draft.body || item.draftBody || '',
    title:draft.subject || item.title,
    status:'ready_for_review',
    recipientEmail:recipient
  };
  currentCorrespondenceItems = [updated].concat(currentCorrespondenceItems.filter((row) => row.id !== item.id));
  activeCorrespondenceItem = updated;
  renderCorrespondenceBrief(updated);
  if(correspondenceSafety) correspondenceSafety.textContent = result.warning || 'Private forward draft prepared for ' + recipient + '. Nothing was forwarded.';
}

async function linkCorrespondenceContext(kind = 'relationship', item = activeCorrespondenceItem, target = {}){
  if(!item || !target.id){
    if(correspondenceSafety) correspondenceSafety.textContent = kind === 'project' ? 'Choose or create a project before linking this email.' : 'Choose or create a relationship before linking this email.';
    return null;
  }
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The local VAL server is needed to save email context links.';
    return null;
  }
  const payload = {
    kind,
    targetId:target.id,
    targetName:target.name || '',
    email:correspondenceEmailForAction(item),
    sourceItemId:item.id || '',
    threadId:item.threadId || '',
    messageId:item.messageId || '',
    conversationId:item.conversationId || '',
    summary:item.summary || item.title || ''
  };
  const result = await postJson('/api/val/executive-inbox/link-context', payload);
  const label = target.name || target.id;
  if(kind === 'project'){
    item.projects = Array.from(new Set([...(item.projects || []), label]));
  }else{
    item.relationships = Array.from(new Set([...(item.relationships || []), label]));
  }
  renderCorrespondenceBrief(item);
  if(correspondenceSafety) correspondenceSafety.textContent = result.message || 'Linked this email to ' + label + '.';
  return result;
}

function selectedCorrespondenceRelationship(){
  let id = String(correspondenceRelationshipSelect?.value || '').trim();
  if(!id && correspondenceRelationshipSearch){
    const query = correspondenceRelationshipSearch.value.trim().toLowerCase();
    const exact = query ? correspondenceRelationshipOptions().find((item) => item.label.toLowerCase() === query || String(item.email || '').toLowerCase() === query) : null;
    if(exact) id = exact.id;
  }
  const option = id ? correspondenceRelationshipOptions().find((item) => item.id === id) : null;
  const profile = id ? relationshipIndexProfiles[id] || relationshipIndexSourceProfiles()[id] : null;
  return option || profile ? {id, name:option?.label || correspondenceOptionLabel(profile), email:option?.email || profile?.email || profile?.primaryEmail || ''} : null;
}

function selectedCorrespondenceProject(){
  const id = String(correspondenceProjectSelect?.value || '').trim();
  const profile = id ? projectIndexProfiles[id] || projectProfiles[id] : null;
  return profile ? {id, name:correspondenceOptionLabel(profile)} : null;
}

async function createCorrespondenceRelationship(item = activeCorrespondenceItem){
  if(!item) return;
  const contact = correspondenceSafeContact(item);
  const name = contact.name || contact.email || item.senderName || '';
  const email = contact.email || item.senderEmail || '';
  if(!name && !email){
    if(correspondenceSafety) correspondenceSafety.textContent = 'VAL needs a sender name or email before creating a relationship.';
    return;
  }
  if(correspondenceSafety) correspondenceSafety.textContent = 'Creating a local relationship from this email. No external system changes.';
  const result = await postJson('/api/relationships/network/manual', {name, email, summary:'Created from Executive Inbox thread: ' + (item.title || '')});
  await hydrateRelationshipIndex({force:true}).catch(() => null);
  const relationship = result.relationship || {};
  await linkCorrespondenceContext('relationship', item, {id:relationship.id || relationship.profileId || relationship.email || email, name:relationship.name || name, email});
}

async function createCorrespondenceProject(item = activeCorrespondenceItem){
  if(!item) return;
  const name = String(correspondenceProjectName?.value || '').trim();
  if(!name){
    if(correspondenceSafety) correspondenceSafety.textContent = 'Type a project name before creating it from this email.';
    return;
  }
  if(correspondenceSafety) correspondenceSafety.textContent = 'Creating a local project shell from this email. No external system changes.';
  const payload = new FormData();
  payload.append('name', name);
  payload.append('summary', 'Created from Executive Inbox thread: ' + (item.title || ''));
  payload.append('rawContext', [item.summary, item.threadMessages?.[0]?.body].filter(Boolean).join('\n\n'));
  payload.append('createdFrom', 'executive_inbox_context_link');
  const result = await postFormData('/api/projects/create', payload);
  await hydrateProjectIndex().catch(() => null);
  const project = result.project || {};
  if(correspondenceProjectName) correspondenceProjectName.value = '';
  await linkCorrespondenceContext('project', item, {id:project.id || project.projectId || name, name:project.name || name});
}

async function analyzeCorrespondenceRuleSuggestions(){
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The local VAL server is needed to analyze rule suggestions.';
    return;
  }
  if(correspondenceSafety) correspondenceSafety.textContent = 'Asking VAL to look for repeatable inbox rules.';
  const result = await postJson('/api/email/rule-suggestions/analyze', {});
  currentCorrespondenceRuleSuggestions = Array.isArray(result.suggestions) ? result.suggestions : [];
  if(correspondenceSafety) correspondenceSafety.textContent = currentCorrespondenceRuleSuggestions.length ? 'VAL found ' + currentCorrespondenceRuleSuggestions.length + ' possible rule' + (currentCorrespondenceRuleSuggestions.length === 1 ? '' : 's') + ' for review.' : 'VAL did not find enough repeated evidence for a new rule yet.';
  renderCorrespondenceIntelligence(activeCorrespondenceItem);
}

async function acceptCorrespondenceRuleSuggestion(index){
  const suggestion = correspondenceRuleSuggestionRows(activeCorrespondenceItem)[index];
  if(!suggestion) return;
  const payload = correspondenceRulePayloadFromSuggestion(suggestion, activeCorrespondenceItem);
  const saved = await saveCorrespondenceRulePayload(payload, 'Saved suggested rule: ' + suggestion.text + '.');
  if(saved){
    dismissedCorrespondenceRuleSuggestions.add(suggestion.text);
    renderCorrespondenceIntelligence(activeCorrespondenceItem);
  }
}

function dismissCorrespondenceRuleSuggestion(index){
  const suggestion = correspondenceRuleSuggestionRows(activeCorrespondenceItem)[index];
  if(!suggestion) return;
  dismissedCorrespondenceRuleSuggestions.add(suggestion.text);
  if(correspondenceSafety) correspondenceSafety.textContent = 'Suggestion dismissed.';
  renderCorrespondenceIntelligence(activeCorrespondenceItem);
}

async function hydrateCorrespondenceDrawer(){
  setCorrespondenceLoadingState(true, 'Opening saved Executive Inbox context. Use Scan only when you want a fresh Gmail or Outlook pass.');
  currentCorrespondenceItems = [];
  activeCorrespondenceItem = currentCorrespondenceItems[0] || null;
  renderCorrespondenceBrief(activeCorrespondenceItem);
  void Promise.all([
    hydrateRelationshipIndex({force:false}).catch(() => null),
    hydrateProjectIndex().catch(() => null)
  ]);
  renderCorrespondenceIntelligence(activeCorrespondenceItem);
  if(!canUseApi){
    setCorrespondenceLoadingState(false, 'The live VAL server is needed to load Executive Inbox.');
    hydrateCorrespondenceRules();
    return;
  }
  try{
    const inbox = await getJson('/api/val/executive-inbox/queue?limit=60', {
      timeoutMs:7000,
      timeoutMessage:'Saved Executive Inbox context is taking too long to open.'
    });
    const merged = correspondenceItemsFromEmailIntelligence(inbox);
    const byId = new Map();
    merged.forEach((item) => {
      if(item?.id && !byId.has(item.id)) byId.set(item.id, item);
    });
    currentCorrespondenceItems = Array.from(byId.values());
    activeCorrespondenceItem = currentCorrespondenceItems[0] || null;
    currentCorrespondenceScanStatus = currentCorrespondenceItems.length ? '' : 'No saved conversations currently cross the Executive Inbox judgment gate. Use Scan to refresh Gmail or Outlook.';
    setCorrespondenceLoadingState(false, currentCorrespondenceScanStatus);
    renderCorrespondenceBrief(activeCorrespondenceItem);
    await hydrateCorrespondenceRules();
  }catch(error){
    console.warn('[hearth] correspondence drawer unavailable', error.message);
    currentCorrespondenceItems = [];
    activeCorrespondenceItem = null;
    setCorrespondenceLoadingState(false, 'Executive Inbox could not open saved conversations. Use Scan to refresh Gmail or Outlook.');
    renderCorrespondenceBrief(activeCorrespondenceItem);
    if(correspondenceSafety) correspondenceSafety.textContent = 'Executive Inbox could not open saved conversations. No demo emails are being shown.';
    await hydrateCorrespondenceRules();
  }
}

async function scanCorrespondenceWindow(days = 30){
  const scanDays = Math.max(1, Math.min(90, Number(days) || 30));
  if(!canUseApi){
    currentCorrespondenceScanStatus = 'The local VAL server is needed to scan Gmail.';
    renderCorrespondenceList();
    if(correspondenceSafety) correspondenceSafety.textContent = currentCorrespondenceScanStatus;
    return;
  }
  currentCorrespondenceScanDays = scanDays;
  correspondenceScanInFlight = true;
  setCorrespondenceLoadingState(true, 'Scanning the last ' + scanDays + ' days of connected Gmail. Low-priority mail will stay out of Executive Inbox.');
  renderCorrespondenceList();
  if(correspondenceSafety) correspondenceSafety.textContent = currentCorrespondenceScanStatus;
  try{
    const result = await getJson('/api/val/executive-inbox/queue?refresh=1&days=' + encodeURIComponent(scanDays) + '&limit=' + encodeURIComponent(scanDays >= 90 ? 150 : 90), {timeoutMs:45000, timeoutMessage:'Gmail scan is taking longer than expected.'});
    currentCorrespondenceItems = correspondenceItemsFromEmailIntelligence(result);
    activeCorrespondenceItem = currentCorrespondenceItems[0] || null;
    currentCorrespondenceScanStatus = currentCorrespondenceItems.length
      ? 'Found ' + currentCorrespondenceItems.length + ' Executive Inbox item' + (currentCorrespondenceItems.length === 1 ? '' : 's') + ' in the last ' + scanDays + ' days.'
      : 'Scanned the last ' + scanDays + ' days. No unresolved Gmail threads crossed the Executive Inbox judgment gate.';
    correspondenceScanInFlight = false;
    setCorrespondenceLoadingState(false, currentCorrespondenceScanStatus);
    renderCorrespondenceBrief(activeCorrespondenceItem);
    if(correspondenceSafety){
      correspondenceSafety.textContent = currentCorrespondenceScanStatus;
    }
  }catch(error){
    correspondenceScanInFlight = false;
    currentCorrespondenceScanStatus = 'Gmail scan failed: ' + error.message;
    setCorrespondenceLoadingState(false, currentCorrespondenceScanStatus);
    renderCorrespondenceList();
    if(correspondenceSafety) correspondenceSafety.textContent = currentCorrespondenceScanStatus;
  }
}

function openCorrespondenceReviewWorkspace(item = activeCorrespondenceItem){
  if(!item) return;
  setWorkspaceContent({
    lens: 'Executive Inbox',
    title: item.title || 'Prepared reply ready for review',
    meaning: item.whyNow || item.summary || 'VAL prepared an important reply for review.',
    understanding: [
      item.context,
      item.prepared,
      item.needs,
      'Drafting is private preparation inside VAL; sending represents Jessa externally and still requires explicit approval.'
    ].filter(Boolean),
    recommendation: item.status === 'needs_context' ? 'Provide the missing context before approving any external use.' : 'Review voice, accuracy, and relationship consequence before anything is sent.',
    actions: [
      {label:'Back to Executive Inbox', workflow:'cancel:correspondence'},
      {label:'Teach VAL', workflow:'teach'}
    ],
    label: 'Executive Inbox review workspace',
    returnTarget:'correspondence'
  });
  openWorkspaceShell('Executive Inbox review workspace', {returnTarget:'correspondence'});
}

async function openCorrespondenceThreadCowork(item = activeCorrespondenceItem){
  if(!item) return;
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The local VAL server is needed to prepare this selected thread. Nothing was changed.';
    return;
  }
  const source = item.raw?.sourceContext || item.raw?.source_context || item.raw?.metadataJson || item.raw?.metadata || {};
  const messageId = item.messageId || source.currentMessageId || source.current_message_id || source.messageId || source.conversationContext?.current_message?.messageId || '';
  const threadId = item.threadId || source.threadId || source.conversationContext?.threadId || '';
  const conversationId = item.conversationId || source.conversationId || source.conversationContext?.conversationId || '';
  if(!messageId && !threadId && !conversationId){
    if(correspondenceSafety) correspondenceSafety.textContent = 'VAL needs the durable selected email thread before it can prepare a reply. Nothing was changed.';
    return;
  }
  activeCoworkEntry = {entrypointId:'email.thread',sessionId:'',workItemId:'',emailThreadId:messageId || threadId || conversationId,status:'opening'};
  openContextualCoworkSession({
    returnTarget:'correspondence',
    title:'Prepare reply with VAL',
    meaning:'Holding the readable messages and existing context for this selected Executive Inbox thread.',
    context:[
      'Thread: ' + (item.title || 'Selected email thread'),
      item.senderName || item.senderEmail ? 'Sender: ' + (item.senderName || item.senderEmail) : '',
      item.context ? 'Relationship/project: ' + item.context : '',
      'No email, provider draft, calendar event, CRM record, or task will be changed from this Co-Work.'
    ].filter(Boolean),
    recommendation:'VAL will ask only for the outcome this reply should create, then prepare one private draft for Leverage review.',
    placeholder:'Preparing the selected Executive Inbox thread...',
    heading:'Preparing a reply for ' + (item.title || 'this thread'),
    detail:'This conversation is scoped to one readable Executive Inbox thread.',
    publicDetail:'Scoped to Executive Inbox: selected thread.',
    lockContext:true
  });
  try{
    const result = await postJson('/api/val/cowork/entries/open',{
      entrypointId:'email.thread',
      scope:{
        entityType:'email_thread',
        entityId:messageId || threadId || conversationId,
        sectionId:'reply_draft',
        provider:item.provider || '',
        messageId,
        threadId,
        conversationId
      }
    },{timeoutMs:10000,timeoutMessage:'VAL could not prepare this selected Executive Inbox thread yet.'});
    renderCoworkEntryResult(result,{replaceMessage:true});
  }catch(error){
    activeCoworkEntry = null;
    appendHomeCoworkMessage('val','VAL could not open this selected Executive Inbox thread. Nothing was changed. ' + error.message,{replace:true});
  }
}

async function handleCorrespondenceAction(action){
  if(action === 'show_rules'){
    toggleCorrespondenceRulesPanel();
    return;
  }
  if(action === 'show_writing_rules'){
    toggleCorrespondenceWritingRulesPanel();
    return;
  }
  const item = activeCorrespondenceItem;
  if(action === 'search_inbox'){
    await searchCorrespondenceInbox();
    return;
  }
  if(action === 'save_forward_rule'){
    await saveCorrespondenceForwardRule(item);
    return;
  }
  if(action === 'save_safe_contact'){
    await saveCorrespondenceSafeContact(item);
    return;
  }
  if(action === 'suggest_rules'){
    await analyzeCorrespondenceRuleSuggestions();
    return;
  }
  if(action === 'create_rule'){
    setCorrespondenceRuleComposerPanel(true);
    if(correspondenceSafety) correspondenceSafety.textContent = 'Create a review-only Executive Inbox rule. Nothing will run automatically from this screen.';
    return;
  }
  if(action === 'save_composed_rule'){
    await saveCorrespondenceComposedRule(item);
    return;
  }
  if(action === 'save_draft_rules'){
    await saveCorrespondenceDraftRules();
    return;
  }
  if(!item) return;
  if(action === 'generate'){
    await draftCorrespondenceReply(item);
    return;
  }
  if(action === 'forward'){
    await forwardCorrespondenceDraft(item);
    return;
  }
  if(action === 'link_relationship'){
    await linkCorrespondenceContext('relationship', item, selectedCorrespondenceRelationship() || {});
    return;
  }
  if(action === 'create_relationship'){
    await createCorrespondenceRelationship(item);
    return;
  }
  if(action === 'link_project'){
    await linkCorrespondenceContext('project', item, selectedCorrespondenceProject() || {});
    return;
  }
  if(action === 'create_project'){
    await createCorrespondenceProject(item);
    return;
  }
  if(action === 'not_executive_contact'){
    const contact = correspondenceSuppressionContact(item);
    if(!contact.email && !contact.name){
      if(correspondenceSafety) correspondenceSafety.textContent = 'VAL needs an email or name before it can suppress this sender. Nothing was changed.';
      return;
    }
    if(canUseApi){
      await postJson('/api/val/executive-inbox/not-executive-contact', contact);
    }
    currentCorrespondenceItems = currentCorrespondenceItems.filter((row) => row.id !== item.id);
    activeCorrespondenceItem = currentCorrespondenceItems[0] || null;
    renderCorrespondenceBrief(activeCorrespondenceItem);
    if(correspondenceSafety) correspondenceSafety.textContent = 'Marked ' + (contact.name || contact.email) + ' as not an executive contact.';
    return;
  }
  if(action === 'safe_contact'){
    const contact = correspondenceSafeContact(item);
    if(!contact.email){
      if(correspondenceSafety) correspondenceSafety.textContent = 'VAL needs an email address before it can remember this Executive contact.';
      return;
    }
    if(canUseApi){
      await postJson('/api/val/executive-inbox/safe-contact', contact);
    }
    if(correspondenceSafety) correspondenceSafety.textContent = 'Saved ' + (contact.name || contact.email) + ' as an Executive Inbox contact.';
    return;
  }
  if(action === 'resolve_thread'){
    if(canUseApi){
      await postJson('/api/val/executive-inbox/resolve-thread', {
        provider:item.provider || 'email',
        threadId:item.threadId || '',
        messageId:item.messageId || '',
        sourceItemId:item.id || '',
        reason:'User marked this Executive Inbox thread resolved from Hearth.'
      });
    }
    currentCorrespondenceItems = currentCorrespondenceItems.filter((row) => row.id !== item.id);
    activeCorrespondenceItem = currentCorrespondenceItems[0] || null;
    renderCorrespondenceBrief(activeCorrespondenceItem);
    if(correspondenceSafety) correspondenceSafety.textContent = 'Marked resolved. VAL will keep the thread as evidence, but remove it from the active Executive Inbox.';
    return;
  }
  if(action === 'cowork_correspondence'){
    await openCorrespondenceThreadCowork(item);
    return;
  }
  if(action === 'review'){
    openCorrespondenceReviewWorkspace(item);
    return;
  }
  if(!canUseApi){
    if(correspondenceSafety) correspondenceSafety.textContent = 'The local VAL server is needed to prepare or revise saved drafts. Nothing was sent or changed externally.';
    return;
  }
  try{
    if(action === 'generate'){
      if(!item.conversationId){
        showCorrespondenceLocalBoundary('generate', item);
        return;
      }
      if(correspondenceSafety) correspondenceSafety.textContent = 'Preparing a private draft for review. Nothing will be sent from this click.';
      const result = await postJson('/api/val/email/generate-draft', {conversationId:item.conversationId, writingRules:correspondenceActiveDraftRuleText()});
      if(!String(result?.draft?.body || result?.writer_output?.body || '').trim()){
        const message = result?.message || result?.error || 'VAL could not load enough readable thread content to prepare a source-backed draft. No generic reply was created.';
        activeCorrespondenceItem = {...item, autoDraftAttempted:true, autoDraftFailed:true, draftStatus:result?.status || 'needs_source_content', draftFailureMessage:message, status:item.status || 'needs_context'};
        currentCorrespondenceItems = currentCorrespondenceItems.map((row) => row.id === item.id ? activeCorrespondenceItem : row);
        renderCorrespondenceBrief(activeCorrespondenceItem);
        if(correspondenceSafety) correspondenceSafety.textContent = message;
        return;
      }
      const generated = normalizeCorrespondenceDraft(result.draft || {});
      currentCorrespondenceItems = [generated].concat(currentCorrespondenceItems.filter((row) => row.id !== generated.id));
      activeCorrespondenceItem = generated;
      renderCorrespondenceBrief(generated);
    }
    if(action === 'revise'){
      if(!item.draftId){
        showCorrespondenceLocalBoundary('revise', item);
        return;
      }
      if(correspondenceSafety) correspondenceSafety.textContent = 'Tightening the private draft for review. Nothing will be sent from this click.';
      const result = await postJson('/api/val/email/revise-draft', {draftId:item.draftId});
      const revised = normalizeCorrespondenceDraft(result.draft || {});
      currentCorrespondenceItems = [revised].concat(currentCorrespondenceItems.filter((row) => row.id !== revised.id));
      activeCorrespondenceItem = revised;
      renderCorrespondenceBrief(revised);
    }
    if(action === 'send'){
      const payload = correspondenceSendPayload(item);
      if(!payload?.body){
        showCorrespondenceLocalBoundary('send', item);
        return;
      }
      if(correspondenceSafety) correspondenceSafety.textContent = 'Sending...';
      let sendResult;
      try{
        sendResult = await postJson('/api/val/external-actions/email-send-now', {...payload, approvalNote:'Sent from Executive Inbox.'});
      }catch(executeError){
        sendResult = executeError.data || {ok:false,error:executeError.message};
      }
      if(sendResult.ok && sendResult.executed){
        currentCorrespondenceItems = currentCorrespondenceItems.filter((row) => row.id !== item.id);
        activeCorrespondenceItem = currentCorrespondenceItems[0] || null;
        renderCorrespondenceBrief(activeCorrespondenceItem);
        if(correspondenceSafety) correspondenceSafety.textContent = correspondenceExecutionMessage(sendResult);
        return;
      }
      if(correspondenceSafety) correspondenceSafety.textContent = correspondenceExecutionMessage(sendResult);
    }
  }catch(error){
    if(correspondenceSafety) correspondenceSafety.textContent = 'Send failed: ' + error.message;
  }
}

async function runCorrespondenceActionClick(correspondenceAction, event){
  if(!correspondenceAction) return false;
  if(event){
    event.preventDefault();
    event.stopPropagation();
    if(typeof event.stopImmediatePropagation === 'function') event.stopImmediatePropagation();
  }
  const correspondenceActionId = correspondenceAction.dataset.correspondenceAction;
  const drawerUtilityAction = ['show_rules', 'search_inbox', 'save_forward_rule', 'save_safe_contact', 'suggest_rules', 'create_rule', 'show_writing_rules', 'save_draft_rules', 'save_composed_rule'].includes(correspondenceActionId);
  if(drawerUtilityAction){
    await handleCorrespondenceAction(correspondenceActionId);
    return true;
  }
  const inspectOnlyAction = ['cowork_correspondence', 'generate', 'forward', 'resolve_thread', 'safe_contact', 'not_executive_contact', 'link_relationship', 'create_relationship', 'link_project', 'create_project', 'show_rules', 'search_inbox', 'save_forward_rule', 'save_safe_contact', 'suggest_rules', 'create_rule', 'show_writing_rules', 'save_draft_rules', 'save_composed_rule'].includes(correspondenceActionId);
  const preflight = await ensureHearthClickPacket({node:correspondenceAction, packetName:'email_packet', action:correspondenceActionId, allowBlockedForInspection:inspectOnlyAction, source:{email:activeCorrespondenceItem || null, sourceId:activeCorrespondenceItem?.id || '', sourceType:'executive_inbox_item', sourceLabel:activeCorrespondenceItem?.title || 'Executive Inbox action', sourceItem:activeCorrespondenceItem || null}});
  if(!preflight.ok) return true;
  await handleCorrespondenceAction(correspondenceActionId);
  return true;
}

function commitmentLabel(value = ''){
  return String(value || '').replace(/_/g, ' ').replace(/\b\w/g, (char) => char.toUpperCase());
}

function commitmentDueLabel(value = ''){
  if(!value) return 'No due date';
  const date = new Date(value);
  if(isNaN(date.getTime())) return value;
  return date.toLocaleDateString(undefined, {month:'short', day:'numeric'});
}

function commitmentItemsForFilter(){
  return currentCommitmentItems.filter((item) => {
    if(activeCommitmentFilter === 'all') return !['complete','dismissed'].includes(item.status);
    if(activeCommitmentFilter === 'complete') return item.status === 'complete';
    if(activeCommitmentFilter === 'drafted') return item.status === 'drafted' || item.draft_id || item.task_id;
    if(activeCommitmentFilter === 'overdue') return item.status === 'overdue';
    if(activeCommitmentFilter === 'needs_resolution') return item.status === 'needs_resolution' || item.owner_type === 'unknown';
    return item.owner_type === activeCommitmentFilter;
  });
}

function updateCommitmentSummary(summary = {}){
  document.querySelectorAll('[data-commitment-summary]').forEach((node) => {
    node.textContent = summary[node.dataset.commitmentSummary] ?? 0;
  });
}

function commitmentSummaryFromItems(items = currentCommitmentItems){
  return items.reduce((summary, item) => {
    if(!item || ['complete','dismissed'].includes(item.status)) return summary;
    if(item.owner_type === 'user') summary.you_owe += 1;
    if(item.owner_type === 'contact') summary.others_owe_you += 1;
    if(item.status === 'overdue') summary.overdue += 1;
    if(item.status === 'drafted' || item.draft_id || item.task_id) summary.ready_for_approval += 1;
    return summary;
  }, {you_owe:0, others_owe_you:0, overdue:0, ready_for_approval:0});
}

function setCommitmentField(field, value){
  const node = document.querySelector('[data-commitment-field="' + field + '"]');
  if(node) node.textContent = value || '';
}

function commitmentSuggestedActions(item = activeCommitmentItem){
  if(!item) return [];
  const actions = ['cowork_commitment'];
  const explicit = Array.isArray(item.suggested_actions) ? item.suggested_actions : Array.isArray(item.suggestedActions) ? item.suggestedActions : [];
  const push = (action) => {
    if(action && !actions.includes(action)) actions.push(action);
  };
  explicit.forEach(push);
  if(item.suggested_action_type) push(item.suggested_action_type);
  if(item.owner_type === 'user'){
    push('draft_email');
    push('create_task');
  }
  if(item.owner_type === 'contact'){
    push('draft_email');
  }
  if(item.status === 'needs_resolution' || item.owner_type === 'unknown') push('resolve_contact');
  if(item.task_id || item.due_at || item.suggested_action_type === 'schedule') push('schedule');
  if(item.status === 'drafted' || item.task_id || item.draft_id) push('show_source');
  push('show_source');
  if(item.status === 'ready_for_completion' || item.can_complete === true || item.canComplete === true) push('complete');
  if(item.can_delegate === true || item.canDelegate === true) push('delegate');
  if(item.dismissable === true || item.can_dismiss === true || item.canDismiss === true) push('dismiss');
  return actions.filter((action) => [
    'cowork_commitment',
    'draft_email',
    'create_task',
    'schedule',
    'complete',
    'delegate',
    'dismiss',
    'show_source',
    'resolve_contact'
  ].includes(action));
}

function commitmentSource(item = activeCommitmentItem, action = ''){
  const selected = item || activeCommitmentItem || null;
  return {
    commitment: selected,
    commitmentId: selected?.id || '',
    sourceId: selected?.id || '',
    sourceType: selected?.source_type ? 'commitment_' + selected.source_type : 'commitment',
    sourceLabel: selected?.title || 'Commitment',
    sourceItem: selected,
    ownerType: selected?.owner_type || '',
    ownerName: selected?.owner_name || '',
    counterpartyName: selected?.counterparty_name || '',
    relationshipId: selected?.relationship_id || selected?.relationshipId || selected?.contact_id || selected?.contactId || '',
    projectId: selected?.project_id || selected?.projectId || '',
    emailThreadId: selected?.thread_id || selected?.threadId || selected?.conversation_id || selected?.conversationId || '',
    transcriptId: selected?.transcript_id || selected?.transcriptId || '',
    calendarEventId: selected?.calendar_event_id || selected?.calendarEventId || '',
    taskId: selected?.task_id || selected?.taskId || '',
    draftId: selected?.draft_id || selected?.draftId || '',
    sourceTitle: selected?.source_title || '',
    sourceQuote: selected?.evidence_quote || selected?.evidence_summary || '',
    suggestedActions: commitmentSuggestedActions(selected),
    requestedAction: action
  };
}

function commitmentActionNeedsLiveConfirmation(action = ''){
  return ['draft_email','create_task','schedule','complete','delegate','dismiss'].includes(action);
}

function renderCommitmentList(){
  if(!commitmentList) return;
  commitmentList.innerHTML = '';
  const rows = commitmentItemsForFilter();
  if(!rows.length){
    const empty = document.createElement('article');
    empty.className = 'empty';
    empty.innerHTML = '<span>No active commitments yet</span><p>VAL will surface promises, next steps, and follow-through here as transcripts, emails, meetings, and conversations are processed.</p>';
    commitmentList.appendChild(empty);
    return;
  }
  rows.forEach((item) => {
    const button = document.createElement('button');
    button.type = 'button';
    button.dataset.commitmentItem = item.id;
    const isActive = activeCommitmentItem?.id === item.id;
    button.classList.toggle('active', isActive);
    button.setAttribute('aria-pressed', String(isActive));
    const meta = [commitmentLabel(item.owner_type), item.source_type, item.status, 'Risk: ' + commitmentLabel(item.risk_level)].filter(Boolean).join(' · ');
    button.innerHTML = '<span>' + escapeHtml(meta) + '</span><strong>' + escapeHtml(item.title) + '</strong><p>' + escapeHtml(item.evidence_quote || item.description || '') + '</p><small>' + escapeHtml((item.owner_name || 'Unknown') + ' · ' + commitmentDueLabel(item.due_at)) + '</small>';
    commitmentList.appendChild(button);
  });
}

function renderCommitmentBrief(item = activeCommitmentItem){
  activeCommitmentItem = item || currentCommitmentItems[0] || null;
  renderCommitmentList();
  const selected = activeCommitmentItem;
  setCommitmentField('status', selected ? commitmentLabel(selected.status) : 'Open');
  setCommitmentField('title', selected?.title || 'Select a commitment');
  setCommitmentField('description', selected?.description || 'Promises, next steps, and follow-through will appear here with evidence and ownership.');
  setCommitmentField('owner', selected ? [selected.owner_name, commitmentLabel(selected.owner_type)].filter(Boolean).join(' · ') : 'Unknown');
  setCommitmentField('counterparty', selected?.counterparty_name || 'Unknown');
  setCommitmentField('due', selected ? commitmentDueLabel(selected.due_at) : 'No due date');
  setCommitmentField('source', selected ? [commitmentLabel(selected.source_type), selected.source_title || selected.source_id].filter(Boolean).join(' · ') : 'No source selected.');
  setCommitmentField('risk', selected ? commitmentLabel(selected.risk_level) + ' · ' + commitmentLabel(selected.priority) : 'Medium');
  setCommitmentField('next', selected?.next_action || 'Review commitment.');
  if(commitmentEvidence){
    commitmentEvidence.innerHTML = '<span>Evidence</span><p>' + escapeHtml(selected?.evidence_quote || 'Source quote will appear here.') + '</p>';
  }
  if(commitmentStatus) commitmentStatus.textContent = selected ? 'Selected commitment is evidence-backed. Drafts and tasks stay local until you act; sends still require approval.' : 'Commitments are accountability records. Drafts and tasks require visible user action; sends still require approval.';
  document.querySelectorAll('[data-commitment-action]').forEach((button) => {
    const allowed = commitmentSuggestedActions(selected).includes(button.dataset.commitmentAction);
    button.hidden = !allowed;
    button.disabled = !selected || !allowed;
    button.setAttribute('aria-hidden', String(!allowed));
  });
  scrollCommitmentActionsIntoView();
}

function scrollCommitmentActionsIntoView(){
  if(!drawerTray || !drawerTray.classList.contains('commitment-open')) return;
  window.requestAnimationFrame(() => {
    const action = document.querySelector('#commitment-detail [data-commitment-action]:not([hidden])');
    if(!action) return;
    const trayRect = drawerTray.getBoundingClientRect();
    const actionRect = action.getBoundingClientRect();
    const safeBottom = Math.min(window.innerHeight - 18, trayRect.bottom - 18);
    if(actionRect.bottom <= safeBottom && actionRect.top >= trayRect.top + 18) return;
    drawerTray.scrollTop = Math.max(0, drawerTray.scrollTop + actionRect.bottom - safeBottom);
  });
}

async function hydrateCommitmentDrawer(){
  currentCommitmentItems = localCommitmentItems.slice();
  activeCommitmentItem = currentCommitmentItems[0] || null;
  updateCommitmentSummary(commitmentSummaryFromItems(currentCommitmentItems));
  renderCommitmentBrief(activeCommitmentItem);
  if(!canUseApi) return;
  try{
    const result = await getJson('/api/val/commitments?limit=120');
    if(Array.isArray(result.commitments) && result.commitments.length){
      currentCommitmentItems = result.commitments;
      activeCommitmentItem = currentCommitmentItems[0] || null;
      updateCommitmentSummary(result.summary || {});
      renderCommitmentBrief(activeCommitmentItem);
    }else{
      updateCommitmentSummary(commitmentSummaryFromItems(currentCommitmentItems));
    }
  }catch(error){
    if(commitmentStatus) commitmentStatus.textContent = 'Commitments API unavailable; showing local preview only.';
  }
}

async function handleCommitmentAction(action){
  const item = activeCommitmentItem;
  if(!item) return;
  if(action === 'cowork_commitment'){
    if(commitmentStatus) commitmentStatus.textContent = 'Commitment follow-through is now handled from its source in Executive Inbox, Project Managers, Transcripts, or Leverage. No generic commitment Co-Work opened.';
    return;
  }
  if(String(item.id || '').startsWith('local-') && commitmentActionNeedsLiveConfirmation(action)){
    if(commitmentStatus){
      commitmentStatus.textContent = 'Local preview only: VAL can prepare this action for review, but no draft, task, schedule change, status update, delegation, dismissal, send, CRM update, or calendar change happened.';
    }
    return;
  }
  if(!canUseApi){
    if(commitmentStatus) commitmentStatus.textContent = 'The local VAL server is needed for commitment actions. Nothing changed.';
    return;
  }
  try{
    if(action === 'draft_email'){
      if(commitmentStatus) commitmentStatus.textContent = 'Drafting follow-up from commitment evidence...';
      const result = await postJson('/api/val/commitments/' + encodeURIComponent(item.id) + '/draft-email', {});
      activeCommitmentItem = result.commitment || item;
      currentCommitmentItems = currentCommitmentItems.map((row) => row.id === item.id ? activeCommitmentItem : row);
      renderCommitmentBrief(activeCommitmentItem);
      if(commitmentStatus) commitmentStatus.textContent = 'Draft created for review. Nothing was sent.';
      return;
    }
    if(action === 'create_task'){
      const result = await postJson('/api/val/commitments/' + encodeURIComponent(item.id) + '/create-task', {});
      activeCommitmentItem = result.commitment || item;
      currentCommitmentItems = currentCommitmentItems.map((row) => row.id === item.id ? activeCommitmentItem : row);
      renderCommitmentBrief(activeCommitmentItem);
      if(commitmentStatus) commitmentStatus.textContent = 'Task created from commitment evidence and linked locally.';
      return;
    }
    if(action === 'complete' || action === 'dismiss'){
      const status = action === 'complete' ? 'complete' : 'dismissed';
      const result = await postJson('/api/val/commitments/' + encodeURIComponent(item.id) + '/status', {status, reason: action === 'dismiss' ? 'Dismissed from Commitments drawer.' : ''});
      activeCommitmentItem = result.commitment || {...item,status};
      currentCommitmentItems = currentCommitmentItems.map((row) => row.id === item.id ? activeCommitmentItem : row);
      renderCommitmentBrief(activeCommitmentItem);
      if(commitmentStatus) commitmentStatus.textContent = action === 'complete' ? 'Commitment marked complete.' : 'Commitment dismissed with local audit context.';
      return;
    }
    if(action === 'delegate'){
      const result = await postJson('/api/val/commitments/' + encodeURIComponent(item.id) + '/status', {status:'delegated'});
      activeCommitmentItem = result.commitment || {...item,status:'delegated'};
      currentCommitmentItems = currentCommitmentItems.map((row) => row.id === item.id ? activeCommitmentItem : row);
      renderCommitmentBrief(activeCommitmentItem);
      if(commitmentStatus) commitmentStatus.textContent = 'Commitment marked delegated. Full owner reassignment can attach a resolved contact next.';
      return;
    }
    if(action === 'schedule'){
      setWorkspaceContent({
        lens:'Commitments',
        title:'Schedule commitment follow-through',
        meaning:item.title,
        understanding:[item.evidence_quote, item.owner_name, item.due_at ? commitmentDueLabel(item.due_at) : 'No due date yet'].filter(Boolean),
        recommendation:'Use the existing calendar/task scheduling flow once this commitment has a confirmed task or date.',
        actions:[{label:'Back to Leverage', workflow:'cancel:home'}],
        label:'Commitment scheduling workspace'
      });
      openWorkspaceShell('Commitment scheduling workspace', {returnTarget:'home'});
      renderHearthPacketReceiptStrip(lastHearthPacketReceipt);
      return;
    }
    if(action === 'show_source'){
      if(commitmentStatus) commitmentStatus.textContent = 'Source: ' + [commitmentLabel(item.source_type), item.source_title || item.source_id, item.evidence_quote].filter(Boolean).join(' · ');
      return;
    }
    if(action === 'resolve_contact'){
      if(commitmentStatus) commitmentStatus.textContent = 'Contact resolution needed. VAL will not guess or create duplicate relationship records.';
    }
  }catch(error){
    if(commitmentStatus) commitmentStatus.textContent = 'Commitment action did not complete: ' + error.message;
  }
}

function projectContextActions(actions = []){
  const name = activeProjectProfile?.name || 'project';
  return actions.concat([
    {label:'Back to ' + name, workflow:'cancel:project'},
    {label:'All projects', workflow:'projectAllProjects'}
  ]);
}

