function valGhlVoiceStage(){
  const widget = document.querySelector('chat-widget[data-val-ghl-voice-widget],chat-widget');
  return widget?.shadowRoot?.querySelector?.('.voice-orb-stage,[aria-label*="Tap to talk"],[role="button"]') || null;
}

function valGhlVoiceStageIsActive(stage = valGhlVoiceStage()){
  const text = String(stage?.innerText || stage?.textContent || '').trim();
  return /\b(speaking|listening|end call|connected|connecting)\b/i.test(text);
}

function activateValGhlVoiceStage(){
  const stage = valGhlVoiceStage();
  if(!stage) return false;
  if(valGhlVoiceStageIsActive(stage)) return true;
  try{
    stage.dispatchEvent(new PointerEvent('pointerdown', {bubbles:true,composed:true,cancelable:true,pointerId:1,pointerType:'mouse'}));
    stage.dispatchEvent(new MouseEvent('mousedown', {bubbles:true,composed:true,cancelable:true}));
    stage.dispatchEvent(new PointerEvent('pointerup', {bubbles:true,composed:true,cancelable:true,pointerId:1,pointerType:'mouse'}));
    stage.dispatchEvent(new MouseEvent('mouseup', {bubbles:true,composed:true,cancelable:true}));
    stage.click();
    return true;
  }catch(error){
    try{ stage.click(); return true; }catch(innerError){}
  }
  return false;
}

function startValGhlVoiceWidgetObserver(){
  if(valCoworkVoiceState.ghlWidgetObserver || !window.MutationObserver) return;
  valCoworkVoiceState.ghlWidgetObserver = new MutationObserver(markValGhlVoiceWidgetNodes);
  valCoworkVoiceState.ghlWidgetObserver.observe(document.body, {childList:true,subtree:true});
  markValGhlVoiceWidgetNodes();
}

function stopValGhlVoiceWidgetObserver(){
  if(valCoworkVoiceState.ghlWidgetObserver){
    valCoworkVoiceState.ghlWidgetObserver.disconnect();
    valCoworkVoiceState.ghlWidgetObserver = null;
  }
  if(valCoworkVoiceState.ghlWidgetMarkTimer){
    window.clearInterval(valCoworkVoiceState.ghlWidgetMarkTimer);
    valCoworkVoiceState.ghlWidgetMarkTimer = null;
  }
}

function waitForValGhlVoiceWidget(timeoutMs = 8000){
  return new Promise((resolve, reject) => {
    const started = Date.now();
    const tick = () => {
      markValGhlVoiceWidgetNodes();
      const api = valGhlVoiceWidgetApi();
      if(api && typeof api.openWidget === 'function') return resolve(api);
      if(Date.now() - started >= timeoutMs) return reject(new Error('VAL voice could not connect to the GHL voice agent.'));
      window.setTimeout(tick, 150);
    };
    tick();
  });
}

function ensureValGhlVoiceWidget(){
  if(valCoworkVoiceState.ghlScriptPromise) return valCoworkVoiceState.ghlScriptPromise;
  startValGhlVoiceWidgetObserver();
  valCoworkVoiceState.ghlScriptPromise = new Promise((resolve, reject) => {
    const existing = document.querySelector('script[data-val-ghl-voice-loader]');
    const complete = () => waitForValGhlVoiceWidget().then(resolve).catch(reject);
    if(existing){
      complete();
      return;
    }
    const script = document.createElement('script');
    script.src = VAL_GHL_WIDGET_LOADER_SRC;
    script.async = true;
    script.defer = true;
    script.dataset.valGhlVoiceLoader = 'true';
    script.setAttribute('data-resources-url', VAL_GHL_WIDGET_RESOURCE_SRC);
    script.setAttribute('data-widget-id', VAL_GHL_VOICE_WIDGET_ID);
    script.addEventListener('load', complete, {once:true});
    script.addEventListener('error', () => reject(new Error('VAL voice could not load the GHL voice agent.')), {once:true});
    document.body.appendChild(script);
  }).catch((error) => {
    valCoworkVoiceState.ghlScriptPromise = null;
    throw error;
  });
  return valCoworkVoiceState.ghlScriptPromise;
}

function preloadValGhlVoiceWidget(){
  startValGhlVoiceWidgetObserver();
  void ensureValGhlVoiceWidget().then(markValGhlVoiceWidgetNodes).catch((error) => {
    console.warn('VAL GHL voice preload failed:', error.message);
  });
}

function activatePreloadedValGhlVoiceWidget(){
  const api = valGhlVoiceWidgetApi();
  if(!api || typeof api.openWidget !== 'function') return false;
  document.body.classList.add('val-ghl-voice-active');
  setValGhlVoiceWidgetPlacement('voice');
  startValGhlVoiceWidgetObserver();
  markValGhlVoiceWidgetNodes();
  api.openWidget();
  return activateValGhlVoiceStage();
}

async function openValGhlVoiceWidget(){
  document.body.classList.add('val-ghl-voice-active');
  setValGhlVoiceWidgetPlacement('voice');
  startValGhlVoiceWidgetObserver();
  setValCoworkVoiceMode('thinking', 'Opening VAL voice.');
  const api = await ensureValGhlVoiceWidget();
  markValGhlVoiceWidgetNodes();
  if(typeof api.openWidget === 'function') api.openWidget();
  window.setTimeout(() => activateValGhlVoiceStage(), 120);
  window.setTimeout(() => {
    const stage = valGhlVoiceStage();
    if(stage && !valGhlVoiceStageIsActive(stage)) activateValGhlVoiceStage();
  }, 900);
  let marks = 0;
  if(valCoworkVoiceState.ghlWidgetMarkTimer) window.clearInterval(valCoworkVoiceState.ghlWidgetMarkTimer);
  valCoworkVoiceState.ghlWidgetMarkTimer = window.setInterval(() => {
    markValGhlVoiceWidgetNodes();
    marks += 1;
    if(marks > 30 && valCoworkVoiceState.ghlWidgetMarkTimer){
      window.clearInterval(valCoworkVoiceState.ghlWidgetMarkTimer);
      valCoworkVoiceState.ghlWidgetMarkTimer = null;
    }
  }, 250);
  setValCoworkVoiceMode('listening', 'VAL voice is open.');
}

function closeValGhlVoiceWidget(){
  document.body.classList.remove('val-ghl-voice-active');
  setValGhlVoiceWidgetPlacement('hidden');
  try{
    const api = valGhlVoiceWidgetApi();
    if(api && typeof api.closeWidget === 'function') api.closeWidget();
  }catch(error){}
  stopValGhlVoiceWidgetObserver();
}

function primeValCoworkVoiceRecognition(){
  const SpeechRecognition = valCoworkSpeechRecognitionCtor();
  if(!SpeechRecognition || !valCoworkVoiceState.active || valCoworkVoiceState.priming) return false;
  valCoworkVoiceState.priming = true;
  try{
    const recognition = new SpeechRecognition();
    valCoworkVoiceState.recognition = recognition;
    recognition.lang = 'en-US';
    recognition.interimResults = false;
    recognition.continuous = false;
    recognition.maxAlternatives = 1;
    recognition.onresult = () => {};
    recognition.onerror = () => {
      valCoworkVoiceState.priming = false;
    };
    recognition.onend = () => {
      if(valCoworkVoiceState.recognition === recognition) valCoworkVoiceState.recognition = null;
      valCoworkVoiceState.priming = false;
    };
    recognition.onstart = () => {
      window.setTimeout(() => {
        try{ recognition.stop(); }catch(error){}
      }, 90);
    };
    recognition.start();
    return true;
  }catch(error){
    valCoworkVoiceState.priming = false;
    return false;
  }
}

function valCoworkSpeechText(text = ''){
  return String(text || '')
    .replace(/\*\*(.*?)\*\*/g, '$1')
    .replace(/\[(.*?)\]\(.*?\)/g, '$1')
    .replace(/<[^>]*>/g, '')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 2000);
}

function fetchValCoworkDeepgramAudio(cleanText = ''){
  const clean = valCoworkSpeechText(cleanText);
  if(!clean) return Promise.reject(new Error('No text supplied for voice playback.'));
  if(valCoworkVoiceState.audioCache[clean]) return valCoworkVoiceState.audioCache[clean];
  let controller = null;
  let timer = null;
  if(window.AbortController){
    controller = new AbortController();
    timer = window.setTimeout(() => {
      try{ controller.abort(); }catch(error){}
    }, 6500);
  }
  valCoworkVoiceState.audioCache[clean] = fetch('/api/val/tts', {
    method:'POST',
    headers:{'Content-Type':'application/json'},
    body:JSON.stringify({text:clean}),
    signal:controller ? controller.signal : undefined
  }).then((response) => {
    if(!response.ok){
      return response.json().catch(() => ({})).then((data) => {
        throw new Error(data.detail || data.error || 'Deepgram TTS failed: ' + response.status);
      });
    }
    const contentType = response.headers.get('content-type') || '';
    if(!contentType.includes('audio/')) throw new Error('Deepgram TTS did not return audio.');
    return response.blob();
  }).catch((error) => {
    delete valCoworkVoiceState.audioCache[clean];
    throw error;
  }).finally(() => {
    if(timer) window.clearTimeout(timer);
  });
  return valCoworkVoiceState.audioCache[clean];
}

function stopValCoworkVoiceMode(){
  clearValCoworkVoiceRestart();
  if(valCoworkVoiceState.ghlBridge) closeValGhlVoiceWidget();
  valCoworkVoiceState.active = false;
  valCoworkVoiceState.pending = false;
  valCoworkVoiceState.priming = false;
  valCoworkVoiceState.ghlBridge = false;
  valCoworkVoiceState.playbackToken += 1;
  if(valCoworkVoiceState.audio){
    try{ valCoworkVoiceState.audio.pause(); }catch(error){}
    valCoworkVoiceState.audio = null;
  }
  try{ valCoworkVoiceState.recognition?.stop?.(); }catch(error){}
  valCoworkVoiceState.recognition = null;
  try{ window.speechSynthesis?.cancel?.(); }catch(error){}
  workspaceInputPanel.classList.remove('val-cowork-voice-active');
  deskWorkspace?.classList.remove('val-cowork-voice-active');
  valCoworkVoiceShell()?.remove();
}

function closeValCoworkVoiceSession(){
  closeWorkspace();
}

function speakValCoworkMessage(text = '', options = {}){
  if(!valCoworkVoiceState.active) return;
  const spoken = valCoworkSpeechText(text);
  if(!spoken) return;
  const token = ++valCoworkVoiceState.playbackToken;
  let finished = false;
  let fellBack = false;
  setValCoworkVoiceMode('speaking', options.detail || 'VAL is answering out loud.');
  try{ window.speechSynthesis.cancel(); }catch(error){}
  if(valCoworkVoiceState.audio){
    try{ valCoworkVoiceState.audio.pause(); }catch(error){}
    valCoworkVoiceState.audio = null;
  }
  const finish = () => {
    if(finished || token !== valCoworkVoiceState.playbackToken) return;
    finished = true;
    if(typeof options.onEnd === 'function') options.onEnd();
    else if(valCoworkVoiceState.active) startValCoworkListening();
  };
  const fallbackSpeak = () => {
    if(fellBack || finished || token !== valCoworkVoiceState.playbackToken) return;
    fellBack = true;
    setValCoworkVoiceMode('idle', 'Deepgram voice is not available in this local preview. VAL will not use a robot fallback.');
    finish();
  };
  fetchValCoworkDeepgramAudio(spoken).then((blob) => {
    if(fellBack || finished || token !== valCoworkVoiceState.playbackToken) return;
    const url = URL.createObjectURL(blob);
    const audio = new Audio(url);
    valCoworkVoiceState.audio = audio;
    audio.onended = () => {
      URL.revokeObjectURL(url);
      if(valCoworkVoiceState.audio === audio) valCoworkVoiceState.audio = null;
      finish();
    };
    audio.onerror = () => {
      URL.revokeObjectURL(url);
      if(valCoworkVoiceState.audio === audio) valCoworkVoiceState.audio = null;
      fallbackSpeak();
    };
    audio.play().catch(() => {
      URL.revokeObjectURL(url);
      if(valCoworkVoiceState.audio === audio) valCoworkVoiceState.audio = null;
      fallbackSpeak();
    });
  }).catch(() => fallbackSpeak());
}

async function sendValCoworkVoiceTranscript(transcript = ''){
  const spoken = projectCleanText(transcript);
  if(!spoken || valCoworkVoiceState.pending) return;
  valCoworkVoiceState.pending = true;
  valCoworkVoiceState.lastTranscript = spoken;
  setValCoworkVoiceMode('thinking', 'VAL heard you. Holding the thread and preparing a response.');
  try{
    const entry = activeCoworkEntry;
    const scopedEntryReady = Boolean(entry?.sessionId && entry.status !== 'opening' && entry.status !== 'applied');
    if(scopedEntryReady && await submitActiveCoworkEntry(spoken)) return;
    await runCowork('think', spoken);
  }catch(error){
    console.warn('VAL voice turn failed:', error);
    if(valCoworkVoiceState.active){
      speakValCoworkMessage(error?.message || 'I heard you, but that voice turn did not complete. Ask me again in one shorter sentence.', {silentVoice:true});
    }else{
      appendHomeCoworkMessage('val', 'Voice needs attention: ' + (error?.message || 'The voice turn did not complete.') + '\n\nNo external action was taken.');
    }
  }finally{
    valCoworkVoiceState.pending = false;
    if(valCoworkVoiceState.active && valCoworkVoiceState.mode === 'thinking'){
      startValCoworkListening();
    }
  }
}

function startValCoworkListening(){
  if(!valCoworkVoiceState.active || valCoworkVoiceState.pending) return;
  const SpeechRecognition = valCoworkSpeechRecognitionCtor();
  if(!SpeechRecognition){
    setValCoworkVoiceMode('idle', 'Voice capture is not available in this browser. Typed co-work is still available.');
    return;
  }
  clearValCoworkVoiceRestart();
  try{ valCoworkVoiceState.recognition?.stop?.(); }catch(error){}
  const recognition = new SpeechRecognition();
  valCoworkVoiceState.recognition = recognition;
  const attempt = ++valCoworkVoiceState.listenAttempt;
  recognition.lang = 'en-US';
  recognition.interimResults = false;
  recognition.continuous = false;
  recognition.maxAlternatives = 1;
  setValCoworkVoiceMode('listening', 'Speak naturally. Nothing is being typed into the input.');
  recognition.onresult = (event) => {
    const transcript = Array.from(event.results || [])
      .map((result) => result[0]?.transcript || '')
      .join(' ')
      .trim();
    void sendValCoworkVoiceTranscript(transcript);
  };
  recognition.onerror = (event) => {
    if(!valCoworkVoiceState.active) return;
    const errorName = String(event?.error || '');
    if(errorName === 'not-allowed' || errorName === 'service-not-allowed' || errorName === 'audio-capture'){
      setValCoworkVoiceMode('idle', 'Microphone permission is needed for VAL voice mode.');
      return;
    }
    setValCoworkVoiceMode('listening', 'VAL is still listening.');
  };
  recognition.onend = () => {
    if(!valCoworkVoiceState.active || valCoworkVoiceState.pending || valCoworkVoiceState.mode === 'speaking') return;
    valCoworkVoiceState.restartTimer = window.setTimeout(() => {
      if(valCoworkVoiceState.active && !valCoworkVoiceState.pending && valCoworkVoiceState.listenAttempt === attempt) startValCoworkListening();
    }, 600);
  };
  try{
    recognition.start();
  }catch(error){
    setValCoworkVoiceMode('idle', 'Voice is already starting. Give VAL one breath, then speak.');
  }
}

function startValCoworkVoiceMode(){
  const form = workspaceInputPanel.querySelector('[data-home-cowork-form]') || scraperPreviewList?.querySelector?.('[data-home-cowork-form]');
  if(!form){
    startWorkspaceVoiceDictation();
    return;
  }
  if(valCoworkVoiceState.active){
    ensureValCoworkVoiceSurface();
    if(valCoworkVoiceState.ghlBridge) void openValGhlVoiceWidget();
    else startValCoworkListening();
    return;
  }
  valCoworkVoiceState.active = true;
  valCoworkVoiceState.pending = false;
  valCoworkVoiceState.ghlBridge = true;
  ensureValCoworkVoiceSurface();
  activatePreloadedValGhlVoiceWidget();
  void openValGhlVoiceWidget().catch((error) => {
    console.warn('VAL GHL voice bridge failed:', error);
    setValCoworkVoiceMode('idle', error?.message || 'VAL voice could not connect. Try again in a moment.');
  });
}

function startWorkspaceVoiceDictation(){
  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if(!SpeechRecognition){
    setWorkspaceToolStatus('Voice input is not available in this browser yet. Type here, or use upload/generate image as context.');
    return;
  }
  const recognition = new SpeechRecognition();
  recognition.lang = 'en-US';
  recognition.interimResults = false;
  recognition.maxAlternatives = 1;
  setWorkspaceToolStatus('Listening. Speak the context you want VAL to hold here.');
  recognition.onresult = (event) => {
    const transcript = Array.from(event.results || [])
      .map((result) => result[0]?.transcript || '')
      .join(' ')
      .trim();
    appendToWorkspaceInput(transcript);
    setWorkspaceToolStatus(transcript ? 'Voice note added to this workspace. Nothing was sent or saved externally.' : 'Voice stopped without a transcript.');
  };
  recognition.onerror = () => {
    setWorkspaceToolStatus('Voice input could not start. The typed Co-Work and upload controls are still available.');
  };
  recognition.onend = () => {
    const current = workspaceInputPanel.querySelector('[data-workspace-tool-status]')?.textContent || '';
    if(current === 'Listening. Speak the context you want VAL to hold here.'){
      setWorkspaceToolStatus('Voice listening ended. Add more context or ask VAL to help shape it.');
    }
  };
  recognition.start();
}

function startWorkspaceVoiceInput(){
  startValCoworkVoiceMode();
}

function activeWorkspaceFileInput(tool = null){
  return tool?.closest?.('[data-home-cowork-form]')?.querySelector?.('[data-workspace-file-input]')
    || workspaceInputPanel.querySelector('[data-workspace-file-input]')
    || scraperPreviewList?.querySelector?.('[data-workspace-file-input]');
}

function handleHomeCoworkFormSubmit(event){
  if(!event.target.matches('[data-home-cowork-form]')) return false;
  event.preventDefault();
  const observerLane = Boolean(deskWorkspace?.classList.contains('observer-cowork-active'));
  const textarea = event.target.querySelector('[data-workspace-input="cowork"]');
  const message = observerLane ? projectCleanText(textarea?.value || '') : '';
  if(observerLane && textarea) textarea.value = '';
  submitActiveCoworkEntry(message).then((handled) => {
    if(!handled) runCowork('think', message);
  });
  return true;
}

function handleHomeCoworkInput(event){
  if(!event.target.matches('[data-home-cowork-form] [data-workspace-input="cowork"]')) return false;
  orientHomeCoworkFromInput();
  return true;
}

function handleHomeCoworkEnterToSend(event){
  if(event.key !== 'Enter' || event.shiftKey || event.metaKey || event.ctrlKey || event.altKey) return false;
  const field = event.target.closest?.('[data-home-cowork-form] [data-workspace-input="cowork"]');
  if(!field) return false;
  event.preventDefault();
  const form = field.closest('[data-home-cowork-form]');
  if(form?.requestSubmit) form.requestSubmit();
  else if(form) handleHomeCoworkFormSubmit({target:form,preventDefault(){}});
  return true;
}

async function handleWorkspaceFileChange(event){
  const input = event.target.closest('[data-workspace-file-input]');
  if(!input) return false;
  await appendWorkspaceFiles(input.files);
  input.value = '';
  return true;
}

function handleWorkspaceToolClick(event){
  const tool = event.target.closest('[data-workspace-tool]');
  if(!tool) return false;
  event.preventDefault();
  event.stopPropagation();
  if(tool.dataset.workspaceTool === 'voice'){
    startWorkspaceVoiceInput();
    return true;
  }
  if(tool.dataset.workspaceTool === 'upload'){
    activeWorkspaceFileInput(tool)?.click();
    return true;
  }
  if(tool.dataset.workspaceTool === 'image'){
    appendWorkspaceImageRequest();
    return true;
  }
  return true;
}

async function appendWorkspaceFiles(files = []){
  const selected = Array.from(files || []);
  if(!selected.length) return;
  setWorkspaceToolStatus('Reading ' + selected.length + ' uploaded file' + (selected.length === 1 ? '' : 's') + ' for this workspace only.');
  const snippets = await Promise.all(selected.slice(0, 6).map(async (file) => {
    const receipt = 'Uploaded file: ' + file.name + ' (' + Math.ceil((file.size || 0) / 1024) + ' KB)';
    if(!/^text\/|json|csv|markdown|xml|html|javascript/.test(file.type || '') && !/\.(txt|md|json|csv|tsv|html|css|js)$/i.test(file.name || '')){
      return receipt + '\nContext: file attached for review. VAL should use the document library/upload pipeline before treating this as durable evidence.';
    }
    try{
      const text = await file.text();
      return receipt + '\nExcerpt: ' + text.slice(0, 1200);
    }catch(error){
      return receipt + '\nContext: file selected, but this browser could not read a local excerpt.';
    }
  }));
  appendToWorkspaceInput(snippets.join('\n\n'));
  setWorkspaceToolStatus('Upload context added to this workspace. Nothing was sent, posted, or written to memory.');
}

async function appendValWitnessingFiles(category, files = []){
  const selected = Array.from(files || []);
  if(!selected.length) return;
  const card = valWitnessingCard(category);
  const mode = 'val-witnessing-' + card.category;
  const statusTarget = workspaceInputPanel.querySelector('.val-conversation-helper');
  if(statusTarget) statusTarget.textContent = 'Uploading ' + selected.length + ' file' + (selected.length === 1 ? '' : 's') + ' into VAL document context...';
  const receipts = [];
  for(const file of selected.slice(0, 8)){
    let receipt = 'Uploaded file: ' + file.name + ' (' + Math.ceil((file.size || 0) / 1024) + ' KB)';
    if(canUseApi && !mockScrapers){
      try{
        const form = new FormData();
        form.append('files', file, file.name);
        form.append('uploadedVia', 'val_witnessing_session');
        form.append('docType', 'knowledge_document');
        form.append('title', file.name);
        const response = await fetch('/api/val/files', {method:'POST', body:form});
        const data = await response.json().catch(() => ({}));
        if(!response.ok) throw new Error(data.error || data.message || 'Upload failed');
        receipt += '\nVAL file id: ' + (data.id || data.files?.[0]?.id || 'saved');
        receipt += '\nClassification needed: Document or Template.';
        receipt += '\nIf Document: which relationship or project does this belong to?';
        receipt += '\nIf Template: what is this template used for?';
      }catch(error){
        receipt += '\nUpload note: VAL could not read this file yet (' + (error.message || 'upload failed') + '). Keep the file named here and add its purpose below.';
      }
    }else{
      receipt += '\nPrototype note: file selected. In live VAL this should upload into the document library before being interpreted.';
    }
    receipts.push(receipt);
  }
  const textarea = workspaceInputPanel.querySelector('[data-workspace-input="' + mode + '"]');
  if(textarea){
    const prefix = textarea.value.trim() ? '\n\n' : '';
    textarea.value += prefix + receipts.join('\n\n');
    textarea.focus();
  }else{
    appendToWorkspaceInput(receipts.join('\n\n'));
  }
  if(statusTarget) statusTarget.textContent = 'File context added. Tell VAL whether each item is a Document or Template before continuing.';
}

async function copyValWitnessingImportPrompt(){
  try{
    await navigator.clipboard.writeText(valUniversalAiImportPrompt);
    valLiveStatus.textContent = 'Copied the one-time ChatGPT/Claude import prompt.';
  }catch(error){
    const card = valWitnessingCard('import_context');
    const mode = 'val-witnessing-' + card.category;
    const textarea = workspaceInputPanel.querySelector('[data-workspace-input="' + mode + '"]');
    if(textarea){
      textarea.value = valUniversalAiImportPrompt + '\n\n' + textarea.value;
      textarea.focus();
    }
    valLiveStatus.textContent = 'Clipboard was unavailable, so I placed the prompt in the text box.';
  }
}

