function updatePreviewApprovalSummary(){
  const rows = Array.from(leadDrawerPreviewList.querySelectorAll('.preview-lead'));
  if(!rows.length) return;
  const approved = rows.filter((row) => row.dataset.leadReview !== 'held').length;
  const held = rows.length - approved;
  const summary = leadDrawerPreviewList.querySelector('[data-preview-summary]');
  if(summary){
    const sourceMode = mockScrapers || !canUseApi ? 'Prototype/mock preview' : 'Live scraper preview';
    summary.textContent = sourceMode + ' - ' + approved + ' approved / ' + held + ' held - not imported until you click Import.';
  }
  const importAction = workspaceActions.querySelector('[data-workflow-action^="import:"]');
  if(importAction){
    importAction.textContent = approved ? 'Import ' + approved + ' approved lead' + (approved === 1 ? '' : 's') : 'No approved leads';
    importAction.disabled = approved === 0;
  }
  const drawerImportAction = leadDrawerPreviewList.querySelector('[data-lead-drawer-action="import"]');
  if(drawerImportAction){
    drawerImportAction.textContent = approved ? 'Import ' + approved + ' approved lead' + (approved === 1 ? '' : 's') : 'No approved leads';
    drawerImportAction.disabled = approved === 0;
  }
}

function activeLeadIntelligenceSource(action = '', extra = {}){
  const type = activeScraperType || extra.type || '';
  const session = type ? sessionFor(type) : {};
  const rows = leadDrawerPreviewList ? Array.from(leadDrawerPreviewList.querySelectorAll('.preview-lead')) : [];
  const approvedCount = rows.filter((row) => row.dataset.leadReview !== 'held').length;
  const heldCount = rows.length - approvedCount;
  return {
    ...extra,
    sourceId: extra.sourceId || type || action || 'lead_intelligence',
    sourceType: extra.sourceType || 'lead_intelligence_workflow',
    sourceLabel: extra.sourceLabel || (type ? documentTypeLabel(type) + ' Lead Intelligence' : 'Lead Intelligence'),
    sourceItem: extra.sourceItem || {
      id: type || 'lead_intelligence',
      title: extra.sourceLabel || (type ? documentTypeLabel(type) + ' Lead Intelligence' : 'Lead Intelligence'),
      workflowType: type,
      criteria: session?.payload || null,
      previewCount: rows.length,
      approvedCount,
      heldCount
    },
    workflowType: type,
    previewCount: rows.length,
    approvedCount,
    heldCount,
    requestedAction: action
  };
}

function getScraperCriteria(){
  return Array.from(leadDrawerCriteriaPanel.querySelectorAll('[data-criteria-label]')).reduce((values, field) => {
    values[field.dataset.criteriaLabel] = field.value;
    values[field.dataset.criteriaKey] = field.value;
    return values;
  }, {});
}

function publicSurfaceText(value){
  return String(value == null ? '' : value)
    .replace(/\bCRM\s*\/\s*CRM\b/gi, 'CRM')
    .replace(/\bCRM\s*\/\s*GHL\b/gi, 'CRM')
    .replace(/\bGHL\s*\/\s*CRM\b/gi, 'CRM')
    .replace(/\bGHL\b/g, 'CRM')
    .replace(/\bGoHighLevel\b/gi, 'CRM')
    .replace(/\bKrisp\b/gi, 'VAL')
    .replace(/\bCrisp\b/gi, 'VAL')
    .replace(/\bOutscraper\b/gi, 'VAL')
    .replace(/\bRocketReach\b/gi, 'VAL')
    .replace(/\bApollo\b/gi, 'VAL');
}

function escapeHtml(value){
  return publicSurfaceText(value).replace(/[&<>"']/g, (char) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  })[char]);
}

// Connection providers are user-chosen external services. Do not pass their
// names or workflow identifiers through the generic internal-name masker.
function escapeConnectionHtml(value){
  return String(value == null ? '' : value).replace(/[&<>"']/g, (char) => ({
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#39;'
  })[char]);
}

function leadField(lead, keys, fallback = ''){
  for(const key of keys){
    if(lead && lead[key] != null && String(lead[key]).trim()) return String(lead[key]).trim();
  }
  return fallback;
}

function normalizePreviewLead(lead, type){
  const sourceUrls = Array.isArray(lead.sourceUrls) ? lead.sourceUrls : Array.isArray(lead.sources) ? lead.sources : [];
  const contactName = leadField(lead, ['decisionMakerName','contactName','primaryContact','name'], '');
  const contactTitle = leadField(lead, ['decisionMakerTitle','contactTitle','title'], '');
  const contact = contactName ? contactName + (contactTitle ? ', ' + contactTitle : '') : lead.email || lead.phone || 'Decision maker not confirmed';
  const score = type === 'partners'
    ? (lead.partnershipFitScore != null ? 'Fit ' + Number(lead.partnershipFitScore) + '/100' : leadField(lead, ['score','leadScore','partnerFit'], 'Fit pending'))
    : (lead.leadScore != null ? 'Score ' + lead.leadScore : leadField(lead, ['score','leadScoreReason','partnerFit','confidence'], 'Review fit'));
  const evidence = leadField(lead, ['reasonForScore','leadScoreReason','evidence','nextOutreachAngle','recommendedOutreachAngle','tagReason'], sourceUrls.length ? 'Sources: ' + sourceUrls.slice(0, 2).join(', ') : 'Evidence attached in scraper result.');
  return {
    name: leadField(lead, ['organizationName','companyName','businessName','name'], 'Unnamed organization'),
    type: leadField(lead, ['partnerType','organizationType','industry','aiExactIndustry','normalizedIndustry'], type === 'partners' ? 'Strategic partner' : 'Organization'),
    location: leadField(lead, ['location','city','state','market'], 'Location pending'),
    score,
    contact,
    evidence,
    _raw: lead,
    _approved: lead._approved !== false
  };
}

function sessionFor(type){
  scraperSessions[type] = scraperSessions[type] || {};
  return scraperSessions[type];
}

const VAL_COMPLETION_SOUND_STORAGE_KEY = 'valCompletionSoundEnabled';
const VAL_COMPLETION_SOUND_MIN_WAIT_MS = 650;
const VAL_COMPLETION_SOUND_THROTTLE_MS = 1600;
let valCompletionSoundEnabled = true;
let valCompletionAudioContext = null;
let valCompletionLastUserGestureAt = 0;
let valCompletionLastPlayedAt = 0;

function readValCompletionSoundPreference(){
  try{
    return window.localStorage.getItem(VAL_COMPLETION_SOUND_STORAGE_KEY) !== 'false';
  }catch(_error){
    return true;
  }
}

function updateValCompletionSoundToggle(){
  if(!completionSoundToggle) return;
  completionSoundToggle.checked = valCompletionSoundEnabled;
  const label = valCompletionSoundEnabled ? 'Completion sound on' : 'Completion sound off';
  completionSoundToggle.setAttribute('aria-label', label + '. Play a quiet sound when VAL finishes.');
  const toggle = completionSoundToggle.closest('.completion-sound-toggle');
  if(toggle){
    toggle.dataset.tooltip = label;
    toggle.title = label;
  }
}

function primeValCompletionAudio(){
  if(!valCompletionSoundEnabled) return;
  const AudioContext = window.AudioContext || window.webkitAudioContext;
  if(!AudioContext) return;
  if(!valCompletionAudioContext) valCompletionAudioContext = new AudioContext();
  if(valCompletionAudioContext.state === 'suspended'){
    void valCompletionAudioContext.resume().catch(() => {});
  }
}

function noteValCompletionUserGesture(){
  valCompletionLastUserGestureAt = Date.now();
  primeValCompletionAudio();
}

function setValCompletionSoundEnabled(enabled){
  valCompletionSoundEnabled = !!enabled;
  try{
    window.localStorage.setItem(VAL_COMPLETION_SOUND_STORAGE_KEY, String(valCompletionSoundEnabled));
  }catch(_error){}
  updateValCompletionSoundToggle();
  if(valCompletionSoundEnabled) primeValCompletionAudio();
}

function captureValCompletionCue(){
  return valCompletionSoundEnabled && Date.now() - valCompletionLastUserGestureAt < 1500;
}

function valCompletionSoundIsBackgroundRequest(url = ''){
  return /\/api\/(?:hearth\/build-packet|val\/ready-for-you\/build|val\/review-updates\/build|val\/executive-instructions\/extract|teach-val\/onboarding\/(?:start|[^/]+\/reset)|dev\/)/.test(String(url || ''));
}

function shouldPlayValCompletionCue(url = '', options = {}){
  if(options.completionCue === false || valCompletionSoundIsBackgroundRequest(url)) return false;
  return options.completionCue === true || captureValCompletionCue();
}

function playValCompletionCue({cue = true, requestStartedAt = Date.now()} = {}){
  if(!cue || !valCompletionSoundEnabled || Date.now() - requestStartedAt < VAL_COMPLETION_SOUND_MIN_WAIT_MS) return;
  const context = valCompletionAudioContext;
  if(!context || context.state !== 'running' || Date.now() - valCompletionLastPlayedAt < VAL_COMPLETION_SOUND_THROTTLE_MS) return;
  valCompletionLastPlayedAt = Date.now();
  const now = context.currentTime;
  const gain = context.createGain();
  gain.gain.setValueAtTime(.0001, now);
  gain.gain.exponentialRampToValueAtTime(.026, now + .015);
  gain.gain.exponentialRampToValueAtTime(.0001, now + .30);
  gain.connect(context.destination);
  [523.25, 659.25].forEach((frequency, index) => {
    const tone = context.createOscillator();
    tone.type = 'sine';
    tone.frequency.setValueAtTime(frequency, now + index * .065);
    tone.connect(gain);
    tone.start(now + index * .065);
    tone.stop(now + .32);
  });
}

valCompletionSoundEnabled = readValCompletionSoundPreference();
updateValCompletionSoundToggle();
document.addEventListener('pointerdown', noteValCompletionUserGesture, true);
document.addEventListener('keydown', (event) => {
  if(event.key === 'Enter' || event.key === ' ') noteValCompletionUserGesture();
}, true);
completionSoundToggle?.addEventListener('change', (event) => {
  setValCompletionSoundEnabled(event.target.checked);
});

async function postJson(url, payload, options = {}){
  const completionCue = shouldPlayValCompletionCue(url, options);
  const requestStartedAt = Date.now();
  const controller = options.timeoutMs && window.AbortController ? new AbortController() : null;
  const timeoutId = controller ? window.setTimeout(() => controller.abort(), options.timeoutMs) : null;
  let response;
  try{
    response = await fetch(url, {
      method: options.method || 'POST',
      credentials: 'same-origin',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify(payload),
      signal: controller?.signal
    });
  }catch(error){
    if(error.name === 'AbortError'){
      throw new Error(options.timeoutMessage || 'Request timed out before VAL received a usable response.');
    }
    throw error;
  }finally{
    if(timeoutId) window.clearTimeout(timeoutId);
  }
  const text = await response.text();
  let data = {};
  try{ data = text ? JSON.parse(text) : {}; }
  catch(e){ data = {content: text}; }
  if(!response.ok || data.ok === false){
    const error = new Error(data.error || data.message || 'Request failed.');
    error.data = data;
    error.status = response.status;
    throw error;
  }
  playValCompletionCue({cue:completionCue,requestStartedAt});
  return data;
}

async function postFormData(url, payload, options = {}){
  const completionCue = shouldPlayValCompletionCue(url, options);
  const requestStartedAt = Date.now();
  const response = await fetch(url, {
    method: 'POST',
    credentials: 'same-origin',
    body: payload
  });
  const text = await response.text();
  let data = {};
  try{ data = text ? JSON.parse(text) : {}; }
  catch(e){ data = {content: text}; }
  if(!response.ok || data.ok === false){
    const error = new Error(data.error || data.message || 'Request failed.');
    error.data = data;
    error.status = response.status;
    throw error;
  }
  playValCompletionCue({cue:completionCue,requestStartedAt});
  return data;
}

async function patchJson(url, payload){
  const response = await fetch(url, {
    method: 'PATCH',
    credentials: 'same-origin',
    headers: {'Content-Type': 'application/json'},
    body: JSON.stringify(payload || {})
  });
  const text = await response.text();
  let data = {};
  try{ data = text ? JSON.parse(text) : {}; }
  catch(e){ data = {content: text}; }
  if(!response.ok || data.ok === false){
    const error = new Error(data.error || data.message || 'Request failed.');
    error.data = data;
    error.status = response.status;
    throw error;
  }
  return data;
}

async function getJson(url, {cache = 'default', timeoutMs = 0, timeoutMessage = ''} = {}){
  const controller = timeoutMs && window.AbortController ? new AbortController() : null;
  const timeoutId = controller ? window.setTimeout(() => controller.abort(), timeoutMs) : null;
  let response;
  try{
    response = await fetch(url, {credentials: 'same-origin', cache, signal: controller?.signal});
  }catch(error){
    if(error.name === 'AbortError'){
      throw new Error(timeoutMessage || 'VAL took too long to return a usable response.');
    }
    throw error;
  }finally{
    if(timeoutId) window.clearTimeout(timeoutId);
  }
  const text = await response.text();
  let data = {};
  try{ data = text ? JSON.parse(text) : {}; }
  catch(e){ data = {content: text}; }
  if(!response.ok || data.ok === false){
    const error = new Error(data.error || data.message || 'Request failed.');
    error.data = data;
    error.status = response.status;
    throw error;
  }
  return data;
}

function showFeatureComingSoon(label){
  setWorkspaceContent({
    lens: 'Coming Soon',
    title: label + ' is coming soon.',
    meaning: 'This surface is intentionally held back for this VAL until it is connected cleanly.',
    understanding: [
      'No data was opened or changed.',
      'This protects onboarding from showing unfinished or cross-client context.',
      'The rest of Hearth remains available.'
    ],
    recommendation: 'Continue with the available drawers and Witnessing Session for now.',
    actions: [{label: 'Close and return to desk', workflow: 'cancel:meeting'}],
    label: label + ' coming soon',
    suppressClarityStandard: true
  });
  openWorkspaceShell(label + ' coming soon', {returnTarget:'home'});
}

function applyClientFeatureLocks(){
  if(clientFeatureLocks.projectManagersComingSoon && projectDrawerLink){
    projectDrawerLink.classList.add('drawer-link-coming-soon');
    projectDrawerLink.disabled = true;
    projectDrawerLink.setAttribute('aria-disabled', 'true');
    projectDrawerLink.setAttribute('title', 'Project Managers coming soon');
    const small = projectDrawerLink.querySelector('small');
    if(small) small.textContent = 'Coming soon';
  }
  if(clientFeatureLocks.linkedinHomeComingSoon && linkedinWidget){
    linkedinWidget.classList.add('feature-coming-soon');
    linkedinWidget.setAttribute('aria-disabled', 'true');
    linkedinWidget.setAttribute('title', 'LinkedIn support coming soon');
    const strong = linkedinWidget.querySelector('.linkedin-widget-copy strong');
    const small = linkedinWidget.querySelector('.linkedin-widget-copy small');
    if(strong) strong.textContent = 'Coming Soon';
    if(small) small.textContent = 'LinkedIn support will be connected after onboarding';
  }
}

async function hydrateClientConfig(){
  if(!canUseApi) {
    applyClientFeatureLocks();
    return;
  }
  try{
    const config = await getJson('/api/public-config', {cache:'no-store'}).catch(() => getJson('/api/config', {cache:'no-store'}));
    const flags = config?.featureFlags || {};
    clientFeatureLocks.projectManagersComingSoon = Boolean(flags.projectManagersComingSoon);
    clientFeatureLocks.linkedinHomeComingSoon = Boolean(flags.linkedinHomeComingSoon);
  }catch(error){
    console.warn('[hearth] client config unavailable', error.message);
  }
  applyClientFeatureLocks();
}

