async function runCowork(mode, messageOverride = ''){
  const input = projectCleanText(messageOverride) || workspaceInputValue('cowork');
  let visiblePrompt = input || 'Help me think through the most useful next step from the Hearth.';
  const keepHomeCoworkOpen = Boolean(deskWorkspace?.classList.contains('home-cowork-mode') && homeCoworkResponseNode());
  if(keepHomeCoworkOpen && await confirmPendingHomeCoworkActionPacket(visiblePrompt)){
    const textarea = homeCoworkTextareaNode();
    if(textarea) textarea.value = '';
    return;
  }
  if(keepHomeCoworkOpen && pendingHomeCoworkActionDraft && input && !homeCoworkNeedsActionPrep(input)){
    if(pendingHomeCoworkActionDraft.kind === 'email' && pendingHomeCoworkActionDraft.contact?.name){
      visiblePrompt = 'Send ' + pendingHomeCoworkActionDraft.contact.name + ' an email saying: "' + input.replace(/"/g, "'") + '"';
      pendingHomeCoworkActionDraft = null;
    }
  }
  const suppressVisibleUserPrompt = Boolean(mode === 'meeting_prep' && activeMeetingPrepAutoPrompt);
  const progressTimers = [];
  const clearProgressTimers = () => progressTimers.splice(0).forEach((timer) => window.clearTimeout(timer));
  const heldContext = activeCoworkHeldContext || '';
  const observerCoworkLane = Boolean(deskWorkspace?.classList.contains('observer-cowork-active') || activeCoworkEntry?.entrypointId === 'observer.discussion' || activeCoworkEntry?.entrypointId === 'board.chief_of_staff');
  const calendarContextLines = calendarCoworkContextLines();
  const hasSelectedCoworkSource = Boolean(activeCoworkSelectedSourceContext && typeof activeCoworkSelectedSourceContext === 'object' && Object.keys(activeCoworkSelectedSourceContext).length);
  const actionPrepLane = Boolean(mode !== 'meeting_prep' && !heldContext && !activeProjectCoworkTarget && homeCoworkNeedsActionPrep(visiblePrompt));
  const needsFullValContext = Boolean(mode !== 'meeting_prep' && !heldContext && !activeProjectCoworkTarget && homeCoworkNeedsFullValContext(visiblePrompt));
  const voiceFastLane = Boolean(valCoworkVoiceState.active && mode !== 'meeting_prep' && !needsFullValContext && !actionPrepLane);
  const chatFastLane = Boolean(keepHomeCoworkOpen && mode !== 'meeting_prep' && !heldContext && !activeProjectCoworkTarget && !hasSelectedCoworkSource && !needsFullValContext && !actionPrepLane);
  const conversationFastLane = Boolean(voiceFastLane || chatFastLane || actionPrepLane);
  const calendarContext = calendarContextLines.length
    ? 'Current calendar context from the Hearth sidebar. Use this when the user asks about calendar, meetings, schedule, or what is next. Do not invent events beyond this list.\n' + calendarContextLines.join('\n')
    : '';
  const heldSystemPrompt = [
    heldContext ? (observerCoworkLane
      ? 'You are answering from the selected Board Observer card, not from generic Home VAL. Use the loaded observer context first. If the user asks for evidence, context, what this observer noticed, or which relationship/person is implicated, answer only from the loaded observer card. If names are not attached, say that plainly and do not invent names.\n\n' + heldContext
      : 'Use this held context silently. Do not quote, dump, summarize, or expose it unless the user explicitly asks to see context. Refer to it only by producing useful judgment and next steps.\n\n' + heldContext) : '',
    calendarContext
  ].filter(Boolean).join('\n\n');
  if(keepHomeCoworkOpen && input && !suppressVisibleUserPrompt){
    appendHomeCoworkMessage('user', input);
    const textarea = homeCoworkTextareaNode();
    if(textarea) textarea.value = '';
  }
  if(keepHomeCoworkOpen && observerCoworkLane){
    const cardAnswer = observerCoworkCardAnswer(visiblePrompt, activeCoworkEntry?.context || {});
    if(cardAnswer){
      appendHomeCoworkMessage('val', cardAnswer);
      return;
    }
  }
  if(keepHomeCoworkOpen && hasSelectedCoworkSource && !observerCoworkLane){
    const briefAnswer = alignmentCoworkBriefAnswer(visiblePrompt, activeCoworkSelectedSourceContext);
    if(briefAnswer){
      appendHomeCoworkMessage('val', briefAnswer);
      const textarea = homeCoworkTextareaNode();
      if(textarea) textarea.value = '';
      return;
    }
  }
  if(mockScrapers || !canUseApi){
    if(keepHomeCoworkOpen){
      appendHomeCoworkMessage('val', mode === 'draft' ? 'A draft can begin here. Start with one plain paragraph, then refine from there.' : 'Name the decision, list the tradeoffs, and choose the next reversible step.');
      const textarea = homeCoworkTextareaNode();
      if(textarea) textarea.value = '';
      return;
    }
    setWorkspaceContent({
      lens: 'Co-Work with VAL',
      title: mode === 'draft' ? 'A draft can begin here.' : 'Here is the first useful shape.',
      meaning: 'VAL would use the held context and your Co-Work prompt to prepare a private working draft.',
      understanding: [
        'Prompt: ' + visiblePrompt,
        heldContext ? 'VAL is holding the source context privately.' : '',
        'This stays inside the desk workspace.',
        'No external action is taken from Co-Work without a separate approval step.'
      ].filter(Boolean),
      recommendation: mode === 'draft' ? 'Start with one plain paragraph, then refine from there.' : 'Name the decision, list the tradeoffs, and choose the next reversible step.',
      actions: [
        {label: 'Keep working', workflow: 'cowork:think'},
        {label: 'Teach VAL from this', workflow: 'teach'},
        {label: 'Close and return to desk', workflow: 'cancel:meeting'}
      ],
      label: 'Co-Work with VAL result'
    });
    renderWorkspaceInput({
      label: 'Continue Co-Work',
      placeholder: 'Add the next thought...',
      helper: 'Mock-safe mode is on, so this did not call the live chat route.',
      mode: 'cowork',
      value: input
    });
    return;
  }
  if(keepHomeCoworkOpen){
    const textarea = homeCoworkTextareaNode();
    if(suppressVisibleUserPrompt && textarea){
      textarea.value = '';
      textarea.placeholder = 'Add the next thought...';
    }
    if(mode !== 'meeting_prep'){
      if(observerCoworkLane || voiceFastLane){
        hideCoworkContextGathering();
      }else if(actionPrepLane){
        const actionDetail = homeCoworkFullContextDetail(visiblePrompt);
        showCoworkContextGathering(actionDetail, {noTimeout:true});
        if(valCoworkVoiceState.active) speakValCoworkMessage(actionDetail);
      }else if(conversationFastLane){
        showCoworkContextGathering('VAL is thinking with you.', {noTimeout:true});
      }else if(needsFullValContext){
        const fullContextDetail = homeCoworkFullContextDetail(visiblePrompt);
        showCoworkContextGathering(fullContextDetail, {noTimeout:true});
        if(valCoworkVoiceState.active) speakValCoworkMessage(fullContextDetail);
      }else{
        showCoworkContextGathering('VAL is gathering the scoped context for this conversation.', {noTimeout:true});
      }
    }else{
      appendHomeCoworkMessage('val', 'I am preparing your meeting brief. This can take a minute or two while VAL checks the meeting context and public signals.');
      progressTimers.push(window.setTimeout(() => {
        appendHomeCoworkMessage('val', 'Still working. This meeting has more context to reason through, so VAL is taking a little longer than usual.');
      }, 45000));
      progressTimers.push(window.setTimeout(() => {
        appendHomeCoworkMessage('val', 'Still preparing the brief. The screen has not frozen; VAL is waiting on the model response.');
      }, 90000));
    }
  }else{
    setWorkspaceContent({
      lens: 'Co-Work with VAL',
      title: 'VAL is thinking with you.',
      meaning: 'Co-Work is becoming a private working response.',
      understanding: [
        'VAL is holding the relevant context privately.',
        'VAL can prepare drafts, options, or decision framing.',
        'External action still requires approval.'
      ],
      recommendation: 'Stay with the thought; VAL will bring back the next useful shape.',
      actions: [{label: 'Close and return to desk', workflow: 'cancel:meeting'}],
      label: 'Co-Work with VAL loading'
    });
  }
  try{
    const requestOptions = hasSelectedCoworkSource ? {
      timeoutMs: 22000,
      timeoutMessage: 'I have the selected source loaded, but this answer took too long. Ask for one concrete output and I will answer from the loaded packet.'
    } : observerCoworkLane ? {
      timeoutMs: 18000,
      timeoutMessage: 'The observer answer took too long. Ask one direct question about the loaded card and I will answer from that card only.'
    } : conversationFastLane ? {
      timeoutMs: actionPrepLane ? 14000 : (voiceFastLane ? 22000 : 28000),
      timeoutMessage: actionPrepLane
        ? 'I heard you, but preparing that action took too long. Ask again with the person and the action in one sentence.'
        : voiceFastLane
        ? 'I heard you, but the voice response took too long. Ask again in one shorter sentence.'
        : 'I took too long to answer this chat turn. Try one narrower question.'
    } : (valCoworkVoiceState.active ? {
      timeoutMs: 16000,
      timeoutMessage: 'I’m still gathering that context. Ask me one narrower version and I’ll stay with you.'
    } : {});
    const result = await postJson('/api/val/chat', {
      channel: 'hearth_cowork',
      title: observerCoworkLane ? (activeCoworkEntry?.title || 'Observer Co-Work') : 'Co-Work from Hearth',
      latencyMode: observerCoworkLane ? 'observer_card' : (actionPrepLane ? 'action_fast' : (voiceFastLane ? 'voice_fast' : (conversationFastLane ? 'chat_fast' : 'full_context'))),
      voiceMode: Boolean(voiceFastLane || (actionPrepLane && valCoworkVoiceState.active)),
      messages: [
        ...(heldSystemPrompt ? [{role: 'system', content: heldSystemPrompt}] : []),
        {role: 'user', content: visiblePrompt}
      ],
      heldContext,
      projectContext: workspaceReturnTarget === 'project' ? activeProjectChatContext() : null,
      selectedSourceContext: activeCoworkSelectedSourceContext,
      dashboard: {
        hearth: title.textContent,
        witness: witness.textContent,
        orientation: orientation.textContent,
        permission: permission.textContent,
        calendar: calendarContextLines
      }
    }, requestOptions);
    const content = result.message?.content || 'VAL prepared a response.';
    clearProgressTimers();
    if(result.externalActionPacket){
      pendingHomeCoworkActionPacket = result.externalActionPacket;
      pendingHomeCoworkActionDraft = null;
    }else if(result.hearthActionPrep && result.needs === 'message_body'){
      pendingHomeCoworkActionDraft = {kind:result.actionKind, contact:result.contact || null};
    }
    if(keepHomeCoworkOpen){
      appendHomeCoworkMessage('val', content, {meetingPrep: mode === 'meeting_prep'});
      const textarea = homeCoworkTextareaNode();
      if(textarea){
        textarea.value = '';
        textarea.placeholder = 'Add the next thought...';
      }
      return;
    }
    setWorkspaceContent({
      lens: 'Co-Work with VAL',
      title: 'VAL prepared the next useful shape.',
      meaning: content,
      understanding: [
        result.saved ? 'This conversation was saved.' : (result.saveWarning || 'This conversation may not have been saved.'),
        result.createdTasks?.length ? result.createdTasks.length + ' task candidate(s) were detected.' : 'No task was created automatically.',
        'No external action was taken.'
      ],
      recommendation: 'Review this, then keep working or turn it into a prepared artifact when it feels true.',
      actions: [
        {label: 'Keep working', workflow: 'cowork:think'},
        {label: 'Teach VAL from this', workflow: 'teach'},
        {label: 'Close and return to desk', workflow: 'cancel:meeting'}
      ],
      label: 'Co-Work with VAL result'
    });
    renderWorkspaceInput({
      label: 'Continue Co-Work',
      placeholder: 'Add the next thought...',
      helper: 'Co-Work remains private until you choose an approved action elsewhere.',
      mode: 'cowork',
      value: input
    });
  }catch(error){
    clearProgressTimers();
    if(keepHomeCoworkOpen){
      const recoveryMessage = valCoworkVoiceState.active
        ? (error.message || 'I heard you, but that turn did not complete. Ask me one smaller thing and I’ll stay with you.')
        : 'Co-Work needs attention: ' + error.message + '\n\nNo external action was taken.';
      appendHomeCoworkMessage('val', recoveryMessage, {silentVoice:!valCoworkVoiceState.active});
      return;
    }
    setWorkspaceContent({
      lens: 'Co-Work with VAL',
      title: 'Co-Work needs attention.',
      meaning: 'VAL could not complete the co-working response.',
      understanding: [error.message, 'Nothing external was changed.', 'Your prompt is still yours to refine.'],
      recommendation: 'Try a smaller prompt or return to the desk.',
      actions: [
        {label: 'Try again', workflow: 'cowork:think'},
        {label: 'Close and return to desk', workflow: 'cancel:meeting'}
      ],
      label: 'Co-Work with VAL error'
    });
    renderWorkspaceInput({
      label: 'Co-Work',
      placeholder: 'Try a smaller prompt...',
      helper: 'No external action was taken.',
      mode: 'cowork',
      value: input
    });
  }
}

async function runTeachVal(mode){
  const input = workspaceInputValue('teach');
  const prompt = input || "This wasn't useful. Help VAL understand why.";
  if(mode === 'review'){
    if(mockScrapers || !canUseApi){
      setWorkspaceContent({
        lens: 'Teach VAL',
        title: 'Review updates would be prepared.',
        meaning: 'VAL would gather pending learning candidates for approval.',
        understanding: [
          'Relationship, project, Teach VAL, and priority-rule candidates remain reviewable.',
          'No durable memory is committed automatically.',
          'Mock-safe mode is on, so no backend call ran.'
        ],
        recommendation: 'Approve only what you want VAL to remember or apply.',
        actions: [
          {label: 'Extract teaching signal', workflow: 'teach:extract'},
          {label: 'Close and return to desk', workflow: 'cancel:meeting'}
        ],
        label: 'Teach VAL review updates'
      });
      return;
    }
    const result = await postJson('/api/val/review-updates/build', {limit: 20});
    setWorkspaceContent({
      lens: 'Teach VAL',
      title: result.count ? result.count + ' learning update' + (result.count === 1 ? ' is' : 's are') + ' ready for review.' : 'No learning updates need review right now.',
      meaning: 'VAL gathered reviewable updates without committing them automatically.',
      understanding: (result.updates || []).slice(0, 3).map((update) => update.title || update.summary || update.targetType || 'Review update').concat(['No external action was taken.']),
      recommendation: 'Open the review queue when you want to approve, reject, or edit what VAL learns.',
      actions: [
        {label: 'Open VAL review queue', workflow: 'reviewQueue'},
        {label: 'Extract teaching signal', workflow: 'teach:extract'},
        {label: 'Close and return to desk', workflow: 'cancel:meeting'}
      ],
      label: 'Teach VAL review updates'
    });
    return;
  }
  if(mockScrapers || !canUseApi){
    setWorkspaceContent({
      lens: 'Teach VAL',
      title: 'VAL heard the teaching signal.',
      meaning: 'This would become a reviewable correction or preference, not automatic durable memory.',
      understanding: [
        'Teaching note: ' + prompt,
        'Likely type: correction or preference.',
        'Approval is required before this becomes durable memory.'
      ],
      recommendation: 'Keep the teaching specific: what VAL noticed, what was wrong, and what it should do next time.',
      actions: [
        {label: 'Build review updates', workflow: 'teach:review'},
        {label: 'Close and return to desk', workflow: 'cancel:meeting'}
      ],
      label: 'Teach VAL extraction result'
    });
    renderWorkspaceInput({
      label: 'Teach VAL',
      placeholder: 'Add more context...',
      helper: 'Mock-safe mode is on, so this did not call the live extractor.',
      mode: 'teach',
      value: input
    });
    return;
  }
  const result = await postJson('/api/val/executive-instructions/extract', {
    text: prompt,
    sourceType: 'hearth_teach_val',
    sourceId: 'hearth_teach_val',
    authenticatedUserNames: ['Jessa'],
    trustedAuthenticatedUser: true
  });
  const instructions = result.executive_instructions || [];
  setWorkspaceContent({
    lens: 'Teach VAL',
    title: instructions.length ? 'VAL found a possible instruction.' : 'VAL captured this as teaching context.',
    meaning: instructions.length ? 'The instruction is reviewable and no external action was taken.' : 'This looks more like preference or correction context than an executable instruction.',
    understanding: instructions.slice(0, 3).map((instruction) => [
      instruction.requested_action || instruction.instruction_type || 'instruction',
      instruction.authorization || 'approval_required',
      instruction.recommended_next_step || 'review'
    ].join(' / ')).concat(['No external action was taken.']),
    recommendation: 'Use review updates to decide what VAL should actually learn or apply.',
    actions: [
      {label: 'Build review updates', workflow: 'teach:review'},
      {label: 'Close and return to desk', workflow: 'cancel:meeting'}
    ],
    label: 'Teach VAL extraction result'
  });
  renderWorkspaceInput({
    label: 'Teach VAL',
    placeholder: 'Add more context...',
    helper: 'This remains reviewable. Durable memory should be confirmed before promotion.',
    mode: 'teach',
    value: input
  });
}

