function valFirstLookDisplaySource(source,definition){
  const current={...(source||{}),label:source?.label||definition.label};
  if(current.id==='krisp'&&Number(current.counts?.reviewed||0)===0&&current.status==='complete'){
    return {
      ...current,
      status:'needs_verification',
      detail:'Krisp is connected, but this First Look did not receive any meeting receipts. That does not prove there are no transcripts.',
      limitNote:'Check that a known meeting is visible in Krisp to this account. VAL will never create a substitute transcript.'
    };
  }
  return current;
}
function valFirstLookCountLabel(source = {}){
  const count=Number(source.counts?.reviewed||0);
  if(!Number.isFinite(count))return '';
  return count+' record'+(count===1?'':'s')+' scanned';
}
function valFirstLookCandidateLabel(candidate = {}){
  const payload=candidate.payload||{};
  const destination=candidate.type==='project'?'Project Managers':'Stewardship';
  if(candidate.decision==='delivered')return 'Delivered to '+destination;
  if(['kept','corrected'].includes(candidate.decision))return 'Ready for '+destination;
  if(candidate.decision==='deferred')return 'Held for later';
  if(candidate.decision==='excluded')return 'Not included';
  return 'Needs your review';
}
function valFirstLookCandidateIdentityNote(candidate = {}){
  const admission=candidate.payload?.admission||{};
  if(candidate.decision==='delivered')return '';
  if(admission.status==='user_confirmation_required')return 'VAL found this name in your Witnessing context. Keep it only if it belongs in your network.';
  if(admission.status==='user_confirmed_identity')return 'Identity confirmed by you.';
  return 'Identity is supported by the cited source evidence.';
}
function valFirstLookCandidateEvidence(candidate = {}){
  const evidence=Array.isArray(candidate.sourceEvidence)?candidate.sourceEvidence:[];
  if(!evidence.length)return '';
  return '<ul class="val-first-look-candidate-evidence">'+evidence.slice(0,4).map(item=>[
    '<li><b>'+escapeHtml(item.source==='witnessing'?'Witnessing':'Source')+'</b> '+escapeHtml(item.title||'Source receipt')+(item.date?' <small>'+escapeHtml(valFirstLookDate(item.date))+'</small>':'')+'</li>'
  ].join('')).join('')+'</ul>';
}
function renderValFirstLookCandidate(candidate = {}){
  const payload=candidate.payload||{};
  const destination=candidate.type==='project'?'Project Managers':'Stewardship';
  const title=payload.proposedName||'Unnamed proposal';
  const canDecide=candidate.decision==='proposed'||candidate.decision==='deferred';
  const canCorrect=candidate.decision!=='delivered'&&candidate.decision!=='excluded';
  return [
    '<article class="val-first-look-candidate" data-state="'+escapeHtml(candidate.decision||'proposed')+'">',
      '<div class="val-first-look-candidate-heading"><span>'+escapeHtml(destination)+'</span><em>'+escapeHtml(valFirstLookCandidateLabel(candidate))+'</em></div>',
      '<h5>'+escapeHtml(title)+'</h5>',
      '<p>'+escapeHtml(payload.note||'VAL found source-backed context that needs your review.')+'</p>',
      '<small>'+escapeHtml(valFirstLookCandidateIdentityNote(candidate))+'</small>',
      payload.confidence?'<small>Confidence: '+escapeHtml(String(payload.confidence).replace(/_/g,' '))+'</small>':'',
      candidate.type==='project'&&payload.knownPeople?.length?'<small>People named: '+escapeHtml(payload.knownPeople.join(', '))+'</small>':'',
      candidate.type==='project'&&payload.onboardingQuestion?'<small>On arrival: '+escapeHtml(payload.onboardingQuestion)+'</small>':'',
      valFirstLookCandidateEvidence(candidate),
      canCorrect?'<label class="val-first-look-candidate-correction"><span>Correct the name</span><input type="text" value="'+escapeHtml(title)+'" data-first-look-candidate-name="'+escapeHtml(candidate.id)+'"></label>':'',
      '<div class="val-first-look-candidate-actions">',
        canDecide?'<button type="button" data-val-witnessing-action="true" data-workflow-action="valFirstLookCandidateDecision:'+escapeHtml(candidate.id)+':kept">Keep</button>':'',
        canCorrect?'<button type="button" data-val-witnessing-action="true" data-workflow-action="valFirstLookCandidateCorrect:'+escapeHtml(candidate.id)+'">Save correction</button>':'',
        canDecide?'<button type="button" data-val-witnessing-action="true" data-workflow-action="valFirstLookCandidateDecision:'+escapeHtml(candidate.id)+':excluded">Not '+(candidate.type==='project'?'a project':'a relationship')+'</button>':'',
      '</div>',
    '</article>'
  ].join('');
}
function renderValFirstLookCandidateMap(){
  const candidates=Array.isArray(valFirstLookCandidates)?valFirstLookCandidates:[];
  const relationships=candidates.filter(candidate=>candidate.type==='relationship');
  const projects=candidates.filter(candidate=>candidate.type==='project');
  const ready=candidates.filter(candidate=>['kept','corrected'].includes(candidate.decision));
  const delivered=candidates.filter(candidate=>candidate.decision==='delivered');
  const coverage=valFirstLookCandidateAnalysis?.sourceReceipt?.witnessingCoverage||{};
  const answersRead=Number(coverage.answersRead||0);
  const answersAccountedFor=Number(coverage.answersAccountedFor||0);
  return [
    '<section class="val-first-look-candidate-map" aria-label="What VAL found">',
      '<span>What VAL found</span>',
      '<h4>A proposed map, ready for your judgment.</h4>',
      '<p>Nothing below exists in a drawer yet. Keep what belongs, correct what needs context, and leave out anything that does not belong.</p>',
      answersRead?'<p><b>Witnessing coverage:</b> '+answersAccountedFor+' of '+answersRead+' answers accounted for. Any relationship or project you explicitly named is shown below as a review packet; the rest remains context and does not become a record on its own.</p>':'',
      relationships.length?'<section><div class="val-first-look-candidate-group-heading"><h5>Relationships for Stewardship</h5><small>'+relationships.length+' proposed</small></div><div class="val-first-look-candidate-grid">'+relationships.map(renderValFirstLookCandidate).join('')+'</div></section>':'',
      projects.length?'<section><div class="val-first-look-candidate-group-heading"><h5>Projects for Project Managers</h5><small>'+projects.length+' proposed</small></div><div class="val-first-look-candidate-grid">'+projects.map(renderValFirstLookCandidate).join('')+'</div></section>':'',
      ready.length?'<div class="val-first-look-delivery"><strong>'+ready.length+' approved item'+(ready.length===1?'':'s')+' ready for delivery.</strong><p>Delivery creates local Stewardship and Project Managers packets with their notes and source references. It does not send, schedule, or change anything outside VAL.</p><button type="button" data-val-witnessing-action="true" data-workflow-action="valFirstLookDeliver">Deliver approved items</button></div>':'',
      delivered.length?'<div class="val-first-look-delivery delivered"><strong>'+delivered.length+' item'+(delivered.length===1?'':'s')+' delivered.</strong><p>VAL created the approved local packets and preserved their First Look notes and source references. Continue Witnessing to Confirm Relationships and the Partnership Promise.</p></div>':'',
    '</section>'
  ].join('');
}
function renderValFirstLookCandidateProgress(){
  const byId=new Map((valFirstLookCandidateProgress||[]).map(item=>[item.id,item]));
  const rows=[
    {id:'witnessing',label:'Witnessing Session'},
    ...valFirstLookSourceOrder,
    {id:'reasoning',label:'Relationship and project map'},
    {id:'review',label:'Review packets'}
  ].map(source=>({...source,...(byId.get(source.id)||{state:'waiting',message:'Waiting for VAL to begin this step.'})}));
  return [
    '<section class="val-first-look-progress" aria-live="polite" aria-label="Proposed map activity">',
      '<span>Building the proposed map</span>',
      '<strong>'+escapeHtml(valFirstLookCandidateActivity||'VAL is preparing the map from the sources you approved.')+'</strong>',
      '<div class="val-first-look-source-grid">',
        rows.map(source=>'<article data-state="'+escapeHtml(source.state||'waiting')+'"><div><b>'+escapeHtml(source.label)+'</b><em>'+escapeHtml(valFirstLookSourceStateLabel(source.state))+'</em></div><p>'+escapeHtml(source.message||'Waiting for VAL to begin this step.')+'</p></article>').join(''),
      '</div>',
    '</section>'
  ].join('');
}
function renderValFirstLookReceipt(run = valFirstLookRun){
  const snapshot = run?.snapshot || {};
  const sources = Array.isArray(snapshot.sources) ? snapshot.sources : [];
  const sourceById = new Map(sources.map(source => [source.id, source]));
  const window = snapshot.window || {start:run?.windowStart || '',end:run?.windowEnd || ''};
  return [
    '<section class="val-first-look-receipt" aria-label="Your First Look receipt">',
      '<span>First Look complete</span>',
      '<h4>VAL checked the sources you approved.</h4>',
      '<p>' + escapeHtml((valFirstLookDate(window.start) || 'The start of your review window') + ' through ' + (valFirstLookDate(window.end) || 'today') + '. This is a private, review-only receipt. VAL did not create projects, relationships, tasks, drafts, or memory.') + '</p>',
      '<div class="val-first-look-source-grid">',
        valFirstLookSourceOrder.map(definition => {
          const original = sourceById.get(definition.id) || {id:definition.id,label:definition.label,status:'unavailable',detail:'This source was not available for the First Look.',examples:[]};
          const source = definition.id==='krisp'&&valFirstLookKrispVerification
            ? valFirstLookKrispVerification
            : valFirstLookDisplaySource(original,definition);
          return [
            '<article data-state="' + escapeHtml(source.status || 'unavailable') + '">',
              '<div><b>' + escapeConnectionHtml(source.label || definition.label) + '</b><em>' + escapeHtml(valFirstLookSourceStateLabel(source.status)) + '</em></div>',
              '<p>' + escapeHtml(source.detail || '') + '</p>',
              valFirstLookCountLabel(source)?'<small>'+escapeHtml(valFirstLookCountLabel(source))+'</small>':'',
              source.limitNote ? '<small>' + escapeHtml(source.limitNote) + '</small>' : '',
              source.error ? '<small>' + escapeHtml(source.error) + '</small>' : '',
              definition.id==='krisp'&&source.status==='needs_verification' ? '<button type="button" class="val-first-look-verify" data-val-witnessing-action="true" data-workflow-action="valWitnessingImportKrisp">Check Krisp meeting receipts again</button>' : '',
            '</article>'
          ].join('');
        }).join(''),
      '</div>',
      valFirstLookCandidates.length?renderValFirstLookCandidateMap():'',
    '</section>'
  ].join('');
}
function renderValFirstLookConversation({state = 'ready', error = '', run = valFirstLookRun} = {}){
  const card = valWitnessingCard('source_review');
  const index = valWitnessingIndex(card);
  const total = valWitnessingCards.length;
  const complete = valFirstLookComplete(run);
  workspaceInputPanel.hidden = false;
  workspaceInputPanel.innerHTML = [
    '<div class="val-conversation val-first-look" data-val-witnessing-state="' + escapeHtml(state) + '">',
      '<div class="val-conversation-progress" aria-label="Witnessing Session progress">',
        '<span>Witnessing Session</span>',
        '<b>' + (index + 1) + ' of ' + total + '</b>',
        '<i style="--progress:' + (((index + 1) / total) * 100).toFixed(2) + '%"></i>',
      '</div>',
      renderValWitnessingPhaseMap(index),
      '<section class="val-conversation-question" aria-label="The First Look">',
        '<span>Movement 8 · The First Look</span>',
        '<h3>Before we move on, VAL will show you exactly what it can see.</h3>',
        '<p class="val-conversation-helper">This is one private, review-only 90-day source receipt. VAL will name each source as it checks it and will not create anything from what it finds.</p>',
      '</section>',
      complete ? (state === 'mapping' ? renderValFirstLookCandidateProgress() : renderValFirstLookReceipt(run)) : state === 'preparing' ? renderValFirstLookProgress() : [
        '<section class="val-first-look-intro" aria-label="Prepare the First Look">',
          '<span>What VAL will check</span>',
          '<ul><li>Gmail message records</li><li>Google Calendar events</li><li>Drive and Docs metadata, without opening document content</li><li>Krisp transcript receipts, preserved exactly as Krisp provided them</li></ul>',
          '<p>Nothing will be routed into Projects, Relationships, Executive Inbox, Transcripts, or memory until you review it later.</p>',
        '</section>',
      ].join(''),
      error ? '<p class="val-conversation-error">' + escapeHtml(error) + '</p>' : '',
      '<div class="val-conversation-actions">',
        complete
          ? (valFirstLookCandidates.length
            ? (valFirstLookCandidates.every(candidate=>candidate.decision==='delivered')?'<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingFirstLookContinue">Continue Witnessing</button>':'')
            : '<button type="button" data-val-witnessing-action="true" data-workflow-action="valFirstLookBuildMap">Build the proposed map</button>')
          : state === 'preparing'
            ? ''
            : '<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingFirstLookPrepare">Prepare my First Look</button>',
      '</div>',
    '</div>'
  ].join('');
}
async function loadValFirstLookRun(){
  if(!canUseApi || mockScrapers) return valFirstLookRun;
  const result = await getJson('/api/val/first-look',{cache:'no-store'});
  valFirstLookRun = result?.run || null;
  valFirstLookCandidates = Array.isArray(result?.candidates)?result.candidates:[];
  valFirstLookCandidateAnalysis = result?.candidateAnalysis || null;
  return valFirstLookRun;
}
async function prepareValFirstLook(){
  if(!canUseApi || mockScrapers){
    renderValFirstLookConversation({state:'ready',error:'The live VAL connection is required before it can read your sources.'});
    return;
  }
  const sourceCard = valWitnessingCard('connect_sources');
  const scope = String(valWitnessingState[sourceCard.category]?.rawResponse || workspaceInputValue('val-witnessing-' + sourceCard.category) || '').trim();
  valFirstLookProgress = valFirstLookSourceOrder.map(source => ({...source,state:'waiting',message:'Waiting for VAL to begin this source.'}));
  valFirstLookActivity = 'Starting your private, review-only First Look.';
  renderValFirstLookConversation({state:'preparing'});
  try{
    const completionCue = captureValCompletionCue();
    const requestStartedAt = Date.now();
    const sessionId = await ensureValWitnessingSession();
    const response = await fetch('/api/val/first-look/prepare',{
      method:'POST',
      credentials:'same-origin',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({sessionId,scope})
    });
    if(!response.ok || !response.body){
      const body = await response.text();
      let payload = {};
      try{payload = body ? JSON.parse(body) : {};}catch(_e){}
      throw new Error(payload.error || 'VAL could not begin the First Look.');
    }
    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let pending = '';
    let completed = false;
    const handleEvent = event => {
      if(event.type === 'progress'){
        if(event.source === 'snapshot'){
          valFirstLookActivity = event.message || valFirstLookActivity;
        }else{
          const current = valFirstLookProgress.find(item => item.id === event.source);
          if(current) Object.assign(current,{state:event.state || current.state,message:event.message || current.message,error:event.error || ''});
        }
        renderValFirstLookConversation({state:'preparing'});
        return;
      }
      if(event.type === 'complete'){
        valFirstLookRun = event.run || null;
        valFirstLookActivity = event.reused ? 'Your existing First Look is ready.' : 'Your First Look receipt is ready.';
        completed = true;
        playValCompletionCue({cue:completionCue,requestStartedAt});
        renderValFirstLookConversation({state:'complete',run:valFirstLookRun});
        hydrateValDrawer();
        return;
      }
      if(event.type === 'error') throw new Error(event.message || 'VAL could not finish the First Look.');
    };
    while(true){
      const chunk = await reader.read();
      if(chunk.done) break;
      pending += decoder.decode(chunk.value,{stream:true});
      const lines = pending.split('\n');
      pending = lines.pop() || '';
      for(const line of lines){
        if(!line.trim()) continue;
        handleEvent(JSON.parse(line));
      }
    }
    if(pending.trim()) handleEvent(JSON.parse(pending));
    if(!completed) throw new Error('VAL finished without returning a First Look receipt.');
  }catch(error){
    renderValFirstLookConversation({state:'ready',error:error.message || 'VAL could not finish the First Look.'});
  }
}
async function importValFirstLookKrisp(){
  if(!canUseApi || mockScrapers) return;
  valFirstLookKrispVerification = {
    id:'krisp',label:'Krisp transcripts',status:'reading',
    detail:'Checking your accessible, owned, shared, and action-item-linked Krisp meetings from the last 30 days.',
    examples:[]
  };
  renderValFirstLookConversation({state:'complete',run:valFirstLookRun});
  try{
    const completionCue = captureValCompletionCue();
    const requestStartedAt = Date.now();
    const response=await fetch('/api/val/first-look/krisp-import',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'});
    if(!response.ok||!response.body){
      const body=await response.text();
      let payload={};
      try{payload=body?JSON.parse(body):{};}catch(_e){}
      throw new Error(payload.error||'Krisp could not begin the 30-day intake.');
    }
    const reader=response.body.getReader();
    const decoder=new TextDecoder();
    let pending='';
    let completed=false;
    const handleEvent=event=>{
      if(event.type==='progress'){
        valFirstLookKrispVerification={
          ...valFirstLookKrispVerification,
          status:event.state||'reading',detail:event.message||valFirstLookKrispVerification.detail,
          counts:{...(valFirstLookKrispVerification.counts||{}),reviewed:Number(event.count||valFirstLookKrispVerification.counts?.reviewed||0)}
        };
        renderValFirstLookConversation({state:'complete',run:valFirstLookRun});
        return;
      }
      if(event.type==='complete'){
        valFirstLookKrispVerification=event.source||null;
        completed=true;
        playValCompletionCue({cue:completionCue,requestStartedAt});
        return;
      }
      if(event.type==='error')throw new Error(event.message||'Krisp could not finish the 30-day intake.');
    };
    while(true){
      const chunk=await reader.read();
      if(chunk.done)break;
      pending+=decoder.decode(chunk.value,{stream:true});
      const lines=pending.split('\n');
      pending=lines.pop()||'';
      for(const line of lines){if(line.trim())handleEvent(JSON.parse(line));}
    }
    if(pending.trim())handleEvent(JSON.parse(pending));
    if(!completed)throw new Error('Krisp finished without returning an intake receipt.');
  }catch(error){
    valFirstLookKrispVerification={
      id:'krisp',label:'Krisp transcripts',status:'unavailable',
      detail:'Krisp could not complete the 30-day intake right now.',examples:[],
      error:error.message||'Krisp could not be imported.'
    };
  }
  renderValFirstLookConversation({state:'complete',run:valFirstLookRun});
}
async function prepareValFirstLookCandidateMap(){
  if(!canUseApi || mockScrapers || !valFirstLookRun?.id){
    renderValFirstLookConversation({state:'complete',error:'Open your completed First Look before building the proposed map.'});
    return;
  }
  valFirstLookCandidateProgress=[
    {id:'witnessing',state:'waiting',message:'Waiting to read your Witnessing answers.'},
    ...valFirstLookSourceOrder.map(source=>({id:source.id,state:'waiting',message:'Waiting to read this source.'})),
    {id:'reasoning',state:'waiting',message:'Waiting to map the source evidence.'},
    {id:'review',state:'waiting',message:'Waiting to prepare your review packets.'}
  ];
  valFirstLookCandidateActivity='Starting a private, review-only proposed map.';
  renderValFirstLookConversation({state:'mapping',run:valFirstLookRun});
  try{
    const completionCue = captureValCompletionCue();
    const requestStartedAt = Date.now();
    const response=await fetch('/api/val/first-look/'+encodeURIComponent(valFirstLookRun.id)+'/candidates/prepare',{
      method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:'{}'
    });
    if(!response.ok||!response.body){
      const body=await response.text();
      let payload={};
      try{payload=body?JSON.parse(body):{};}catch(_e){}
      throw new Error(payload.error||'VAL could not prepare the proposed map.');
    }
    const reader=response.body.getReader();
    const decoder=new TextDecoder();
    let pending='';
    let completed=false;
    const handleEvent=event=>{
      if(event.type==='progress'){
        if(event.source==='snapshot')valFirstLookCandidateActivity=event.message||valFirstLookCandidateActivity;
        else{
          const current=valFirstLookCandidateProgress.find(item=>item.id===event.source);
          if(current)Object.assign(current,{state:event.state||current.state,message:event.message||current.message,error:event.error||''});
        }
        renderValFirstLookConversation({state:'mapping',run:valFirstLookRun});
        return;
      }
      if(event.type==='complete'){
        valFirstLookCandidates=Array.isArray(event.candidates)?event.candidates:[];
        valFirstLookCandidateAnalysis=event.candidateAnalysis||valFirstLookCandidateAnalysis;
        valFirstLookCandidateActivity=event.reused?'Your proposed map is ready to review.':'Your proposed map is ready to review.';
        completed=true;
        playValCompletionCue({cue:completionCue,requestStartedAt});
        renderValFirstLookConversation({state:'complete',run:valFirstLookRun});
        return;
      }
      if(event.type==='error')throw new Error(event.message||'VAL could not prepare the proposed map.');
    };
    while(true){
      const chunk=await reader.read();
      if(chunk.done)break;
      pending+=decoder.decode(chunk.value,{stream:true});
      const lines=pending.split('\n');
      pending=lines.pop()||'';
      for(const line of lines){if(line.trim())handleEvent(JSON.parse(line));}
    }
    if(pending.trim())handleEvent(JSON.parse(pending));
    if(!completed)throw new Error('VAL finished without returning the proposed map.');
  }catch(error){
    renderValFirstLookConversation({state:'complete',run:valFirstLookRun,error:error.message||'VAL could not prepare the proposed map.'});
  }
}
async function decideValFirstLookCandidate(candidateId='',decision='kept',payload={}){
  if(!canUseApi || mockScrapers || !valFirstLookRun?.id)return;
  try{
    const result=await postJson('/api/val/first-look/'+encodeURIComponent(valFirstLookRun.id)+'/candidates/'+encodeURIComponent(candidateId)+'/decision',{decision,...payload});
    valFirstLookCandidates=Array.isArray(result?.candidates)?result.candidates:valFirstLookCandidates;
    renderValFirstLookConversation({state:'complete',run:valFirstLookRun});
  }catch(error){
    renderValFirstLookConversation({state:'complete',run:valFirstLookRun,error:error.message||'VAL could not save that review choice.'});
  }
}
async function correctValFirstLookCandidate(candidateId=''){
  const input=workspaceInputPanel.querySelector('[data-first-look-candidate-name="'+String(candidateId).replace(/"/g,'')+'"]');
  const proposedName=String(input?.value||'').trim();
  if(!proposedName){
    renderValFirstLookConversation({state:'complete',run:valFirstLookRun,error:'Give this proposed item a clear name first.'});
    return;
  }
  await decideValFirstLookCandidate(candidateId,'corrected',{proposedName});
}
async function deliverValFirstLookCandidates(){
  if(!canUseApi || mockScrapers || !valFirstLookRun?.id)return;
  try{
    const result=await postJson('/api/val/first-look/'+encodeURIComponent(valFirstLookRun.id)+'/apply',{});
    valFirstLookCandidates=Array.isArray(result?.candidates)?result.candidates:valFirstLookCandidates;
    valFirstLookDelivery=result?.changeSet||null;
    renderValFirstLookConversation({state:'complete',run:valFirstLookRun});
  }catch(error){
    renderValFirstLookConversation({state:'complete',run:valFirstLookRun,error:error.message||'VAL could not deliver the approved items.'});
  }
}
function openValFirstLookDestination(destination=''){
  closeWorkspace();
  if(destination==='stewardship'){
    relationshipDrawerLink?.click();
    return;
  }
  if(destination==='projects')projectDrawerLink?.click();
}
async function continueValWitnessingAfterFirstLook(){
  if(valFirstLookCandidates.length&&!valFirstLookCandidates.every(candidate=>candidate.decision==='delivered')){
    renderValFirstLookConversation({state:'complete',run:valFirstLookRun,error:'Review and deliver the proposed relationship and project packets before moving past the First Look.'});
    return;
  }
  await openValWitnessingQuestion('key_relationships');
}

function renderValWitnessingCompletion(result = {}){
  const memoryCount = Number(result?.memory?.length || result?.promotion?.memoryCount || 0);
  const savedLine = memoryCount
    ? 'I saved this Witnessing Session into VAL so it can inform drafts, relationship context, calendar protection, inbox review, documents, and working agreements.'
    : 'I saved this Witnessing Session as VAL partnership context. I will keep treating it as evidence to confirm, not a set of assumptions.';
  return [
    '<section class="val-witnessing-complete" aria-label="Witnessing Session complete">',
      '<span>Partnership Promise</span>',
      '<h3>Your Witnessing Session is now inside VAL.</h3>',
      '<p>' + escapeHtml(savedLine) + '</p>',
      '<p>I will use what you shared to support your vision, protect your capacity, preserve your voice, and notice when future work starts pulling against what matters.</p>',
      '<p>I will still ask before acting. Being witnessed is not the same as giving me permission to send, publish, change records, or decide for you.</p>',
      '<p>From here, the next layer is practical: connect sources, review what I notice, confirm key relationships, and let the rest of VAL begin working from the partnership we just formed.</p>',
    '</section>',
    '<div class="val-conversation-actions">',
      '<button type="button" data-workflow-action="cancel:val">Back to VAL</button>',
      '<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingOpenBoard">View Board of Observers</button>',
      '<button type="button" data-workflow-action="valConnections:review">Connect sources</button>',
    '</div>'
  ].join('');
}

function renderValWitnessingConversation({card, rawResponse = '', state = 'question', error = '', witness = null}){
  const mode = 'val-witnessing-' + card.category;
  const index = valWitnessingIndex(card);
  const total = valWitnessingCards.length;
  const next = card.next ? valWitnessingCard(card.next) : null;
  const answered = state === 'thinking' || state === 'shaping' || state === 'witnessed' || state === 'confirmed' || state === 'paused';
  const showAnswer = state === 'shaping' || state === 'witnessed' || state === 'confirmed' || state === 'paused';
  const witnessed = normalizeValWitnessingPayload(witness || valWitnessingState[card.category]?.witness || {}, rawResponse);
  if(card.id === 'source_review'){
    renderValFirstLookConversation({state:valFirstLookComplete() ? 'complete' : state === 'preparing' ? 'preparing' : 'ready',error,run:valFirstLookRun});
    return;
  }
  if(state === 'intro'){
    workspaceInputPanel.hidden = false;
    workspaceInputPanel.innerHTML = [
      '<div class="val-conversation" data-val-witnessing-state="' + escapeHtml(state) + '">',
        '<div class="val-conversation-progress" aria-label="Witnessing Session progress">',
          '<span>Witnessing Session</span>',
          '<b>Before we begin</b>',
          '<i style="--progress:0%"></i>',
        '</div>',
        '<section class="val-conversation-opening" aria-label="VAL introduction">',
          '<span>Before we begin</span>',
          renderValWitnessingLineList(valWitnessingOpeningLines()),
          '<p class="val-conversation-line val-conversation-question-intro">May I ask you my first question?</p>',
        '</section>',
        '<div class="val-conversation-actions">',
          '<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingQuestion:' + escapeHtml(card.id) + '">Begin</button>',
        '</div>',
      '</div>'
    ].join('');
    return;
  }
  if(state === 'complete'){
    workspaceInputPanel.hidden = false;
    workspaceInputPanel.innerHTML = [
      '<div class="val-conversation" data-val-witnessing-state="' + escapeHtml(state) + '">',
        '<div class="val-conversation-progress" aria-label="Witnessing Session progress">',
          '<span>Witnessing Session</span>',
          '<b>' + total + ' of ' + total + '</b>',
          '<i style="--progress:100%"></i>',
        '</div>',
        renderValWitnessingPhaseMap(total - 1),
        renderValWitnessingCompletion(witness || {}),
      '</div>'
    ].join('');
    return;
  }
  workspaceInputPanel.hidden = false;
  workspaceInputPanel.innerHTML = [
    '<div class="val-conversation" data-val-witnessing-state="' + escapeHtml(state) + '">',
      '<div class="val-conversation-progress" aria-label="Witnessing Session progress">',
          '<span>Witnessing Session</span>',
          '<b>' + (index + 1) + ' of ' + total + '</b>',
        '<i style="--progress:' + (((index + 1) / total) * 100).toFixed(2) + '%"></i>',
      '</div>',
      renderValWitnessingPhaseMap(index),
      answered ? '<p class="val-conversation-memory-line">Before we began, VAL promised to understand you accurately before trying to sound intelligent.</p>' : '',
      '<section class="val-conversation-question" aria-label="Current question">',
        '<span>' + (index === 0 ? 'First question' : escapeHtml(card.movement)) + '</span>',
        '<h3>' + escapeHtml(valWitnessingQuestionText(card)) + '</h3>',
      '</section>',
      showAnswer ? [
        '<section class="val-conversation-answer" aria-label="Your answer">',
          '<span>You</span>',
          '<p>' + escapeHtml(rawResponse) + '</p>',
        '</section>'
      ].join('') : state === 'thinking' ? '' : [
        '<label class="val-conversation-input">',
          card.id === 'connect_sources' ? '<span>Optional: what should VAL look for first?</span>' : '',
          '<textarea data-workspace-input="' + escapeHtml(mode) + '" placeholder="' + escapeHtml(card.placeholder) + '">' + escapeHtml(rawResponse) + '</textarea>',
        '</label>',
        valWitnessingContextTools(card),
        '<p class="val-conversation-helper">' + escapeHtml(card.helper) + '</p>',
        '<div class="val-conversation-actions">',
          '<button type="button" data-val-witnessing-action="true" data-workflow-action="' + (card.id === 'connect_sources' ? 'valWitnessingSourcesContinue:' : 'valWitnessingSave:') + escapeHtml(card.category) + '">' + (card.id === 'connect_sources' ? 'Continue to First Look' : 'Continue') + '</button>',
        '</div>'
      ].join(''),
      error ? '<p class="val-conversation-error">' + escapeHtml(error) + '</p>' : '',
      state === 'paused' ? [
        '<div class="val-conversation-actions">',
        next ? '<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingSkipTo:' + escapeHtml(next.id) + '">Continue testing questions</button>' : '',
          '<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingFresh">Start Fresh</button>',
          '<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingQuestion:' + escapeHtml(card.id) + '">Try again</button>',
        '</div>'
      ].join('') : '',
      state === 'thinking' ? [
        '<section class="val-conversation-val" aria-label="VAL response">',
          '<span>VAL</span>',
          '<div class="val-thinking-state" role="status" aria-live="polite">',
            '<div class="val-thinking-pulse" aria-hidden="true"><i></i><i></i><i></i></div>',
            '<p><strong>VAL is observing and witnessing...</strong><small>Your answer stays here while VAL prepares a thoughtful response.</small></p>',
          '</div>',
        '</section>'
      ].join('') : '',
      state === 'shaping' ? [
        '<section class="val-conversation-val" aria-label="VAL response">',
          '<span>VAL</span>',
          '<div class="val-thinking-state" role="status" aria-live="polite">',
            '<div class="val-thinking-pulse" aria-hidden="true"><i></i><i></i><i></i></div>',
            '<p><strong>VAL is carrying that forward...</strong><small>It is shaping the next question from what you just confirmed.</small></p>',
          '</div>',
        '</section>'
      ].join('') : '',
      state === 'witnessed' ? [
        '<section class="val-conversation-val" aria-label="VAL response">',
          '<span>VAL</span>',
          '<div class="val-thinking-pause" aria-hidden="true"></div>',
          renderValWitnessingLineList(witnessed.lines, 'val-witnessed-line'),
        '</section>',
        '<div class="val-confirmation-actions" aria-label="Confirm VAL understanding">',
          '<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingConfirm:yes:' + escapeHtml(card.category) + '">' + escapeHtml(witnessed.confirmation_options[0] || 'Yes, exactly') + '</button>',
          '<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingConfirm:mostly:' + escapeHtml(card.category) + '">' + escapeHtml(witnessed.confirmation_options[1] || 'Mostly') + '</button>',
          '<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingConfirm:clarify:' + escapeHtml(card.category) + '">' + escapeHtml(witnessed.confirmation_options[2] || 'Let me clarify') + '</button>',
        '</div>'
      ].join('') : '',
      state === 'confirmed' ? [
        '<section class="val-conversation-val" aria-label="VAL promise">',
          '<span>VAL</span>',
          renderValWitnessingLineList(witnessed.follow_up_lines, 'val-witnessed-line'),
        '</section>',
        next ? [
          '<div class="val-conversation-actions">',
            '<button type="button" data-val-witnessing-action="true" data-workflow-action="valWitnessingQuestion:' + escapeHtml(next.id) + '">Continue</button>',
          '</div>'
        ].join('') : ''
      ].join('') : '',
    '</div>'
  ].join('');
  if(card.id === 'connect_sources' && state === 'question') window.setTimeout(refreshValWitnessingConnections, 0);
}

async function openValWitnessingSession(cardId = 'meeting_val', options = {}){
  if(!(await ensureOpenAIConnectionBeforeWitnessing(cardId,options))) return;
  let resumeTarget = null;
  if(options.fresh){
    await startFreshValWitnessingSession();
  }else if(options.resume){
    try{
      const resumed = await resumeValWitnessingSession();
      resumeTarget = resumed.target;
      cardId = resumeTarget.card.id;
    }catch(error){
      valLiveStatus.textContent = 'Could not restore the Witnessing Session: ' + error.message;
    }
  }else if(cardId !== 'meeting_val'){
    await ensureValWitnessingSession();
  }
  const card = valWitnessingCard(cardId);
  const index = valWitnessingIndex(card);
  let sessionLine = mockScrapers || !canUseApi ? 'Prototype mode: this answer can be staged without calling the onboarding API.' : 'Witnessing Session ready.';
  if(canUseApi){
    try{
      const sessionId = await ensureValWitnessingSession();
      sessionLine = sessionId ? 'Witnessing Session is active inside VAL Home.' : 'VAL did not return a session id yet.';
    }catch(error){
      sessionLine = 'Witnessing Session API needs attention: ' + error.message;
    }
  }
  setWorkspaceContent({
    lens: 'VAL Witnessing Session',
    title: index === 0 ? 'Welcome' : card.title,
    meaning: index === 0
      ? "Before we connect your accounts or import your work, I'd rather meet you."
      : "Let's keep going slowly.",
    understanding: [sessionLine],
    recommendation: card.question,
    actions: [{label:'Back to VAL', workflow:'cancel:val'}],
    label: 'VAL Witnessing Session workspace'
  });
  deskWorkspace.classList.add('witnessing-mode');
  renderValWitnessingConversation({
    card,
    rawResponse: resumeTarget?.rawResponse ?? workspaceInputValue('val-witnessing-' + card.category),
    state: resumeTarget?.state || (index === 0 ? 'intro' : 'question'),
    error: resumeTarget?.error || '',
    witness: resumeTarget?.witness || null
  });
  openWorkspaceShell('VAL Witnessing Session workspace', {returnTarget:'val'});
}

async function openValWitnessingQuestion(cardId = 'meeting_val', options = {}){
  const card = valWitnessingCard(cardId);
  if(card.id === 'source_review' && canUseApi && !mockScrapers){
    try{await loadValFirstLookRun();}
    catch(error){options.error = options.error || ('VAL could not check whether the First Look is ready: ' + error.message);}
  }
  renderValWitnessingConversation({
    card,
    rawResponse: workspaceInputValue('val-witnessing-' + card.category),
    state: 'question',
    error: options.error || ''
  });
  openWorkspaceShell('VAL Witnessing Session workspace', {returnTarget:'val'});
}

async function saveValWitnessingCard(category){
  const card = valWitnessingCard(category);
  const firstLookCard = valWitnessingCard('source_review');
  if(valWitnessingIndex(card) > valWitnessingIndex(firstLookCard) && !valFirstLookComplete()){
    try{await loadValFirstLookRun();}catch(_e){}
    if(!valFirstLookComplete()){
      await openValWitnessingQuestion('source_review', {error:'Before we continue, VAL needs to complete your First Look and show you the source receipt.'});
      return;
    }
  }
  const mode = 'val-witnessing-' + card.category;
  const rawResponse = workspaceInputValue(mode);
  if(!rawResponse){
    renderValWitnessingConversation({
      card,
      rawResponse,
      state: 'question',
      error: 'Share one thing first. It can be short.'
    });
    return;
  }
  setWorkspaceContent({
    lens: 'VAL Witnessing Session',
    title: card.title,
    meaning: "I'm listening.",
    understanding: [],
    recommendation: card.question,
    actions: [{label:'Back to VAL', workflow:'cancel:val'}],
    label: 'VAL Witnessing Session conversation'
  });
  deskWorkspace.classList.add('witnessing-mode');
  renderValWitnessingConversation({card, rawResponse, state:'thinking'});
  if(mockScrapers || !canUseApi){
    renderValWitnessingConversation({
      card,
      rawResponse,
      state: 'question',
      error: 'Live witnessing needs the VAL API connection. I will not use a canned VAL response here.'
    });
    openWorkspaceShell('VAL Witnessing Session workspace', {returnTarget:'val'});
    return;
  }
  if(!(await ensureOpenAIConnectionBeforeWitnessing(card.id,{resume:true}))) return;
  try{
    const sessionId = await ensureValWitnessingSession();
    const result = await postJson(
      '/api/teach-val/onboarding/' + encodeURIComponent(sessionId) + '/witnessing-cards/' + encodeURIComponent(card.id),
      {rawResponse},
      {
        timeoutMs:55000,
        timeoutMessage:'VAL took longer than expected. Your answer is still here. Please try again.'
      }
    );
    const witness = normalizeValWitnessingPayload(result?.witness || {}, rawResponse);
    valWitnessingState[card.category] = {rawResponse, witness, graph: result?.graph || null};
    const next = card.next ? valWitnessingCard(card.next) : null;
    if(next && witness.next_question){
      valWitnessingState[next.category] = {
        ...(valWitnessingState[next.category] || {}),
        questionOverride: witness.next_question
      };
    }
    if(result?.advance && next){
      setWorkspaceContent({
        lens: 'VAL Witnessing Session',
        title: next.title,
        meaning: "Let's look at this together.",
        understanding: [],
        recommendation: valWitnessingQuestionText(next),
        actions: [{label:'Back to VAL', workflow:'cancel:val'}],
        label: 'VAL Witnessing Session conversation'
      });
      deskWorkspace.classList.add('witnessing-mode');
      renderValWitnessingConversation({
        card: next,
        rawResponse: workspaceInputValue('val-witnessing-' + next.category),
        state: 'question'
      });
      hydrateValDrawer();
      openWorkspaceShell('VAL Witnessing Session workspace', {returnTarget:'val'});
      return;
    }
    renderValWitnessingConversation({card, rawResponse, state:'witnessed', witness});
    hydrateValDrawer();
  }catch(error){
    const message = /timed out|taking longer/i.test(error.message || '')
      ? 'VAL took longer than expected. Your answer is still here. Please try again.'
      : (error.message || "Live witnessing is unavailable. I will not use a canned VAL response here.");
    renderValWitnessingConversation({
      card,
      rawResponse,
      state: /Live observation model unavailable|Live witnessing model unavailable|Live next-question model unavailable|previous Witnessing Session flow|wrong question/i.test(error.message || '') ? 'paused' : 'question',
      error: message
    });
  }
  openWorkspaceShell('VAL Witnessing Session workspace', {returnTarget:'val'});
}

function skipValWitnessingToQuestion(cardId = 'meeting_val'){
  const card = valWitnessingCard(cardId);
  renderValWitnessingConversation({
    card,
    rawResponse: workspaceInputValue('val-witnessing-' + card.category),
    state: 'question'
  });
  openWorkspaceShell('VAL Witnessing Session workspace', {returnTarget:'val'});
}

async function confirmValWitnessingCard(category, confirmation = 'yes'){
  const card = valWitnessingCard(category);
  const firstLookCard = valWitnessingCard('source_review');
  if(card.id === 'source_review' || (valWitnessingIndex(card) > valWitnessingIndex(firstLookCard) && !valFirstLookComplete())){
    try{await loadValFirstLookRun();}catch(_e){}
    if(!valFirstLookComplete()){
      await openValWitnessingQuestion('source_review', {error:'Before we continue, VAL needs to complete your First Look and show you the source receipt.'});
      return;
    }
  }
  const rawResponse = workspaceInputPanel.querySelector('.val-conversation-answer p')?.textContent.trim() || workspaceInputValue('val-witnessing-' + card.category);
  valWitnessingState[card.category] = {
    ...(valWitnessingState[card.category] || {}),
    rawResponse,
    confirmation
  };
  if(canUseApi && !mockScrapers){
    if(confirmation === 'yes'){
      renderValWitnessingConversation({
        card,
        rawResponse,
        state:'shaping',
        witness:valWitnessingState[card.category]?.witness || null
      });
    }
    try{
      const sessionId = await ensureValWitnessingSession();
      const result = await postJson(
        '/api/teach-val/onboarding/' + encodeURIComponent(sessionId) + '/witnessing-cards/' + encodeURIComponent(card.id) + '/confirm',
        {confirmation},
        {timeoutMs:12000,timeoutMessage:'VAL is shaping the next question from what you just confirmed. Please try again.'}
      );
      const next = card.next ? valWitnessingCard(card.next) : null;
      const nextQuestion = String(result?.nextQuestion || '').trim();
      if(next && nextQuestion){
        valWitnessingState[next.category] = {
          ...(valWitnessingState[next.category] || {}),
          questionOverride:nextQuestion
        };
      }
    }catch(error){
      valWitnessingState[card.category].confirmationError = error.message;
    }
  }
  if(confirmation === 'clarify' || confirmation === 'mostly'){
    renderValWitnessingConversation({
      card,
      rawResponse,
      state: 'question',
      error: confirmation === 'mostly' ? 'Clarify the part I only mostly understood.' : 'Tell me what I missed.'
    });
    const input = workspaceInputPanel.querySelector('[data-workspace-input]');
    if(input) input.focus();
    return;
  }
  const next = card.next ? valWitnessingCard(card.next) : null;
  if(next){
    setWorkspaceContent({
      lens: 'VAL Witnessing Session',
      title: next.title,
      meaning: "Let's keep going slowly.",
      understanding: [],
      recommendation: valWitnessingQuestionText(next),
      actions: [{label:'Back to VAL', workflow:'cancel:val'}],
      label: 'VAL Witnessing Session conversation'
    });
    deskWorkspace.classList.add('witnessing-mode');
    renderValWitnessingConversation({
      card: next,
      rawResponse: workspaceInputValue('val-witnessing-' + next.category),
      state: 'question'
    });
  }else{
    const witness = valWitnessingState[card.category]?.witness || normalizeValWitnessingPayload({}, rawResponse);
    let completionResult = {};
    if(canUseApi && !mockScrapers){
      try{
        const sessionId = await ensureValWitnessingSession();
        completionResult = await postJson('/api/teach-val/onboarding/' + encodeURIComponent(sessionId) + '/commit', {testMode:false});
      }catch(error){
        completionResult = {error:error.message};
      }
    }
    renderValWitnessingConversation({card, rawResponse, state:'complete', witness: completionResult || witness});
  }
  openWorkspaceShell('VAL Witnessing Session workspace', {returnTarget:'val'});
}

